package com.atlas;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(WealthSync.GROUP)
public interface AtlasConfig extends Config
{
    @ConfigItem(keyName = "syncExperimental", name = "Cross-device sync",
        description = "Share bank and completed-session history through your RuneLite account. Keeps local backups.")
    default boolean syncExperimental() { return false; }

    @ConfigItem(keyName = "showSessionValue", name = "Show session value",
        description = "Show session gains/losses above the inventory tab. Tracking continues when hidden.")
    default boolean showSessionValue() { return true; }
}

package com.atlas;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.ArrayList;
import java.util.List;
import java.util.HashSet;
import java.util.Set;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicLong;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ChatMessageType;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.Item;
import net.runelite.api.MenuAction;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.ItemQuantityChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.SessionOpen;
import net.runelite.client.events.SessionClose;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(name = "Atlas", internalName = "atlas",
    description = "Track bank value, net worth and session gains/losses with optional cross-device history sync",
    tags = {"bank", "wealth", "net worth", "profit", "loss", "session", "history", "equipment"})
public class AtlasPlugin extends Plugin
{
    private static final long SAMPLE_INTERVAL = 5 * 60_000L;
    private static final java.util.regex.Pattern MINED_GEM = java.util.regex.Pattern.compile(
        "You just (?:found|mined) (?:a|an) (?:piece of )?([A-Za-z ]+)!", java.util.regex.Pattern.CASE_INSENSITIVE);
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ItemManager itemManager;
    @Inject private ConfigManager configManager;
    @Inject private AtlasConfig config;
    @Inject private ClientToolbar toolbar;
    @Inject private ScheduledExecutorService executor;
    @Inject private Gson gson;
    @Inject private OverlayManager overlayManager;

    private volatile boolean active;
    private volatile long generation;
    private volatile long lifetime;
    // Local cancellation token only; RuneLite owns account credentials and cloud delivery.
    private final AtomicLong syncContext = new AtomicLong();
    private WealthPanel panel;
    private NavigationButton navigation;
    private InventorySessionOverlay inventorySessionOverlay;
    private WealthStore store;
    private CompletableFuture<Void> ioTail = CompletableFuture.completedFuture(null);
    private Filepath directory;
    // All fields below are only accessed on RuneLite's client thread.
    private String profile;
    private Wealth.State saved;
    private Wealth.Snapshot live;
    private SessionTracker session;
    private long lastSessionSave;
    private String syncDeviceId;
    private boolean syncBusy;
    private boolean syncFlushRequested;
    private long lastSyncAttempt;
    private String syncMessage = "History saved on this device. Not synced.";
    private Map<Integer, Long> quotes = new HashMap<>();
    private Map<Integer, Long> pouchContents = new HashMap<>();
    private final HerbSackTracker herbSack = new HerbSackTracker();
    private final CannonTracker cannon = new CannonTracker();
    private final SoulBearerTracker soulBearer = new SoulBearerTracker();
    private long soulBearerSpent;
    private final Map<Integer, Long> soulBearerTransfers = new HashMap<>();
    private boolean sackPresent;
    private final List<BagTracker> bags = new ArrayList<>();
    private final Set<BagTracker.Kind> presentBags = new HashSet<>();
    private int pickupId = -1, pickupTick;
    private WorldPoint pickupTile;
    private final ContainerTransfer bulkDeposit = new ContainerTransfer();
    private final Set<BagTracker.Kind> bulkEligibleBags = new HashSet<>();
    private boolean bulkHerbs;
    private Map<Integer, Long> bulkBeforeStored = new HashMap<>();
    private final HoldingsTracker containers = new HoldingsTracker(
        id -> SoulBearerTracker.canonicalHead(itemManager.canonicalize(id)),
        id -> itemManager.getItemComposition(id).getPlaceholderTemplateId() != -1);
    private boolean loading, storageFailed, bankSynced, dirty;
    private long bankTime, lastCapture;
    private int ticks, settleUntil;
    private int seedViewSince = -1;
    private int lastCannonStage = -1;
    private boolean lastCannonDecayed;

    @Provides
    AtlasConfig provideConfig(ConfigManager manager) { return manager.getConfig(AtlasConfig.class); }

    @Override
    protected void startUp()
    {
        active = true;
        syncContext.incrementAndGet();
        long version = ++lifetime;
        store = new WealthStore(gson);
        inventorySessionOverlay = new InventorySessionOverlay(client, config);
        overlayManager.add(inventorySessionOverlay);
        bags.clear();
        for (BagTracker.Kind kind : BagTracker.Kind.values())
        {
            bags.add(new BagTracker(kind, this::resolveItem, id ->
            {
                String name = itemManager.getItemComposition(id).getName().toLowerCase(java.util.Locale.ROOT);
                return name.contains("seed") || name.contains("spore") || name.equals("frags");
            }));
        }
        SwingUtilities.invokeLater(() ->
        {
            if (!active || lifetime != version) { return; }
            panel = new WealthPanel(itemManager, () -> clientThread.invoke(this::manualSnapshot),
                () -> clientThread.invoke(this::syncHistoryNow));
            navigation = NavigationButton.builder().tooltip("Atlas")
                .icon(icon()).priority(6).panel(panel).build();
            toolbar.addNavigation(navigation);
        });
        clientThread.invoke(() -> { if (active) { resetSession(); } });
    }

    @Override
    protected void shutDown()
    {
        active = false;
        ++lifetime;
        ++generation;
        if (inventorySessionOverlay != null)
        {
            overlayManager.remove(inventorySessionOverlay);
            inventorySessionOverlay = null;
        }
        // Saves use the shared executor and immutable state; no blocking shutdown or lost final task.
        clientThread.invoke(() ->
        {
            finishSession();
            recordLive();
            resetSession();
        });
        SwingUtilities.invokeLater(() ->
        {
            if (navigation != null) { toolbar.removeNavigation(navigation); navigation = null; }
            if (panel != null) { panel.close(); panel = null; }
        });
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGIN_SCREEN)
        {
            finishSession();
            recordLive();
            resetSession();
            publish("Log in to resume live inventory and equipment tracking.");
        }
        else if (event.getGameState() == GameState.HOPPING)
        {
            herbSack.cancelTransfer();
            bags.forEach(BagTracker::cancelTransfer);
            pickupTile = null;
            bulkDeposit.cancel();
            soulBearer.cancel();
            // Hopping worlds preserves the login session and its fixed prices.
            recordLive();
            bankSynced = false;
            dirty = true;
            settleUntil = ticks + 2;
        }
    }

    @Subscribe
    public void onClientShutdown(ClientShutdown event)
    {
        CompletableFuture<Void> flushed = new CompletableFuture<>();
        event.waitFor(flushed);
        clientThread.invoke(() ->
        {
            try
            {
                finishSession();
                recordLive();
                ioTail.whenComplete((ignored, error) ->
                {
                    if (error == null) { flushed.complete(null); }
                    else { flushed.completeExceptionally(error); }
                });
            }
            catch (RuntimeException ex) { flushed.completeExceptionally(ex); }
        });
    }

    private void resetSession()
    {
        ++generation;
        profile = null;
        saved = null;
        live = null;
        session = null;
        syncBusy = false; syncFlushRequested = false; lastSyncAttempt = 0; syncDeviceId = null;
        if (inventorySessionOverlay != null) { inventorySessionOverlay.update(null); }
        lastSessionSave = 0;
        quotes = new HashMap<>();
        pouchContents = new HashMap<>();
        herbSack.reset();
        cannon.reset(); lastCannonStage = -1; lastCannonDecayed = false;
        soulBearer.cancel(); soulBearerSpent = 0; soulBearerTransfers.clear();
        sackPresent = false;
        bags.forEach(BagTracker::reset);
        presentBags.clear();
        pickupTile = null;
        bulkDeposit.cancel(); bulkEligibleBags.clear(); bulkHerbs = false;
        bulkBeforeStored.clear();
        containers.reset();
        bankSynced = false;
        loading = false;
        storageFailed = false;
        dirty = true;
        bankTime = 0;
        lastCapture = 0;
        seedViewSince = -1;
        settleUntil = ticks + 2;
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (!active || loading || saved == null || storageFailed
            || (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)) { return; }
        String message = Text.removeTags(event.getMessage()).trim();
        if (herbSack.chat(message))
        {
            dirty = true;
            checkpointHerbSack();
        }
        for (BagTracker bag : bags)
        {
            if (bag.chat(message, ticks)) { dirty = true; checkpointExtraContainers(); }
        }
        java.util.regex.Matcher mined = MINED_GEM.matcher(message);
        if (mined.matches()) { queueGem(BagTracker.gemId(mined.group(1)), 1); }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (!active || loading || saved == null || storageFailed) { return; }
        pickupTile = null;
        if (event.getMenuAction() == MenuAction.GROUND_ITEM_THIRD_OPTION && event.getMenuOption().equals("Take")
            && BagTracker.gemId(itemManager.getItemComposition(event.getId()).getName()) > 0)
        {
            pickupId = event.getId(); pickupTick = ticks;
            pickupTile = WorldPoint.fromScene(client, event.getParam0(), event.getParam1(), client.getPlane());
        }
        String target = Text.removeTags(event.getMenuTarget()).toLowerCase(java.util.Locale.ROOT);
        Item[] inventory = items(InventoryID.INV);
        Item[] bank = isBankOpen() ? items(InventoryID.BANK) : null;
        // Finish a successful earlier action before another click replaces its baseline.
        settleStorageTransfers();
        if (event.getMenuAction() == MenuAction.WIDGET_TARGET_ON_WIDGET)
        {
            Widget selected = client.getSelectedWidget();
            int selectedId = inventoryItemId(selected, inventory);
            int targetId = event.getItemId() > 0 ? event.getItemId() : inventoryItemId(event.getWidget(), inventory);
            soulBearer.use(selectedId, targetId, inventory, bank, ticks);
            int containerId = ContainerUse.container(selectedId, targetId);
            int storedId = ContainerUse.storedItem(selectedId, targetId);
            if (HerbSackTracker.isSack(containerId)) { herbSack.beginItemUse(storedId, inventory, bank, ticks); }
            for (BagTracker bag : bags)
            { if (bag.kind.owns(containerId)) { bag.beginItemUse(storedId, inventory, bank, ticks); } }
            // Do not pass "Use" through the ordinary menu path: it would cancel this transfer.
            return;
        }
        soulBearer.menu(event.getMenuOption(), event.getItemId(), inventory, bank, ticks);
        int component = event.getParam1();
        if (inventory != null && bank != null && (component == InterfaceID.Bankmain.DEPOSITCONTAINERS
            || component == InterfaceID.Bankmain.DEPOSITCONTAINERS_GRAPHIC || component == InterfaceID.Bankmain.DEPOSITINV
            || component == InterfaceID.Bankmain.DEPOSITINV_GRAPHIC))
        {
            bulkEligibleBags.clear(); bulkHerbs = false;
            for (Item item : inventory)
            {
                if (item.getQuantity() <= 0) { continue; }
                bulkHerbs |= HerbSackTracker.isSack(item.getId());
                for (BagTracker bag : bags)
                { if (bag.kind.owns(item.getId())) { bulkEligibleBags.add(bag.kind); } }
            }
            herbSack.cancelTransfer(); bags.forEach(BagTracker::cancelTransfer);
            bulkBeforeStored = BagTracker.combinedContents(herbSack, bulkHerbs, bags, bulkEligibleBags);
            bulkDeposit.begin("Empty", inventory, bank, ticks, id -> true);
            return;
        }
        if (HerbSackTracker.isSack(event.getItemId()) || target.contains("herb sack"))
        { herbSack.beginTransfer(event.getMenuOption(), inventory, bank, ticks); }
        for (BagTracker bag : bags)
        {
            if (bag.kind.owns(event.getItemId()) || target.contains(bag.kind.name)
                || (bag.kind.seeds() && WidgetUtil.componentToInterface(event.getParam1()) == InterfaceID.HOSIDIUS_SEEDBOX))
            { bag.menu(event.getMenuOption(), inventory, bank, ticks); }
        }
    }

    @Subscribe
    public void onItemDespawned(ItemDespawned event)
    { matchGemPickup(event.getItem().getId(), event.getItem().getQuantity(), event.getTile().getWorldLocation()); }

    @Subscribe
    public void onItemQuantityChanged(ItemQuantityChanged event)
    { matchGemPickup(event.getItem().getId(), event.getOldQuantity() - event.getNewQuantity(), event.getTile().getWorldLocation()); }

    private void matchGemPickup(int id, int quantity, WorldPoint tile)
    {
        if (!active || pickupTile == null || quantity <= 0 || ticks - pickupTick > 20 || id != pickupId
            || !pickupTile.equals(tile) || client.getLocalPlayer() == null
            || !tile.equals(client.getLocalPlayer().getWorldLocation())) { return; }
        pickupTile = null;
        queueGem(id, quantity);
    }

    private void queueGem(int id, long quantity)
    {
        Item[] inventory = items(InventoryID.INV);
        if (inventory == null || isBankOpen()) { return; }
        for (BagTracker bag : bags)
        {
            if (bag.canAcquire(id, inventory)) { bag.candidate(id, quantity); return; }
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        int id = event.getContainerId();
        if (id == InventoryID.INV && active && !loading && saved != null && !storageFailed)
        {
            // Confirm remote sends before a quick bank opening replaces the cached bank.
            settleSoulBearer(items(InventoryID.INV), isBankOpen() ? items(InventoryID.BANK) : null);
        }
        if (id == InventoryID.SEED_BOX && active && !loading && saved != null && !storageFailed)
        {
            Widget seedBox = client.getWidget(InterfaceID.HosidiusSeedbox.UNIVERSE);
            if (seedBox != null && !seedBox.isHidden() && event.getItemContainer() != null)
            {
                for (BagTracker bag : bags)
                { if (bag.kind.seeds()) { bag.observeSeeds(event.getItemContainer().getItems()); } }
                checkpointExtraContainers(); dirty = true; settleUntil = ticks + 2;
            }
        }
        if (id == InventoryID.BANK || id == InventoryID.INV || id == InventoryID.WORN)
        {
            dirty = true;
            settleUntil = ticks + 2;
            if (id == InventoryID.BANK && isBankOpen() && event.getItemContainer() != null)
            {
                // Preserve the latest withdrawal/deposit even if the bank closes before the next tick.
                containers.observeBank(event.getItemContainer().getItems(), System.currentTimeMillis());
                bankTime = containers.getBankTime();
                bankSynced = true;
                checkpointBank();
            }
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        ++ticks;
        if (!active || client.getGameState() != GameState.LOGGED_IN) { return; }
        String rsProfile = configManager.getRSProfileKey();
        if (rsProfile == null) { return; }
        String key = profileKey(rsProfile);
        if (!key.equals(profile))
        {
            finishSession();
            recordLive();
            resetSession();
            profile = key;
            loadProfile(key);
        }
        if (loading || storageFailed || saved == null) { return; }
        int cannonStage = client.getVarpValue(VarPlayerID.DROPCANNON);
        boolean cannonDecayed = client.getVarbitValue(VarbitID.MCANNON_DECAYED) == 1;
        if (cannonStage != lastCannonStage || cannonDecayed != lastCannonDecayed)
        {
            lastCannonStage = cannonStage; lastCannonDecayed = cannonDecayed;
            dirty = true; settleUntil = ticks + 2;
        }
        Widget seedView = client.getWidget(InterfaceID.HosidiusSeedbox.UNIVERSE);
        if (seedView == null || seedView.isHidden()) { seedViewSince = -1; }
        else
        {
            if (seedViewSince < 0) { seedViewSince = ticks; }
            Item[] seeds = items(InventoryID.SEED_BOX);
            if (ticks >= seedViewSince + 2 && seeds != null)
            {
                for (BagTracker bag : bags)
                {
                    if (bag.kind.seeds() && bag.observeSeeds(seeds)) { dirty = true; checkpointExtraContainers(); }
                }
            }
        }
        if (herbSack.finishCheck())
        {
            dirty = true;
            checkpointHerbSack();
        }
        for (BagTracker bag : bags)
        {
            if (bag.finishCheck(ticks)) { dirty = true; checkpointExtraContainers(); }
        }
        Item[] inventoryItems = items(InventoryID.INV);
        if (inventoryItems != null)
        {
            for (BagTracker bag : bags)
            { if (bag.settleAcquisitions(inventoryItems)) { dirty = true; checkpointExtraContainers(); } }
        }
        if (ticks >= settleUntil)
        {
            settleStorageTransfers();
        }
        // Pouch consumption changes varbits without necessarily changing any item container.
        // Read after each tick's server updates; do not restart the container settling timer.
        EnumComposition runeTypes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
        Map<Integer, Long> contents = RunePouchContents.read(client::getVarbitValue, runeTypes::getIntValue);
        if (!contents.equals(pouchContents)) { pouchContents = contents; dirty = true; }
        ItemContainer bank = isBankOpen() ? client.getItemContainer(InventoryID.BANK) : null;
        if (!bankSynced && bank != null)
        {
            containers.observeBank(bank.getItems(), System.currentTimeMillis());
            bankSynced = true;
            bankTime = containers.getBankTime();
            dirty = true;
            settleUntil = ticks + 2;
        }
        long now = System.currentTimeMillis();
        if (ticks >= settleUntil && (dirty || now - lastCapture >= 15_000))
        {
            capture(now);
        }
        if (live != null && containers.hasBank() && (saved.latest == null || now - saved.latest.time >= SAMPLE_INTERVAL))
        {
            recordLive();
            publish(trackingStatus());
        }
        if (now - lastSyncAttempt >= 60_000) { requestHistorySync(false); }
    }

    private void loadProfile(String key)
    {
        loading = true;
        session = new SessionTracker(System.currentTimeMillis());
        long version = generation;
        WealthStore targetStore = store;
        String rsKey = configManager.getRSProfileKey();
        long syncVersion = syncContext.get();
        publish("Loading this character's history...");
        enqueueIO(() ->
        {
            try
            {
                Filepath root = getPluginDirectory();
                Wealth.State local = targetStore.load(root, key).closeSession(true);
                Wealth.State loaded = local;
                String device = null;
                String syncNote = "History saved on this device. Not synced.";
                try
                {
                    device = targetStore.deviceId(root);
                    if (config.syncExperimental() && syncContext.get() == syncVersion)
                    {
                        targetStore.backupBeforeSync(root, loaded);
                        loaded = mergeHistoryCopies(loaded, rsKey, true);
                        syncNote = "History prepared for RuneLite sync. Delivery is handled by RuneLite.";
                    }
                }
                catch (IOException | IllegalArgumentException ex)
                {
                    log.debug("Unable to prepare history sync", ex);
                    syncNote = "Sync paused. Local history kept; check the client log.";
                }
                Wealth.State initial = loaded;
                String initialDevice = device, initialSyncNote = syncNote;
                clientThread.invoke(() ->
                {
                    if (!active || generation != version || !key.equals(profile)) { return; }
                    directory = root;
                    // A prior unfinished entry is closed at its last checkpoint, never merged into a new login.
                    Wealth.State restored = syncContext.get() == syncVersion ? initial : local;
                    saved = restored;
                    syncDeviceId = initialDevice;
                    syncMessage = syncContext.get() == syncVersion ? initialSyncNote
                        : "History saved locally. RuneLite manages sign-in and sync delivery.";
                    containers.restoreBank(restored.bank);
                    containers.restoreRemoteBank(restored.extraContainers.get(SoulBearerTracker.REMOTE_BANK_KEY));
                    herbSack.restore(restored.herbSack);
                    cannon.restore(restored.extraContainers.get(CannonTracker.STORAGE_KEY));
                    for (BagTracker bag : bags) { bag.restore(restored.extraContainers.get(bag.kind.name())); }
                    bankTime = containers.getBankTime();
                    loading = false;
                    dirty = true;
                    settleUntil = ticks + 2;
                    checkpointBank();
                    persist(saved);
                    publish("Updating live inventory and equipment...");
                });
            }
            catch (IOException ex)
            {
                log.debug("Unable to load net worth history", ex);
                clientThread.invoke(() ->
                {
                    if (!active || generation != version) { return; }
                    loading = false;
                    storageFailed = true;
                    publish("Cannot read history. Original file kept; tracking paused.");
                });
            }
        });
    }

    private boolean capture(long now)
    {
        if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null) { return false; }
        lastCapture = now;
        // Bank data is only refreshed while observed. A closed/missing bank must not block live gear updates.
        ItemContainer bank = isBankOpen() ? client.getItemContainer(InventoryID.BANK) : null;
        if (bank != null)
        {
            containers.observeBank(bank.getItems(), now);
            bankSynced = true;
            checkpointBank();
        }
        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
        Item[] inventoryItems = inventory == null ? new Item[0] : inventory.getItems();
        Map<Integer, long[]> quantities = containers.combine(
            inventoryItems,
            equipment == null ? null : equipment.getItems());
        cannon.observe(client.getVarpValue(VarPlayerID.DROPCANNON),
            client.getVarbitValue(VarbitID.MCANNON_DECAYED) == 1, inventoryItems, itemManager::canonicalize);
        checkpointExtraContainers();
        cannon.deployed().forEach((id, quantity) -> quantities.computeIfAbsent(id, ignored -> new long[3]));
        Map<Integer, Long> bankPouch = RunePouchContents.include(quantities, pouchContents);
        boolean hasSack = HerbSackTracker.location(quantities) >= 0;
        if (sackPresent && !hasSack) { herbSack.invalidate(); }
        sackPresent = hasSack;
        Map<Integer, Long> bankSack = new LinkedHashMap<>(herbSack.include(quantities));
        for (BagTracker bag : bags)
        {
            boolean present = bag.location(quantities) >= 0;
            if (!present && presentBags.remove(bag.kind)) { bag.invalidate(); }
            if (present) { presentBags.add(bag.kind); }
            bag.include(quantities).forEach((id, quantity) -> bankSack.merge(id, quantity, Long::sum));
        }
        bankTime = containers.getBankTime();
        if (itemManager.search("rune").isEmpty())
        {
            publish("Waiting for RuneLite's GE price list. Previous balance kept.");
            return false;
        }
        Map<Integer, Wealth.Entry> entries = new LinkedHashMap<>();
        Map<Integer, Long> newQuotes = new HashMap<>();
        for (Map.Entry<Integer, long[]> holding : quantities.entrySet())
        {
            int id = holding.getKey();
            ItemComposition definition = itemManager.getItemComposition(id);
            long price = quote(id);
            newQuotes.put(id, price);
            long alch = id == ItemID.COINS ? 1 : id == ItemID.PLATINUM ? 1000 : definition.getHaPrice();
            long[] q = holding.getValue();
            entries.put(id, new Wealth.Entry(id, definition.getName(), q[0], q[1], q[2], price, alch,
                definition.isMembers(), definition.isTradeable() || definition.isGeTradeable(), price == 0,
                bankPouch.getOrDefault(id, 0L), bankSack.getOrDefault(id, 0L), cannon.deployed().getOrDefault(id, 0L)));
        }
        // Sold/removed items still need TODAY'S price to attribute their interval accurately.
        if (saved.latest != null)
        {
            for (Wealth.Entry old : saved.latest.items.values())
            {
                if (!newQuotes.containsKey(old.id)) { newQuotes.put(old.id, quote(old.id)); }
            }
        }
        quotes = newQuotes;
        live = new Wealth.Snapshot(now, bankTime, entries);
        updateSession(now);
        dirty = false;
        publish(trackingStatus());
        return true;
    }

    private long quote(int id)
    {
        long price = itemManager.getItemPriceWithSource(id, false);
        // A temporarily missing quote must not invent a loss for previously priced holdings.
        if (price <= 0 && saved.latest != null)
        {
            Wealth.Entry old = saved.latest.items.get(id);
            if (old != null) { return old.price; }
        }
        return Math.max(0, price);
    }

    private boolean isBankOpen()
    {
        Widget bank = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
        return bank != null && !bank.isHidden();
    }

    private void manualSnapshot()
    {
        if (!active || !containers.hasBank() || loading || storageFailed || client.getGameState() != GameState.LOGGED_IN)
        { publish("Inventory/equipment can update now. Open your bank once to start net-worth history."); return; }
        if (ticks < settleUntil) { publish("Items are moving; wait a moment, then record."); return; }
        settleStorageTransfers();
        if (!capture(System.currentTimeMillis())) { return; }
        recordLive();
        publish("Snapshot recorded locally. " + trackingStatus());
    }

    private void recordLive()
    {
        if (saved == null || live == null || live.bankTime == 0 || !containers.hasBank() || directory == null || storageFailed) { return; }
        if (saved.latest != null && live.time <= saved.latest.time) { return; }
        saved = saved.append(live, quotes);
        persist(saved);
    }

    /** Persist observed bank changes even when a graph point is not due yet. */
    private void checkpointBank()
    {
        if (saved == null || directory == null || storageFailed || !containers.hasBank()) { return; }
        Wealth.Bank bank = containers.bankSnapshot();
        if (saved.bank != null && saved.bank.quantities.equals(bank.quantities)) { return; }
        saved = saved.withBank(bank);
        persist(saved);
    }

    private void updateSession(long now)
    {
        if (session == null || saved == null) { return; }
        Wealth.Session before = saved.activeSession;
        if (sackPresent && !herbSack.confirmed()) { session.markEstimated(); }
        if (cannon.estimated()) { session.markEstimated(); }
        boolean reconcile = herbSack.takeReconciliation() | cannon.takeReconciliation();
        for (BagTracker bag : bags)
        {
            if (presentBags.contains(bag.kind) && bag.estimated()) { session.markEstimated(); }
            reconcile |= bag.takeReconciliation();
        }
        if (soulBearerSpent > 0)
        {
            session.spend(ItemID.BLOODRUNE, soulBearerSpent, quote(ItemID.BLOODRUNE));
            session.spend(ItemID.SOULRUNE, soulBearerSpent, quote(ItemID.SOULRUNE));
        }
        session.observe(live, bankSynced, reconcile, soulBearerTransfers);
        soulBearerSpent = 0; soulBearerTransfers.clear();
        Wealth.Session current = session.current();
        saved = saved.withActiveSession(current);
        if (before == null || current.change != before.change || current.estimated != before.estimated
            || now - lastSessionSave >= 60_000)
        {
            persist(saved);
            lastSessionSave = now;
        }
    }

    private void finishSession()
    {
        if (saved != null && saved.activeSession != null && directory != null && !storageFailed)
        {
            recordLive();
            saved = saved.closeSession(false);
            persist(saved);
            exportClosedHistory(saved);
        }
        session = null;
    }

    private void checkpointHerbSack()
    {
        if (saved == null || directory == null || storageFailed || herbSack.contents() == null) { return; }
        if (herbSack.contents().equals(saved.herbSack)) { return; }
        saved = saved.withHerbSack(herbSack.contents());
        persist(saved);
    }

    private Item[] items(int container)
    {
        ItemContainer items = client.getItemContainer(container);
        return items == null ? null : items.getItems();
    }

    private static int inventoryItemId(Widget widget, Item[] inventory)
    {
        if (widget == null) { return -1; }
        return ContainerUse.inventoryItem(widget.getId(), widget.getItemId(), widget.getIndex(), inventory);
    }

    private void settleStorageTransfers()
    {
        Item[] inventory = items(InventoryID.INV);
        Item[] bank = isBankOpen() ? items(InventoryID.BANK) : null;
        settleSoulBearer(inventory, bank);
        Map<Integer, Long> bulkChanges = bulkDeposit.finish(inventory, bank, ticks, id -> true);
        if (!bulkChanges.isEmpty())
        {
            BagTracker.settleBulkDeposit(bulkChanges, bulkBeforeStored, herbSack, bulkHerbs, bags, bulkEligibleBags);
            dirty = true; checkpointHerbSack(); checkpointExtraContainers();
        }
        if (herbSack.finishTransfer(inventory, bank, ticks)) { dirty = true; checkpointHerbSack(); }
        for (BagTracker bag : bags)
        { if (bag.finishTransfer(inventory, bank, ticks)) { dirty = true; checkpointExtraContainers(); } }
    }

    private void settleSoulBearer(Item[] inventory, Item[] bank)
    {
        SoulBearerTracker.Result carried = soulBearer.finish(inventory, bank, ticks);
        if (!carried.heads.isEmpty())
        {
            containers.creditBank(carried.heads);
            soulBearerSpent += carried.spent();
            checkpointBank(); checkpointExtraContainers(); dirty = true;
        }
        if (carried.chargeTransfer != 0)
        {
            soulBearerTransfers.merge(ItemID.BLOODRUNE, carried.chargeTransfer, Long::sum);
            soulBearerTransfers.merge(ItemID.SOULRUNE, carried.chargeTransfer, Long::sum);
            dirty = true;
        }
    }

    private int resolveItem(String name)
    {
        String itemName = name.trim().replaceAll("\\.$", "");
        for (net.runelite.http.api.item.ItemPrice item : itemManager.search(itemName))
        { if (item.getName().equalsIgnoreCase(itemName)) { return item.getId(); } }
        return -1;
    }

    private void checkpointExtraContainers()
    {
        if (saved == null || directory == null || storageFailed) { return; }
        Map<String, Map<Integer, Long>> contents = new LinkedHashMap<>(saved.extraContainers);
        contents.put(SoulBearerTracker.REMOTE_BANK_KEY, containers.remoteBankSnapshot());
        contents.put(CannonTracker.STORAGE_KEY, cannon.deployed());
        for (BagTracker bag : bags)
        { if (bag.contents() != null) { contents.put(bag.kind.name(), bag.contents()); } }
        if (contents.equals(saved.extraContainers)) { return; }
        saved = saved.withExtraContainers(contents);
        persist(saved);
    }

    private void persist(Wealth.State copy)
    {
        Filepath root = directory;
        WealthStore targetStore = store;
        long version = generation;
        enqueueIO(() ->
        {
            try { targetStore.save(root, copy); }
            catch (IOException ex)
            {
                log.debug("Unable to save net worth history", ex);
                clientThread.invoke(() ->
                {
                    if (active && generation == version) { storageFailed = true; publish("History could not be saved. Tracking paused."); }
                });
            }
        });
    }

    private void publish(String status)
    {
        Wealth.Snapshot snapshot = live != null ? live : saved == null ? null : saved.latest;
        Wealth.State state = saved;
        if (inventorySessionOverlay != null)
        { inventorySessionOverlay.update(state == null ? null : state.activeSession); }
        boolean canRecord = live != null && live.bankTime > 0 && containers.hasBank() && !storageFailed;
        boolean observed = bankSynced;
        long version = generation;
        boolean syncEnabled = config.syncExperimental();
        String syncStatus = !syncEnabled ? "History saved on this device. Not synced." : syncMessage;
        SwingUtilities.invokeLater(() ->
        {
            if (active && generation == version && panel != null)
            {
                panel.update(snapshot, state, canRecord, observed, status);
                panel.updateSync(syncStatus, syncEnabled);
            }
        });
    }

    private String trackingStatus()
    {
        String sackStatus = containerSyncStatus(items(InventoryID.INV), herbSack, bags);
        if (!containers.hasBank())
        { return "Inventory/equipment are live. Bank unknown; open it once to include it."
            + (sackStatus.isEmpty() ? "" : "<br>" + sackStatus); }
        if (!sackStatus.isEmpty()) { return sackStatus; }
        return bankSynced ? "Tracking bank + live inventory + equipment"
            : "Saved bank contents + live inventory/equipment. Open your bank when convenient to refresh.";
    }

    @Subscribe
    public void onSessionOpen(SessionOpen event) { onSyncAccountChanged(); }

    @Subscribe
    public void onSessionClose(SessionClose event) { onSyncAccountChanged(); }

    private void onSyncAccountChanged()
    {
        long context = syncContext.incrementAndGet();
        clientThread.invoke(() ->
        {
            if (!active || syncContext.get() != context) { return; }
            syncBusy = false;
            lastSyncAttempt = 0;
            syncMessage = "History saved locally. RuneLite manages sign-in and sync delivery.";
            requestHistorySync(false);
            publish(saved == null ? "Log in to load this character's history." : trackingStatus());
        });
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!WealthSync.GROUP.equals(event.getGroup())) { return; }
        if (event.getKey().equals("syncExperimental") || (event.getKey().startsWith(WealthSync.PREFIX)
            && !event.getKey().equals(WealthSync.PREFIX + syncDeviceId)))
        {
            clientThread.invoke(() ->
            {
                if (!active) { return; }
                requestHistorySync(false);
                publish(saved == null ? "Log in to load this character's history." : trackingStatus());
            });
        }
    }

    /** IO executor only. Each device writes its own key; older copies are merged, never substituted. */
    private Wealth.State mergeHistoryCopies(Wealth.State local, String rsKey, boolean importHoldings) throws IOException
    {
        List<String> keys = configManager.getRSProfileConfigurationKeys(WealthSync.GROUP, rsKey, WealthSync.PREFIX);
        if (keys.size() > 8) { throw new IOException("Too many device records for test sync"); }
        List<Wealth.State> copies = new ArrayList<>();
        for (String key : keys)
        {
            if (!key.matches(WealthSync.PREFIX + "[a-f0-9]{32}")) { throw new IOException("Invalid device record"); }
            String encoded = configManager.getConfiguration(WealthSync.GROUP, rsKey, key);
            if (encoded != null) { copies.add(WealthSync.decode(encoded, local.profile, gson)); }
        }
        return WealthSync.merge(local, copies, importHoldings);
    }

    private void requestHistorySync(boolean flush)
    {
        syncFlushRequested |= flush;
        if (!config.syncExperimental() || syncBusy || loading || saved == null || directory == null || storageFailed) { return; }
        lastSyncAttempt = System.currentTimeMillis();
        long syncVersion = syncContext.get();
        if (syncDeviceId == null) { return; }
        syncBusy = true;
        Wealth.State copy = saved;
        Filepath root = directory;
        String rsKey = configManager.getRSProfileKey(), device = syncDeviceId;
        long version = generation;
        enqueueIO(() ->
        {
            try
            {
                if (syncContext.get() != syncVersion) { return; }
                store.backupBeforeSync(root, copy);
                Wealth.State merged = mergeHistoryCopies(copy, rsKey, false);
                String encoded = WealthSync.encode(merged, gson);
                clientThread.invoke(() ->
                {
                    if (!active || generation != version || saved == null || syncContext.get() != syncVersion) { return; }
                    syncBusy = false;
                    if (!config.syncExperimental()) { return; }
                    if (saved.revision != copy.revision)
                    {
                        // Local loot arrived while merging. Retry from the new state instead of losing it.
                        lastSyncAttempt = 0;
                        return;
                    }
                    saved = merged;
                    persist(saved);
                    configManager.setConfiguration(WealthSync.GROUP, rsKey, WealthSync.PREFIX + device, encoded);
                    syncMessage = "History queued for RuneLite sync. Completed sessions are shared after logout.";
                    if (syncFlushRequested)
                    {
                        syncFlushRequested = false;
                        enqueueIO(() ->
                        {
                            if (config.syncExperimental() && syncContext.get() == syncVersion) { configManager.sendConfig(); }
                        });
                    }
                    publish(trackingStatus());
                });
            }
            catch (IOException | IllegalArgumentException ex)
            {
                log.debug("Unable to sync wealth history", ex);
                clientThread.invoke(() ->
                {
                    if (!active || generation != version || syncContext.get() != syncVersion) { return; }
                    syncBusy = false;
                    syncMessage = "Sync paused: " + ex.getMessage() + ". Local history kept.";
                    publish(trackingStatus());
                });
            }
        });
    }

    private void syncHistoryNow()
    {
        if (!config.syncExperimental())
        { publish("Enable cross-device sync in plugin settings first."); return; }
        long version = generation;
        long syncVersion = syncContext.get();
        syncMessage = "Preparing history for RuneLite sync. Sign in to RuneLite for cloud delivery.";
        publish(saved == null ? "Log in to sync this character's history." : trackingStatus());
        // Flush queued configuration; RuneLite handles authentication and delivery. Never block the client thread.
        enqueueIO(() ->
        {
            if (!config.syncExperimental() || syncContext.get() != syncVersion) { return; }
            configManager.sendConfig();
            clientThread.invoke(() ->
            {
                if (active && generation == version && syncContext.get() == syncVersion) { requestHistorySync(true); }
            });
        });
    }

    private void exportClosedHistory(Wealth.State closed)
    {
        if (!config.syncExperimental() || syncDeviceId == null || directory == null) { return; }
        long syncVersion = syncContext.get();
        Filepath root = directory;
        WealthStore targetStore = store;
        String rsKey = configManager.getRSProfileKey(), device = syncDeviceId;
        enqueueIO(() ->
        {
            try
            {
                if (!config.syncExperimental() || syncContext.get() != syncVersion) { return; }
                targetStore.backupBeforeSync(root, closed);
                Wealth.State merged = mergeHistoryCopies(closed, rsKey, false);
                String encoded = WealthSync.encode(merged, gson);
                targetStore.save(root, merged);
                if (!config.syncExperimental() || syncContext.get() != syncVersion) { return; }
                configManager.setConfiguration(WealthSync.GROUP, rsKey, WealthSync.PREFIX + device, encoded);
                // Flush this final session even if logout/reset changed the plugin's current profile.
                configManager.sendConfig();
            }
            catch (IOException | IllegalArgumentException ex) { log.debug("Unable to sync completed wealth session", ex); }
        });
    }

    /** Reminders concern carried containers only; banked contents remain part of valuation. */
    static String containerSyncStatus(Item[] inventory, HerbSackTracker herbs, List<BagTracker> bags)
    {
        if (inventory == null) { return ""; }
        Set<Integer> carried = new HashSet<>();
        boolean hasHerbs = false;
        for (Item item : inventory)
        {
            if (item.getQuantity() <= 0) { continue; }
            carried.add(item.getId());
            hasHerbs |= HerbSackTracker.isSack(item.getId());
        }
        StringBuilder list = new StringBuilder();
        if (hasHerbs && !herbs.confirmed()) { list.append("<br>• Herb Sack"); }
        for (BagTracker bag : bags)
        {
            if (!bag.confirmed() && (carried.contains(bag.kind.closed) || carried.contains(bag.kind.open)))
            {
                list.append("<br>•");
                for (String word : bag.kind.name.split(" "))
                { list.append(' ').append(Character.toUpperCase(word.charAt(0))).append(word.substring(1)); }
            }
        }
        return list.length() == 0 ? "" : "Check container to sync this session." + list;
    }

    /** Keep loads and atomic saves ordered, including a quick disable/re-enable. */
    private synchronized void enqueueIO(Runnable action)
    {
        ioTail = ioTail.handle((ignored, error) -> null).thenRunAsync(action, executor);
    }

    private static String profileKey(String profile)
    {
        try
        {
            byte[] bytes = MessageDigest.getInstance("SHA-256").digest(profile.getBytes(StandardCharsets.UTF_8));
            StringBuilder key = new StringBuilder();
            for (byte value : bytes) { key.append(String.format("%02x", value & 0xff)); }
            return key.toString();
        }
        catch (NoSuchAlgorithmException ex) { throw new IllegalStateException(ex); }
    }

    private static BufferedImage icon()
    {
        BufferedImage image = new BufferedImage(128, 128, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.scale(4, 4);
        Path2D needle = new Path2D.Double();
        needle.moveTo(16, 1);
        needle.lineTo(29.5, 29.5);
        needle.lineTo(21.5, 25);
        needle.lineTo(16, 12);
        needle.lineTo(10.5, 25);
        needle.lineTo(2.5, 29.5);
        needle.closePath();
        g.setColor(new Color(236, 188, 85));
        g.fill(needle);
        Path2D crossbar = new Path2D.Double();
        crossbar.moveTo(11, 20);
        crossbar.lineTo(21, 20);
        crossbar.lineTo(23, 24);
        crossbar.lineTo(9, 24);
        crossbar.closePath();
        g.setColor(new Color(255, 232, 172));
        g.fill(crossbar);
        g.dispose();
        BufferedImage icon = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
        g = icon.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
        g.drawImage(image, 0, 0, 32, 32, null);
        g.dispose();
        return icon;
    }
}

package com.atlas;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.List;
import java.util.Set;
import java.util.function.IntPredicate;
import java.util.function.ToIntFunction;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;

/** Separate contents for every gem container; seed names are resolved through the item cache. */
final class BagTracker
{
    enum Kind
    {
        GEM_BAG("gem bag", ItemID.GEM_BAG, ItemID.GEM_BAG_OPEN, 60, false),
        GEM_POUCH("gem pouch", ItemID.GEM_POUCH, ItemID.GEM_POUCH_OPEN, 5, true),
        GEM_SATCHEL("gem satchel", ItemID.GEM_SATCHEL, ItemID.GEM_SATCHEL_OPEN, 10, true),
        GEM_TOTE("gem tote", ItemID.GEM_TOTE, ItemID.GEM_TOTE_OPEN, 20, true),
        GEM_SACK("gem sack", ItemID.GEM_SACK, ItemID.GEM_SACK_OPEN, 60, true),
        SEED_BOX("seed box", ItemID.SEED_BOX, ItemID.SEED_BOX_OPEN, 0, false);

        final String name;
        final int closed, open, capacity;
        final boolean semiPrecious;
        Kind(String name, int closed, int open, int capacity, boolean semiPrecious)
        { this.name = name; this.closed = closed; this.open = open; this.capacity = capacity; this.semiPrecious = semiPrecious; }
        boolean owns(int id) { return id == closed || id == open; }
        boolean seeds() { return this == SEED_BOX; }
    }

    private static final Map<String, Integer> GEMS = new LinkedHashMap<>();
    static
    {
        GEMS.put("opal", ItemID.UNCUT_OPAL);
        GEMS.put("jade", ItemID.UNCUT_JADE);
        GEMS.put("red topaz", ItemID.UNCUT_RED_TOPAZ);
        GEMS.put("sapphire", ItemID.UNCUT_SAPPHIRE);
        GEMS.put("emerald", ItemID.UNCUT_EMERALD);
        GEMS.put("ruby", ItemID.UNCUT_RUBY);
        GEMS.put("diamond", ItemID.UNCUT_DIAMOND);
        GEMS.put("dragonstone", ItemID.UNCUT_DRAGONSTONE);
    }
    private static final Pattern SEED_LINE = Pattern.compile("([\\d,]+)\\s*x\\s*(.+?)\\.?$", Pattern.CASE_INSENSITIVE);
    private static final Pattern SEED_PICKUP = Pattern.compile("You put ([\\d,]+) x (.+?) straight into your open seed box\\.", Pattern.CASE_INSENSITIVE);
    private static final Pattern GEM_ADDED = Pattern.compile("You put a gem in your (gem (?:bag|pouch|satchel|tote|sack)): Uncut ([A-Za-z ]+)\\.?", Pattern.CASE_INSENSITIVE);
    final Kind kind;
    private final ToIntFunction<String> resolve;
    private final IntPredicate seedItem;
    private final ContainerTransfer transfer = new ContainerTransfer();
    private Map<Integer, Long> contents;
    private Map<Integer, Long> checking;
    private boolean checkResponse, confirmed, reconcile, inferred;
    private int checkTick;
    private final Map<Integer, Long> candidates = new LinkedHashMap<>();
    private final Map<Integer, Long> explicitAcquisitions = new LinkedHashMap<>();
    private Map<Integer, Long> previousInventory = new LinkedHashMap<>();

    BagTracker(Kind kind, ToIntFunction<String> resolve, IntPredicate seedItem)
    { this.kind = kind; this.resolve = resolve; this.seedItem = seedItem; }

    void reset()
    {
        contents = null; checking = null; confirmed = false; reconcile = false; inferred = false;
        cancelTransfer(); previousInventory.clear(); candidates.clear(); explicitAcquisitions.clear();
    }
    void restore(Map<Integer, Long> saved)
    { if (contents == null && saved != null) { contents = new LinkedHashMap<>(saved); } }
    Map<Integer, Long> contents() { return contents == null ? null : Collections.unmodifiableMap(contents); }
    boolean confirmed() { return confirmed; }
    long removeStored(int id, long quantity)
    {
        if (contents == null) { return 0; }
        long removed = Math.min(quantity, contents.getOrDefault(id, 0L));
        add(id, -removed);
        return removed;
    }

    static Map<Integer, Long> combinedContents(HerbSackTracker herbs, boolean includeHerbs,
        List<BagTracker> bags, Set<Kind> eligible)
    {
        Map<Integer, Long> result = new LinkedHashMap<>();
        if (includeHerbs && herbs.contents() != null) { result.putAll(herbs.contents()); }
        for (BagTracker bag : bags)
        {
            if (eligible.contains(bag.kind) && bag.contents != null)
            { bag.contents.forEach((id, quantity) -> result.merge(id, quantity, Long::sum)); }
        }
        return result;
    }

    static void settleBulkDeposit(Map<Integer, Long> looseChanges, Map<Integer, Long> beforeStored,
        HerbSackTracker herbs, boolean includeHerbs, List<BagTracker> bags, Set<Kind> eligible)
    {
        Map<Integer, Long> current = combinedContents(herbs, includeHerbs, bags, eligible);
        looseChanges.forEach((id, delta) ->
        {
            // An explicit "now empty" message may already have removed part of this bank gain.
            long alreadyRemoved = Math.max(0, beforeStored.getOrDefault(id, 0L) - current.getOrDefault(id, 0L));
            long remaining = Math.max(0, -delta - alreadyRemoved);
            if (includeHerbs) { remaining -= herbs.removeStored(id, remaining); }
            for (BagTracker bag : bags)
            { if (eligible.contains(bag.kind)) { remaining -= bag.removeStored(id, remaining); } }
            long original = beforeStored.getOrDefault(id, 0L);
            if (-delta < original && eligible.size() > 1)
            {
                // A shared partial bank delta cannot prove which overlapping bag kept each gem.
                for (BagTracker bag : bags)
                { if (eligible.contains(bag.kind) && bag.accepts(id)) { bag.invalidate(); } }
            }
        });
    }
    boolean estimated() { return !confirmed || inferred; }
    void invalidate() { confirmed = false; cancelTransfer(); }
    void cancelTransfer() { transfer.cancel(); }
    boolean takeReconciliation() { boolean result = reconcile; reconcile = false; return result; }

    boolean accepts(int id)
    {
        if (id <= 0) { return false; }
        if (kind.seeds()) { return seedItem.test(id); }
        if (!GEMS.containsValue(id)) { return false; }
        boolean semi = id == ItemID.UNCUT_OPAL || id == ItemID.UNCUT_JADE || id == ItemID.UNCUT_RED_TOPAZ;
        return kind == Kind.GEM_SACK || (kind.semiPrecious == semi);
    }

    void menu(String option, Item[] inventory, Item[] bank, int tick)
    {
        if (option.equalsIgnoreCase("Check"))
        {
            checking = new LinkedHashMap<>(); checkResponse = false; checkTick = tick;
        }
        transfer.begin(option, inventory, bank, tick, this::accepts);
    }

    void beginItemUse(int id, Item[] inventory, Item[] bank, int tick)
    {
        transfer.beginItemUse(id, inventory, bank, tick, this::accepts);
    }

    boolean finishTransfer(Item[] inventory, Item[] bank, int tick)
    {
        Map<Integer, Long> changes = transfer.finish(inventory, bank, tick, this::accepts);
        if (changes.isEmpty()) { return false; }
        changes.forEach(this::add);
        return true;
    }

    private void add(int id, long delta)
    {
        if (contents == null) { contents = new LinkedHashMap<>(); }
        long quantity = Math.max(0, contents.getOrDefault(id, 0L) + delta);
        if (quantity == 0) { contents.remove(id); } else { contents.put(id, quantity); }
    }

    boolean chat(String message, int tick)
    {
        String lower = message.toLowerCase(Locale.ROOT);
        if (kind.seeds())
        {
            if (lower.equals("the seed box contains:"))
            { checking = new LinkedHashMap<>(); checkResponse = true; checkTick = tick; return false; }
            if (lower.equals("the seed box is empty."))
            { checking = new LinkedHashMap<>(); checkResponse = true; checkTick = tick; return false; }
            if (lower.equals("your seed box is now empty."))
            { contents = new LinkedHashMap<>(); transfer.cancel(); confirmed = true; return true; }
            Matcher pickup = SEED_PICKUP.matcher(message);
            if (pickup.matches())
            {
                int id = resolve.applyAsInt(pickup.group(2));
                if (id > 0) { add(id, number(pickup.group(1))); return true; }
            }
            if (checking != null && checkResponse)
            {
                Matcher line = SEED_LINE.matcher(message);
                if (line.matches())
                {
                    int id = resolve.applyAsInt(line.group(2));
                    long quantity = number(line.group(1));
                    if (id > 0 && quantity > 0) { checking.put(id, quantity); }
                }
            }
            // Stored/Emptied messages accompany loose-container transfers. The diff is counted once.
            return false;
        }
        Matcher added = GEM_ADDED.matcher(message);
        if (added.matches() && added.group(1).equalsIgnoreCase(kind.name))
        {
            Integer id = GEMS.get(added.group(2).toLowerCase(Locale.ROOT));
            if (id != null && accepts(id) && !transfer.filling())
            { add(id, 1); explicitAcquisitions.merge(id, 1L, Long::sum); return true; }
        }
        Matcher stolen = Pattern.compile("(?:You put the stolen Uncut (.+?) into your |The following stolen loot gets added to your )"
            + Pattern.quote(kind.name) + "(?:\\.|: Uncut (.+?) x ([\\d,]+))", Pattern.CASE_INSENSITIVE).matcher(message);
        if (stolen.matches())
        {
            int id = gemId(stolen.group(1) != null ? stolen.group(1) : stolen.group(2));
            long quantity = stolen.group(3) == null ? 1 : number(stolen.group(3));
            if (accepts(id)) { add(id, quantity); explicitAcquisitions.merge(id, quantity, Long::sum); return true; }
        }
        if (checking != null && tick - checkTick <= 8)
        {
            for (Map.Entry<String, Integer> gem : GEMS.entrySet())
            {
                if (!accepts(gem.getValue())) { continue; }
                String plural = gem.getKey().equals("ruby") ? "ruby|rubies" : gem.getKey() + "s?";
                Matcher line = Pattern.compile("\\b(?:uncut )?(?:" + plural + ")\\s*:\\s*([\\d,]+)", Pattern.CASE_INSENSITIVE).matcher(message);
                if (line.find())
                {
                    long quantity = number(line.group(1));
                    if (quantity > 0) { checking.put(gem.getValue(), quantity); }
                    checkResponse = true;
                }
            }
            if (lower.equals("the " + kind.name + " is empty.") || lower.equals("the gem bag is empty."))
            { checkResponse = true; }
        }
        // Explicit server confirmations do not depend on the exact menu label.
        if (lower.equals("you empty your " + kind.name + " into the bank.")
            || lower.equals("the " + kind.name + " is now empty."))
        { contents = new LinkedHashMap<>(); transfer.cancel(); confirmed = true; return true; }
        return false;
    }

    boolean finishCheck(int tick)
    {
        if (checking == null) { return false; }
        if (tick - checkTick > 8) { checking = null; return false; }
        if (!checkResponse) { return false; }
        contents = checking; checking = null; confirmed = true; inferred = false; reconcile = true;
        transfer.cancel();
        return true;
    }

    boolean observeSeeds(Item[] items)
    {
        Map<Integer, Long> actual = new LinkedHashMap<>();
        for (Item item : items)
        { if (item.getId() > 0 && item.getQuantity() > 0) { actual.merge(item.getId(), (long) item.getQuantity(), Long::sum); } }
        if (confirmed && actual.equals(contents)) { return false; }
        reconcile |= !confirmed;
        contents = actual; confirmed = true; transfer.cancel();
        return true;
    }

    int location(Map<Integer, long[]> holdings)
    {
        int location = -1;
        for (Map.Entry<Integer, long[]> entry : holdings.entrySet())
        {
            if (!kind.owns(entry.getKey())) { continue; }
            if (entry.getValue()[1] > 0) { return 1; }
            if (entry.getValue()[0] > 0) { location = 0; }
        }
        return location;
    }

    Map<Integer, Long> include(Map<Integer, long[]> holdings)
    {
        int location = location(holdings);
        if (location < 0 || contents == null) { return Collections.emptyMap(); }
        contents.forEach((id, quantity) -> holdings.computeIfAbsent(id, ignored -> new long[3])[location] += quantity);
        return location == 0 ? contents : Collections.emptyMap();
    }

    boolean canAcquire(int id, Item[] inventory)
    {
        if (kind.seeds() || !confirmed || !accepts(id) || contents.getOrDefault(id, 0L) >= kind.capacity) { return false; }
        for (Item item : inventory) { if (item.getId() == kind.open && item.getQuantity() > 0) { return true; } }
        return false;
    }

    void candidate(int id, long quantity) { candidates.merge(id, quantity, Long::sum); }

    /** Mining and matched ground pickups can be inferred only when no loose gem was received. */
    boolean settleAcquisitions(Item[] inventory)
    {
        Map<Integer, Long> next = new LinkedHashMap<>();
        for (Item item : inventory)
        { if (accepts(item.getId()) && item.getQuantity() > 0) { next.merge(item.getId(), (long) item.getQuantity(), Long::sum); } }
        boolean changed = false;
        for (Map.Entry<Integer, Long> candidate : candidates.entrySet())
        {
            int id = candidate.getKey();
            long looseGain = Math.max(0, next.getOrDefault(id, 0L) - previousInventory.getOrDefault(id, 0L));
            long quantity = Math.min(kind.capacity - contents.getOrDefault(id, 0L), Math.max(0,
                candidate.getValue() - looseGain - explicitAcquisitions.getOrDefault(id, 0L)));
            if (quantity > 0 && canAcquire(id, inventory)) { add(id, quantity); inferred = true; changed = true; }
        }
        previousInventory = next; candidates.clear(); explicitAcquisitions.clear();
        return changed;
    }

    static int gemId(String name)
    { return GEMS.getOrDefault(name.toLowerCase(Locale.ROOT).replace("uncut ", "").trim(), -1); }
    private static long number(String quantity) { return Long.parseLong(quantity.replace(",", "")); }
}

package com.atlas;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;

/** The player's cannon assembly varp represents owned pieces outside the inventory. */
final class CannonTracker
{
    static final String STORAGE_KEY = "deployedCannon";
    private static final int[][] PARTS = {
        {ItemID.TWPART1, ItemID.LEAGUE_3_MULTICANNON_BASE},
        {ItemID.TWPART2, ItemID.LEAGUE_3_MULTICANNON_STAND},
        {ItemID.TWPART3, ItemID.LEAGUE_3_MULTICANNON_BARRELS},
        {ItemID.TWPART4, ItemID.LEAGUE_3_MULTICANNON_FURNACE}
    };
    private Map<Integer, Long> deployed = new LinkedHashMap<>();
    private Map<Integer, Long> previousInventory = new LinkedHashMap<>();
    private boolean estimated, reconcile;

    void reset()
    { deployed.clear(); previousInventory.clear(); estimated = false; reconcile = false; }

    void restore(Map<Integer, Long> saved)
    {
        if (saved == null || !deployed.isEmpty()) { return; }
        saved.forEach((id, quantity) -> { if (isPart(id) && quantity == 1) { deployed.put(id, 1L); } });
        estimated = !deployed.isEmpty();
    }

    Map<Integer, Long> deployed() { return Collections.unmodifiableMap(deployed); }
    boolean estimated() { return estimated; }
    boolean takeReconciliation() { boolean result = reconcile; reconcile = false; return result; }

    void observe(int assembly, boolean decayed, Item[] inventory, IntUnaryOperator canonicalize)
    {
        if (inventory == null || assembly < 0 || assembly > PARTS.length) { return; }
        Map<Integer, Long> currentInventory = new LinkedHashMap<>();
        for (Item item : inventory)
        {
            if (item.getId() < 0 || item.getQuantity() <= 0) { continue; }
            int id = canonicalize.applyAsInt(item.getId());
            if (isPart(id)) { currentInventory.merge(id, (long) item.getQuantity(), Long::sum); }
        }
        // A decayed cannon remains reclaimable; despawning from the scene is not a sale/loss.
        int count = decayed ? PARTS.length : assembly;
        Map<Integer, Long> next = new LinkedHashMap<>();
        boolean unknown = false;
        for (int component = 0; component < count; component++)
        {
            int chosen = -1;
            for (int variant : PARTS[component])
            { if (deployed.containsKey(variant)) { chosen = variant; break; } }
            if (chosen < 0)
            {
                for (int variant : PARTS[component])
                {
                    if (previousInventory.getOrDefault(variant, 0L) > currentInventory.getOrDefault(variant, 0L))
                    { chosen = variant; break; }
                }
            }
            if (chosen < 0)
            {
                // Login with a deployed cannon and no saved skin: use the ordinary piece as an estimate.
                chosen = PARTS[component][0]; unknown = true;
            }
            next.put(chosen, 1L);
        }
        if (estimated && count < deployed.size())
        {
            // Discovering a previously unknown skin on pickup is a correction, not earned GP.
            reconcile = currentInventory.entrySet().stream().anyMatch(item ->
                item.getValue() > previousInventory.getOrDefault(item.getKey(), 0L) && !deployed.containsKey(item.getKey()));
        }
        estimated = count > 0 && (unknown || estimated);
        deployed = next;
        previousInventory = currentInventory;
    }

    static boolean isPart(int id)
    {
        for (int[] variants : PARTS) { for (int variant : variants) { if (id == variant) { return true; } } }
        return false;
    }
}

package com.atlas;

import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.function.IntPredicate;
import net.runelite.api.Item;

/** A transfer changes loose quantities across BOTH locations, regardless of its menu label. */
final class ContainerTransfer
{
    private Map<Integer, Long> before;
    private boolean fill, includeBank;
    private int started;
    private int usedItem = -1;

    void cancel() { before = null; usedItem = -1; }
    boolean pending() { return before != null; }
    boolean filling() { return pending() && fill; }

    void begin(String option, Item[] inventory, Item[] bank, int tick, IntPredicate accepts)
    {
        cancel();
        String action = option.toLowerCase(Locale.ROOT).replace('-', ' ').trim();
        fill = action.equals("fill");
        if (inventory == null || !(fill || action.equals("empty") || action.equals("empty to bank")
            || action.startsWith("deposit") || action.startsWith("withdraw"))) { return; }
        includeBank = bank != null;
        before = count(inventory, includeBank ? bank : null, accepts);
        started = tick;
    }

    void beginItemUse(int id, Item[] inventory, Item[] bank, int tick, IntPredicate accepts)
    {
        cancel();
        if (id <= 0 || !accepts.test(id)) { return; }
        begin("Fill", inventory, bank, tick, accepts);
        if (!pending()) { return; }
        usedItem = id;
        before.keySet().removeIf(item -> item != id);
    }

    Map<Integer, Long> finish(Item[] inventory, Item[] bank, int tick, IntPredicate accepts)
    {
        Map<Integer, Long> changes = new LinkedHashMap<>();
        if (!pending()) { return changes; }
        if (tick - started > 8) { cancel(); return changes; }
        if (inventory == null || (includeBank && bank == null)) { return changes; }
        Map<Integer, Long> after = count(inventory, includeBank ? bank : null,
            id -> (usedItem < 0 || id == usedItem) && accepts.test(id));
        Map<Integer, Long> ids = new LinkedHashMap<>(before);
        after.forEach(ids::putIfAbsent);
        ids.forEach((id, ignored) ->
        {
            long delta = after.getOrDefault(id, 0L) - before.getOrDefault(id, 0L);
            if ((fill && delta < 0) || (!fill && delta > 0)) { changes.put(id, -delta); }
        });
        if (!changes.isEmpty()) { cancel(); }
        return changes;
    }

    private static Map<Integer, Long> count(Item[] inventory, Item[] bank, IntPredicate accepts)
    {
        Map<Integer, Long> result = new LinkedHashMap<>();
        for (Item[] items : new Item[][]{inventory, bank})
        {
            if (items == null) { continue; }
            for (Item item : items)
            {
                if (item.getQuantity() > 0 && accepts.test(item.getId()))
                { result.merge(item.getId(), (long) item.getQuantity(), Long::sum); }
            }
        }
        return result;
    }
}

package com.atlas;

import net.runelite.api.Item;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;

/** Resolve either item-on-container direction using item IDs, not the combined menu target text. */
final class ContainerUse
{
    static int inventoryItem(int component, int widgetItem, int slot, Item[] inventory)
    {
        int group = WidgetUtil.componentToInterface(component);
        if (group != InterfaceID.INVENTORY && group != InterfaceID.INVENTORY_NOOPS && group != InterfaceID.BANKSIDE)
        { return -1; } // Selected spells can also have an index; it is not an inventory slot.
        if (widgetItem > 0) { return widgetItem; }
        return inventory != null && slot >= 0 && slot < inventory.length ? inventory[slot].getId() : -1;
    }

    static int container(int selected, int target)
    {
        if (selected <= 0 || target <= 0 || isContainer(selected) == isContainer(target)) { return -1; }
        return isContainer(selected) ? selected : target;
    }

    static int storedItem(int selected, int target)
    {
        int container = container(selected, target);
        return container < 0 ? -1 : selected == container ? target : selected;
    }

    private static boolean isContainer(int id)
    {
        if (HerbSackTracker.isSack(id)) { return true; }
        for (BagTracker.Kind kind : BagTracker.Kind.values()) { if (kind.owns(id)) { return true; } }
        return false;
    }
}

package com.atlas;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;

/** Observe server chat and completed container transfers, never infer success from a click alone. */
final class HerbSackTracker
{
    private static final Pattern PICKUP = Pattern.compile(
        "You put the (Grimy [A-Za-z ]+) herb into your (?:silklined )?herb sack\\.", Pattern.CASE_INSENSITIVE);
    private static final Pattern CHECK_LINE = Pattern.compile("([0-9,]+)\\s*x\\s*(Grimy [A-Za-z ]+)", Pattern.CASE_INSENSITIVE);
    private static final Map<String, Integer> HERBS = new LinkedHashMap<>();
    static
    {
        HERBS.put("grimy guam leaf", ItemID.UNIDENTIFIED_GUAM);
        HERBS.put("grimy marrentill", ItemID.UNIDENTIFIED_MARENTILL);
        HERBS.put("grimy tarromin", ItemID.UNIDENTIFIED_TARROMIN);
        HERBS.put("grimy harralander", ItemID.UNIDENTIFIED_HARRALANDER);
        HERBS.put("grimy ranarr weed", ItemID.UNIDENTIFIED_RANARR);
        HERBS.put("grimy toadflax", ItemID.UNIDENTIFIED_TOADFLAX);
        HERBS.put("grimy irit leaf", ItemID.UNIDENTIFIED_IRIT);
        HERBS.put("grimy avantoe", ItemID.UNIDENTIFIED_AVANTOE);
        HERBS.put("grimy kwuarm", ItemID.UNIDENTIFIED_KWUARM);
        HERBS.put("grimy snapdragon", ItemID.UNIDENTIFIED_SNAPDRAGON);
        HERBS.put("grimy cadantine", ItemID.UNIDENTIFIED_CADANTINE);
        HERBS.put("grimy lantadyme", ItemID.UNIDENTIFIED_LANTADYME);
        HERBS.put("grimy dwarf weed", ItemID.UNIDENTIFIED_DWARF_WEED);
        HERBS.put("grimy torstol", ItemID.UNIDENTIFIED_TORSTOL);
        HERBS.put("grimy huasca", ItemID.UNIDENTIFIED_HUASCA);
    }

    private Map<Integer, Long> contents;
    private Map<Integer, Long> check;
    private boolean confirmed, reconcile;
    private boolean legacyBankTransfer;
    private final ContainerTransfer combinedTransfer = new ContainerTransfer();

    void reset() { contents = null; check = null; confirmed = false; reconcile = false; cancelTransfer(); }
    void restore(Map<Integer, Long> saved)
    {
        if (contents == null && saved != null) { contents = new LinkedHashMap<>(saved); }
    }
    Map<Integer, Long> contents() { return contents == null ? null : Collections.unmodifiableMap(contents); }
    boolean confirmed() { return confirmed; }
    long removeStored(int id, long quantity)
    {
        if (contents == null) { return 0; }
        long removed = Math.min(quantity, contents.getOrDefault(id, 0L));
        long left = contents.getOrDefault(id, 0L) - removed;
        if (left == 0) { contents.remove(id); } else { contents.put(id, left); }
        return removed;
    }
    void invalidate() { confirmed = false; cancelTransfer(); }
    boolean takeReconciliation() { boolean result = reconcile; reconcile = false; return result; }
    void cancelTransfer() { combinedTransfer.cancel(); }

    void beginTransfer(String option, Item[] inventory, Item[] bank, int tick)
    {
        cancelTransfer();
        combinedTransfer.begin(option, inventory, bank, tick, HERBS::containsValue);
    }

    void beginItemUse(int id, Item[] inventory, Item[] bank, int tick)
    {
        combinedTransfer.beginItemUse(id, inventory, bank, tick, HERBS::containsValue);
    }

    boolean finishTransfer(Item[] inventory, Item[] bank, int tick)
    {
        Map<Integer, Long> changes = combinedTransfer.finish(inventory, bank, tick, HERBS::containsValue);
        if (changes.isEmpty()) { return false; }
        if (contents == null) { contents = new LinkedHashMap<>(); }
        changes.forEach((id, delta) ->
        {
            long quantity = Math.max(0, contents.getOrDefault(id, 0L) + delta);
            if (quantity == 0) { contents.remove(id); } else { contents.put(id, quantity); }
        });
        return true;
    }

    boolean chat(String message)
    {
        if (message.equalsIgnoreCase("The herb sack is empty.") || message.equalsIgnoreCase("The silklined herb sack is empty."))
        {
            check = new LinkedHashMap<>();
            return false;
        }
        if (message.equalsIgnoreCase("You look in your herb sack and see:")
            || message.equalsIgnoreCase("You look in your silklined herb sack and see:"))
        {
            check = new LinkedHashMap<>();
            return false;
        }
        Matcher line = CHECK_LINE.matcher(message);
        if (check != null && line.matches())
        {
            Integer id = HERBS.get(line.group(2).toLowerCase(Locale.ROOT));
            if (id != null)
            {
                long quantity = Long.parseLong(line.group(1).replace(",", ""));
                if (quantity > 0) { check.put(id, quantity); }
            }
            return false;
        }
        Matcher pickup = PICKUP.matcher(message);
        if (!pickup.matches() || combinedTransfer.filling()) { return false; }
        Integer id = HERBS.get(pickup.group(1).toLowerCase(Locale.ROOT));
        if (id == null) { return false; }
        if (contents == null) { contents = new LinkedHashMap<>(); }
        contents.merge(id, 1L, Long::sum);
        return true;
    }

    /** Check's full message batch is committed together before a wealth reading. */
    boolean finishCheck()
    {
        if (check == null) { return false; }
        contents = check;
        check = null;
        confirmed = true;
        reconcile = true; // Discovering/correcting old sack contents is not new session loot.
        cancelTransfer();
        return true;
    }

    void beginTransfer(String option, Item[] items, int tick)
    {
        legacyBankTransfer = option.equals("Empty to bank");
        beginTransfer(option, legacyBankTransfer ? new Item[0] : items, legacyBankTransfer ? items : null, tick);
    }

    boolean transferringToBank() { return legacyBankTransfer; }

    boolean finishTransfer(Item[] after, int tick)
    {
        return finishTransfer(legacyBankTransfer ? new Item[0] : after, legacyBankTransfer ? after : null, tick);
    }

    static boolean isSack(int id)
    {
        return id == ItemID.SLAYER_HERB_SACK || id == ItemID.SLAYER_HERB_SACK_OPEN
            || id == ItemID.SLAYER_HERB_SACK_SILK || id == ItemID.SLAYER_HERB_SACK_SILK_OPEN;
    }

    static int location(Map<Integer, long[]> holdings)
    {
        int location = -1;
        for (Map.Entry<Integer, long[]> item : holdings.entrySet())
        {
            if (!isSack(item.getKey())) { continue; }
            if (item.getValue()[1] > 0) { return 1; }
            if (item.getValue()[0] > 0) { location = 0; }
        }
        return location;
    }

    Map<Integer, Long> include(Map<Integer, long[]> holdings)
    {
        int location = location(holdings);
        if (location < 0 || contents == null) { return Collections.emptyMap(); }
        contents.forEach((id, quantity) -> holdings.computeIfAbsent(id, ignored -> new long[3])[location] += quantity);
        return location == 0 ? contents : Collections.emptyMap();
    }
}

package com.atlas;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import net.runelite.api.Item;

/** Client-thread state: retain the last observed bank when its live container disappears. */
final class HoldingsTracker
{
    private final IntUnaryOperator canonicalize;
    private final IntPredicate isPlaceholder;
    private Map<Integer, Long> bank;
    private final Map<Integer, Long> remoteBank = new LinkedHashMap<>();
    private long bankTime;

    HoldingsTracker(IntUnaryOperator canonicalize, IntPredicate isPlaceholder)
    {
        this.canonicalize = canonicalize;
        this.isPlaceholder = isPlaceholder;
    }

    void reset()
    {
        bank = null;
        remoteBank.clear();
        bankTime = 0;
    }

    void observeBank(Item[] items, long time)
    {
        if (items == null) { return; }
        // Copy quantities, never retain references to the client's mutable container/array.
        bank = count(items);
        remoteBank.clear();
        bankTime = time;
    }

    long getBankTime() { return bankTime; }

    boolean hasBank() { return bank != null; }

    /** Credit a confirmed remote transfer without claiming the whole bank was observed. */
    void creditBank(Map<Integer, Long> items)
    {
        items.forEach((id, quantity) ->
        {
            if (quantity > 0) { (bank == null ? remoteBank : bank).merge(canonicalize.applyAsInt(id), quantity, Long::sum); }
        });
    }

    Map<Integer, Long> remoteBankSnapshot() { return new LinkedHashMap<>(remoteBank); }

    void restoreRemoteBank(Map<Integer, Long> saved)
    {
        if (bank == null && saved != null) { remoteBank.putAll(saved); }
    }

    Wealth.Bank bankSnapshot()
    {
        return bank == null ? null : new Wealth.Bank(bankTime, bank);
    }

    void restoreBank(Wealth.Bank saved)
    {
        // An observation already received this session takes precedence over a disk load.
        if (bank == null && saved != null)
        {
            bank = new LinkedHashMap<>(saved.quantities);
            bankTime = saved.time;
        }
    }

    Map<Integer, long[]> combine(Item[] inventory, Item[] equipment)
    {
        // Called after logged-in updates settle. RuneLite can omit either empty carried
        // container until its first item arrives; neither is a prerequisite for tracking.
        Map<Integer, long[]> result = new LinkedHashMap<>();
        if (bank != null) { add(result, bank, 0); }
        else { add(result, remoteBank, 0); }
        add(result, count(inventory), 1);
        add(result, count(equipment), 2);
        return result;
    }

    private Map<Integer, Long> count(Item[] items)
    {
        Map<Integer, Long> result = new LinkedHashMap<>();
        if (items == null) { return result; }
        for (Item item : items)
        {
            if (item.getId() < 0 || item.getQuantity() <= 0 || isPlaceholder.test(item.getId())) { continue; }
            result.merge(canonicalize.applyAsInt(item.getId()), (long) item.getQuantity(), Long::sum);
        }
        return result;
    }

    private static void add(Map<Integer, long[]> result, Map<Integer, Long> counts, int location)
    {
        counts.forEach((id, quantity) -> result.computeIfAbsent(id, ignored -> new long[3])[location] = quantity);
    }
}

