    {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    void update(Wealth.Session session)
    {
        value = session == null ? null : new Value(session.change);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        Value current = value;
        if (!config.showSessionValue() || current == null || client.getGameState() != GameState.LOGGED_IN) { return null; }
        for (int id : INVENTORY_TABS)
        {
            Widget tab = client.getWidget(id);
            if (tab == null || tab.isHidden()) { continue; }
            Rectangle bounds = tab.getBounds();
            if (bounds.width < 1 || bounds.height < 1 || bounds.x < 0 || bounds.y < 0) { continue; }
            paint(graphics, bounds, current);
            break;
        }
        return null;
    }

    static final class Value
    {
        final String text;
        final Color color;

        Value(long change)
        {
            text = WealthPanel.signed(change).toLowerCase(Locale.ROOT);
            color = change < 0 ? new Color(255, 70, 70) : change > 0 ? new Color(60, 255, 90) : Color.WHITE;
        }
    }

    /** Package-visible for an offline layout fixture; coordinates come from the visible tab. */
    static void paint(Graphics2D graphics, Rectangle bounds, Value value)
    {
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            g.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
            g.setFont(BADGE_FONT);
            FontMetrics metrics = g.getFontMetrics();
            int width = metrics.stringWidth(value.text);
            int badgeWidth = Math.max(bounds.width - 2, width + 10);
            int badgeHeight = metrics.getHeight() + 4;
            int x = bounds.x + (bounds.width - badgeWidth) / 2;
            int y = bounds.y - badgeHeight - 2;
            // Expand the badge rather than squeezing the digits into a narrow tab.
            Rectangle clip = g.getClipBounds();
            if (clip != null && badgeWidth <= clip.width)
            { x = Math.max(clip.x, Math.min(x, clip.x + clip.width - badgeWidth)); }
            g.setColor(BADGE_BACKGROUND);
            g.fillRoundRect(x, y, badgeWidth, badgeHeight, 7, 7);
            g.setColor(new Color(value.color.getRed(), value.color.getGreen(), value.color.getBlue(), 110));
            g.drawRoundRect(x, y, badgeWidth - 1, badgeHeight - 1, 7, 7);
            g.setColor(value.color);
            g.drawString(value.text, x + (badgeWidth - width) / 2, y + 2 + metrics.getAscent());
        }
        finally { g.dispose(); }
    }
}

package com.atlas;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/** Read the account's shared pouch contents once, even if multiple pouch variants are owned. */
final class RunePouchContents
{
    private static final int[] TYPES = {
        VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
        VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6
    };
    private static final int[] AMOUNTS = {
        VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
        VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6
    };
    private static final int[] POUCHES = {
        ItemID.BH_RUNE_POUCH, ItemID.BH_RUNE_POUCH_TROUVER,
        ItemID.DIVINE_RUNE_POUCH, ItemID.DIVINE_RUNE_POUCH_TROUVER
    };

    static Map<Integer, Long> read(IntUnaryOperator varbit, IntUnaryOperator runeItem)
    {
        Map<Integer, Long> result = new LinkedHashMap<>();
        for (int slot = 0; slot < TYPES.length; slot++)
        {
            int type = varbit.applyAsInt(TYPES[slot]);
            int amount = varbit.applyAsInt(AMOUNTS[slot]);
            if (type <= 0 || amount <= 0) { continue; }
            int id = runeItem.applyAsInt(type);
            if (id > 0) { result.merge(id, (long) amount, Long::sum); }
        }
        return result;
    }

    /** Add to the pouch's location. Return its bank contribution so disk checkpoints stay raw. */
    static Map<Integer, Long> include(Map<Integer, long[]> holdings, Map<Integer, Long> contents)
    {
        int location = -1;
        for (int id : POUCHES)
        {
            long[] quantity = holdings.get(id);
            if (quantity == null) { continue; }
            if (quantity[1] > 0) { location = 1; break; }
            if (quantity[0] > 0) { location = 0; }
        }
        // Varbits can retain contents after losing a pouch. Never count an unowned pouch.
        if (location < 0) { return Collections.emptyMap(); }
        for (Map.Entry<Integer, Long> rune : contents.entrySet())
        {
            holdings.computeIfAbsent(rune.getKey(), ignored -> new long[3])[location] += rune.getValue();
        }
        return location == 0 ? contents : Collections.emptyMap();
    }
}

package com.atlas;

import java.util.HashMap;
import java.util.Map;

/** Quantity changes at fixed per-session prices; unchanged holdings never create session profit/loss. */
final class SessionTracker
{
    private final long start;
    private final Map<Integer, Long> prices = new HashMap<>();
    private final Map<Integer, Long> changes = new HashMap<>();
    private Wealth.Snapshot previous;
    private boolean bankObserved, estimated;

    SessionTracker(long start) { this.start = start; }

    void markEstimated() { estimated = true; }

    void observe(Wealth.Snapshot snapshot, boolean observedBank)
    {
        observe(snapshot, observedBank, false);
    }

    void observe(Wealth.Snapshot snapshot, boolean observedBank, boolean reconcile)
    {
        observe(snapshot, observedBank, reconcile, java.util.Collections.emptyMap());
    }

    /** Neutralize observed rune transfers into/out of the Soul Bearer, not rune consumption. */
    void observe(Wealth.Snapshot snapshot, boolean observedBank, boolean reconcile, Map<Integer, Long> transfers)
    {
        // Use the first available positive quote for each item and never reprice booked changes.
        snapshot.items.values().forEach(e -> { if (e.price > 0) { prices.putIfAbsent(e.id, e.price); } });
        estimated |= !observedBank || snapshot.bankTime == 0;
        if (previous != null && !reconcile && !(observedBank && !bankObserved))
        {
            previous.items.values().forEach(old -> changes.merge(old.id, -old.quantity(), Long::sum));
            snapshot.items.values().forEach(item -> changes.merge(item.id, item.quantity(), Long::sum));
            transfers.forEach((id, quantity) -> changes.merge(id, quantity, Long::sum));
            changes.values().removeIf(quantity -> quantity == 0);
        }
        // The first real bank observation reconciles unknown/stale bank data without calling it loot/loss.
        bankObserved |= observedBank;
        previous = snapshot;
    }

    /** Charges spent from a preloaded item do not appear as loose-rune container changes. */
    void spend(int id, long quantity, long price)
    {
        if (quantity <= 0) { return; }
        if (price > 0) { prices.putIfAbsent(id, price); }
        changes.merge(id, -quantity, Long::sum);
    }

    Wealth.Session current()
    {
        if (previous == null) { return null; }
        long value = changes.entrySet().stream().mapToLong(e -> e.getValue() * prices.getOrDefault(e.getKey(), 0L)).sum();
        return new Wealth.Session(start, Math.max(start, previous.time), value, estimated, false);
    }
}

package com.atlas;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;

/** Match Soul Bearer actions to observed item changes; clicking alone never books a cost. */
final class SoulBearerTracker
{
    static final String REMOTE_BANK_KEY = "soulBearerRemoteBank";
    private enum Action { SEND, CHARGE, UNCHARGE }
    private Action action;
    private Map<Integer, Long> before;
    private boolean includeBank;
    private int started;

    void cancel() { action = null; before = null; }

    void menu(String option, int itemId, Item[] inventory, Item[] bank, int tick)
    {
        if (itemId != ItemID.ARCEUUS_SOULBEARER)
        {
            // A subsequent item action (deposit/drop/cast/etc.) cannot complete an earlier send.
            if (itemId > 0 || option.equalsIgnoreCase("Cast")) { cancel(); }
            return;
        }
        if (option.equalsIgnoreCase("Fill") || option.equalsIgnoreCase("Bank-All"))
        { begin(Action.SEND, inventory, bank, tick, -1); }
        else if (option.equalsIgnoreCase("Uncharge")) { begin(Action.UNCHARGE, inventory, bank, tick, -1); }
        else if (option.equalsIgnoreCase("Configure-Charges")) { begin(Action.CHARGE, inventory, bank, tick, -1); }
        else { cancel(); }
    }

    void use(int selected, int target, Item[] inventory, Item[] bank, int tick)
    {
        cancel();
        int other = selected == ItemID.ARCEUUS_SOULBEARER ? target
            : target == ItemID.ARCEUUS_SOULBEARER ? selected : -1;
        if (isHead(other)) { begin(Action.SEND, inventory, bank, tick, canonicalHead(other)); }
        else if (other == ItemID.BLOODRUNE || other == ItemID.SOULRUNE)
        { begin(Action.CHARGE, inventory, bank, tick, -1); }
    }

    private void begin(Action next, Item[] inventory, Item[] bank, int tick, int usedHead)
    {
        cancel();
        if (inventory == null || (next == Action.SEND && (bank != null || !hasBearer(inventory)))) { return; }
        action = next; includeBank = bank != null; started = tick;
        before = count(inventory, includeBank ? bank : null, action == Action.SEND);
        if (usedHead > 0) { before.keySet().removeIf(id -> id != usedHead); }
    }

    Result finish(Item[] inventory, Item[] bank, int tick)
    {
        if (action == null) { return Result.NONE; }
        // Allow the normal confirmation/quantity dialogue without guessing its outcome.
        if (tick - started > 100 || (action == Action.SEND && bank != null)) { cancel(); return Result.NONE; }
        if (inventory == null || (includeBank && bank == null)) { return Result.NONE; }
        if (action == Action.SEND && !hasBearer(inventory)) { cancel(); return Result.NONE; }
        Map<Integer, Long> after = count(inventory, includeBank ? bank : null, action == Action.SEND);
        if (action == Action.SEND)
        {
            Map<Integer, Long> heads = new LinkedHashMap<>();
            before.forEach((id, quantity) ->
            {
                long sent = quantity - after.getOrDefault(id, 0L);
                if (sent > 0) { heads.put(id, sent); }
            });
            if (heads.isEmpty()) { return Result.NONE; }
            cancel(); return new Result(heads, 0);
        }
        long blood = before.getOrDefault(ItemID.BLOODRUNE, 0L) - after.getOrDefault(ItemID.BLOODRUNE, 0L);
        long soul = before.getOrDefault(ItemID.SOULRUNE, 0L) - after.getOrDefault(ItemID.SOULRUNE, 0L);
        // Configure-Charges supports both adding and removing charges; both rune deltas must agree.
        long charges = blood > 0 && soul > 0 && action == Action.CHARGE ? Math.min(blood, soul)
            : blood < 0 && soul < 0 ? -Math.min(-blood, -soul) : 0;
        if (charges == 0) { return Result.NONE; }
        cancel(); return new Result(Collections.emptyMap(), charges);
    }

    static final class Result
    {
        static final Result NONE = new Result(Collections.emptyMap(), 0);
        final Map<Integer, Long> heads;
        // Positive = loose runes loaded, negative = loose runes returned on uncharging.
        final long chargeTransfer;
        Result(Map<Integer, Long> heads, long chargeTransfer) { this.heads = heads; this.chargeTransfer = chargeTransfer; }
        long spent() { return heads.values().stream().mapToLong(Long::longValue).sum(); }
    }

    private static boolean hasBearer(Item[] inventory)
    {
        for (Item item : inventory)
        { if (item.getId() == ItemID.ARCEUUS_SOULBEARER && item.getQuantity() > 0) { return true; } }
        return false;
    }

    private static Map<Integer, Long> count(Item[] inventory, Item[] bank, boolean heads)
    {
        Map<Integer, Long> result = new LinkedHashMap<>();
        for (Item[] items : new Item[][]{inventory, bank})
        {
            if (items == null) { continue; }
            for (Item item : items)
            {
                int id = item.getId();
                if (item.getQuantity() > 0 && (heads ? isHead(id) : id == ItemID.BLOODRUNE || id == ItemID.SOULRUNE))
                { result.merge(canonicalHead(id), (long) item.getQuantity(), Long::sum); }
            }
        }
        return result;
    }

    static boolean isHead(int id)
    {
        for (int[] pair : HEADS) { if (id == pair[0] || id == pair[1]) { return true; } }
        return false;
    }

    static int canonicalHead(int id)
    {
        for (int[] pair : HEADS) { if (id == pair[0]) { return pair[1]; } }
        return id;
    }

    private static final int[][] HEADS = {
        {ItemID.ARCEUUS_CORPSE_GOBLIN_INITIAL, ItemID.ARCEUUS_CORPSE_GOBLIN},
        {ItemID.ARCEUUS_CORPSE_MONKEY_INITIAL, ItemID.ARCEUUS_CORPSE_MONKEY},
        {ItemID.ARCEUUS_CORPSE_IMP_INITIAL, ItemID.ARCEUUS_CORPSE_IMP},
        {ItemID.ARCEUUS_CORPSE_MINOTAUR_INITIAL, ItemID.ARCEUUS_CORPSE_MINOTAUR},
        {ItemID.ARCEUUS_CORPSE_SCORPION_INITIAL, ItemID.ARCEUUS_CORPSE_SCORPION},
        {ItemID.ARCEUUS_CORPSE_BEAR_INITIAL, ItemID.ARCEUUS_CORPSE_BEAR},
        {ItemID.ARCEUUS_CORPSE_UNICORN_INITIAL, ItemID.ARCEUUS_CORPSE_UNICORN},
        {ItemID.ARCEUUS_CORPSE_DOG_INITIAL, ItemID.ARCEUUS_CORPSE_DOG},
        {ItemID.ARCEUUS_CORPSE_CHAOSDRUID_INITIAL, ItemID.ARCEUUS_CORPSE_CHAOSDRUID},
        {ItemID.ARCEUUS_CORPSE_GIANT_INITIAL, ItemID.ARCEUUS_CORPSE_GIANT},
        {ItemID.ARCEUUS_CORPSE_OGRE_INITIAL, ItemID.ARCEUUS_CORPSE_OGRE},
        {ItemID.ARCEUUS_CORPSE_ELF_INITIAL, ItemID.ARCEUUS_CORPSE_ELF},
        {ItemID.ARCEUUS_CORPSE_TROLL_INITIAL, ItemID.ARCEUUS_CORPSE_TROLL},
        {ItemID.ARCEUUS_CORPSE_HORROR_INITIAL, ItemID.ARCEUUS_CORPSE_HORROR},
        {ItemID.ARCEUUS_CORPSE_KALPHITE_INITIAL, ItemID.ARCEUUS_CORPSE_KALPHITE},
        {ItemID.ARCEUUS_CORPSE_DAGANNOTH_INITIAL, ItemID.ARCEUUS_CORPSE_DAGANNOTH},
        {ItemID.ARCEUUS_CORPSE_BLOODVELD_INITIAL, ItemID.ARCEUUS_CORPSE_BLOODVELD},
        {ItemID.ARCEUUS_CORPSE_TZHAAR_INITIAL, ItemID.ARCEUUS_CORPSE_TZHAAR},
        {ItemID.ARCEUUS_CORPSE_DEMON_INITIAL, ItemID.ARCEUUS_CORPSE_DEMON},
        {ItemID.ARCEUUS_CORPSE_AVIANSIE_INITIAL, ItemID.ARCEUUS_CORPSE_AVIANSIE},
        {ItemID.ARCEUUS_CORPSE_ABYSSAL_INITIAL, ItemID.ARCEUUS_CORPSE_ABYSSAL},
        {ItemID.ARCEUUS_CORPSE_DRAGON_INITIAL, ItemID.ARCEUUS_CORPSE_DRAGON},
        {ItemID.ARCEUUS_CORPSE_HELLHOUND_INITIAL, ItemID.ARCEUUS_CORPSE_HELLHOUND}
    };
}

package com.atlas;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Immutable values shared between the client, Swing and storage threads. */
final class Wealth
{
    static final class Session
    {
        final long start, end, change;
        final boolean estimated, interrupted;

        Session(long start, long end, long change, boolean estimated, boolean interrupted)
        {
            this.start = start;
            this.end = end;
            this.change = change;
            this.estimated = estimated;
            this.interrupted = interrupted;
        }

        long elapsedMillis() { return Math.max(0, end - start); }

        long changePerHour()
        {
            long elapsed = elapsedMillis();
            return elapsed == 0 ? 0 : Math.round(change * (3_600_000.0 / elapsed));
        }
    }

    static final class Bank
    {
        final long time;
        final Map<Integer, Long> quantities;

        Bank(long time, Map<Integer, Long> quantities)
        {
            this.time = time;
            this.quantities = Collections.unmodifiableMap(new LinkedHashMap<>(quantities));
        }

        static Bank from(Snapshot snapshot)
        {
            if (snapshot == null || snapshot.bankTime == 0) { return null; }
            Map<Integer, Long> quantities = new LinkedHashMap<>();
            snapshot.items.forEach((id, entry) ->
            {
                long loose = entry.bank - entry.bankPouch - entry.bankSack;
                if (loose > 0) { quantities.put(id, loose); }
            });
            return new Bank(snapshot.bankTime, quantities);
        }
    }

    static final class Entry
    {
        final int id;
        final String name;
        // bankSack is the persisted legacy name for ALL non-rune-pouch stored contents in the bank.
        final long bank, inventory, equipment, price, alch, bankPouch, bankSack, deployed;
        final boolean members, tradeable, unpriced;

        Entry(int id, String name, long bank, long inventory, long equipment,
              long price, long alch, boolean members, boolean tradeable, boolean unpriced)
        {
            this(id, name, bank, inventory, equipment, price, alch, members, tradeable, unpriced, 0);
        }

        Entry(int id, String name, long bank, long inventory, long equipment,
              long price, long alch, boolean members, boolean tradeable, boolean unpriced, long bankPouch)
        {
            this(id, name, bank, inventory, equipment, price, alch, members, tradeable, unpriced, bankPouch, 0);
        }

        Entry(int id, String name, long bank, long inventory, long equipment,
              long price, long alch, boolean members, boolean tradeable, boolean unpriced, long bankPouch, long bankSack)
        {
            this(id, name, bank, inventory, equipment, price, alch, members, tradeable, unpriced, bankPouch, bankSack, 0);
        }

        Entry(int id, String name, long bank, long inventory, long equipment,
              long price, long alch, boolean members, boolean tradeable, boolean unpriced,
              long bankPouch, long bankSack, long deployed)
        {
            this.id = id;
            this.name = name;
            this.bank = bank;
            this.bankPouch = bankPouch;
            this.bankSack = bankSack;
            this.deployed = deployed;
            this.inventory = inventory;
            this.equipment = equipment;
            this.price = price;
            this.alch = alch;
            this.members = members;
            this.tradeable = tradeable;
            this.unpriced = unpriced;
        }

        long quantity() { return bank + inventory + equipment + deployed; }
        long value() { return quantity() * price; }
        long haValue() { return quantity() * alch; }
    }

    static final class Snapshot
    {
        final long time, bankTime;
        final Map<Integer, Entry> items;

        Snapshot(long time, long bankTime, Map<Integer, Entry> items)
        {
            this.time = time;
            this.bankTime = bankTime;
            this.items = Collections.unmodifiableMap(new LinkedHashMap<>(items));
        }

        long bank() { return items.values().stream().mapToLong(e -> e.bank * e.price).sum(); }
        long inventory() { return items.values().stream().mapToLong(e -> e.inventory * e.price).sum(); }
        long equipment() { return items.values().stream().mapToLong(e -> e.equipment * e.price).sum(); }
        long deployed() { return items.values().stream().mapToLong(e -> e.deployed * e.price).sum(); }
        long total() { return bank() + inventory() + equipment() + deployed(); }
        long alch() { return items.values().stream().mapToLong(Entry::haValue).sum(); }
        long unpriced() { return items.values().stream().filter(e -> e.unpriced).count(); }
    }

    static final class Point
    {
        final long time, total, alch, unique, market, items;
        final boolean attributed;

        Point(long time, long total, long alch, long unique, long market, long items)
        {
            this(time, total, alch, unique, market, items, true);
        }

        Point(long time, long total, long alch, long unique, long market, long items, boolean attributed)
        {
            this.time = time;
            this.total = total;
            this.alch = alch;
            this.unique = unique;
            this.market = market;
            this.items = items;
            this.attributed = attributed;
        }
    }

    /** Revalue the PREVIOUS holdings at today's prices, then attribute the remainder to item changes. */
    static Point point(Snapshot previous, Snapshot next, Point last, Map<Integer, Long> quotes)
    {
        long market = 0;
        if (previous != null)
        {
            for (Entry old : previous.items.values())
            {
                long price = quotes.getOrDefault(old.id, old.price);
                market += old.quantity() * (price - old.price);
            }
        }
        long change = previous == null ? 0 : next.total() - previous.total();
        return new Point(next.time, next.total(), next.alch(), next.items.size(),
            (last == null ? 0 : last.market) + market,
            (last == null ? 0 : last.items) + change - market);
    }

    static final class State
    {
        final String profile;
        final Snapshot latest;
        final List<Point> history;
        final long revision;
        final Bank bank;
        final List<Session> sessions;
        final Session activeSession;
        final Map<Integer, Long> herbSack;
        final Map<String, Map<Integer, Long>> extraContainers;

        State(String profile, Snapshot latest, List<Point> history, long revision)
        {
            this(profile, latest, history, revision, Bank.from(latest));
        }

        State(String profile, Snapshot latest, List<Point> history, long revision, Bank bank)
        {
            this(profile, latest, history, revision, bank, Collections.emptyList(), null);
        }

        State(String profile, Snapshot latest, List<Point> history, long revision, Bank bank,
              List<Session> sessions, Session activeSession)
        {
            this(profile, latest, history, revision, bank, sessions, activeSession, null);
        }

        State(String profile, Snapshot latest, List<Point> history, long revision, Bank bank,
              List<Session> sessions, Session activeSession, Map<Integer, Long> herbSack)
        {
            this(profile, latest, history, revision, bank, sessions, activeSession, herbSack, Collections.emptyMap());
        }

        State(String profile, Snapshot latest, List<Point> history, long revision, Bank bank,
              List<Session> sessions, Session activeSession, Map<Integer, Long> herbSack,
              Map<String, Map<Integer, Long>> extraContainers)
        {
            this.profile = profile;
            this.latest = latest;
            this.history = Collections.unmodifiableList(new ArrayList<>(history));
            this.revision = revision;
            this.bank = bank;
            this.sessions = Collections.unmodifiableList(new ArrayList<>(sessions));
            this.activeSession = activeSession;
            this.herbSack = herbSack == null ? null : Collections.unmodifiableMap(new LinkedHashMap<>(herbSack));
            Map<String, Map<Integer, Long>> copy = new LinkedHashMap<>();
            extraContainers.forEach((key, items) -> copy.put(key, Collections.unmodifiableMap(new LinkedHashMap<>(items))));
            this.extraContainers = Collections.unmodifiableMap(copy);
        }

        static State empty(String profile)
        {
            return new State(profile, null, Collections.emptyList(), 0);
        }

        State append(Snapshot snapshot, Map<Integer, Long> quotes)
        {
            if (snapshot.bankTime == 0) { throw new IllegalArgumentException("Net-worth history requires a known bank"); }
            List<Point> points = new ArrayList<>(history);
            points.add(point(latest, snapshot, points.isEmpty() ? null : points.get(points.size() - 1), quotes));
            Bank observed = Bank.from(snapshot);
            Bank newest = bank != null && (observed == null || bank.time > observed.time) ? bank : observed;
            return new State(profile, snapshot, points, revision + 1, newest, sessions, activeSession, herbSack, extraContainers);
        }

        State withBank(Bank bank)
        {
            return new State(profile, latest, history, revision + 1, bank, sessions, activeSession, herbSack, extraContainers);
        }

        State withActiveSession(Session session)
        {
            return new State(profile, latest, history, revision + 1, bank, sessions, session, herbSack, extraContainers);
        }

        State withHerbSack(Map<Integer, Long> contents)
        {
            return new State(profile, latest, history, revision + 1, bank, sessions, activeSession, contents, extraContainers);
        }

        State withExtraContainers(Map<String, Map<Integer, Long>> contents)
        {
            return new State(profile, latest, history, revision + 1, bank, sessions, activeSession, herbSack, contents);
        }

        State closeSession(boolean interrupted)
        {
            if (activeSession == null) { return this; }
            List<Session> completed = new ArrayList<>(sessions);
            completed.add(new Session(activeSession.start, activeSession.end, activeSession.change,
                activeSession.estimated, interrupted));
            return new State(profile, latest, history, revision + 1, bank, completed, null, herbSack, extraContainers);
        }
    }
}

