        private long quantity(Wealth.Entry entry)
        {
            switch (scope.getSelectedIndex())
            {
                case 1: return entry.bank;
                case 2: return entry.inventory;
                case 3: return entry.equipment;
                default: return entry.quantity();
            }
        }

        private boolean matchesFilter(Wealth.Entry e)
        {
            switch (filter.getSelectedIndex())
            {
                case 1: return e.members;
                case 2: return !e.members;
                case 3: return e.tradeable;
                case 4: return !e.tradeable;
                case 5: return e.unpriced;
                default: return true;
            }
        }

        private void refreshItems()
        {
            String query = search.getText().trim().toLowerCase(Locale.ROOT);
            List<Wealth.Entry> entries = snapshot == null ? new ArrayList<>() : snapshot.items.values().stream()
                .filter(e -> quantity(e) > 0 && e.name.toLowerCase(Locale.ROOT).contains(query) && matchesFilter(e))
                .collect(Collectors.toList());
            Comparator<Wealth.Entry> comparator;
            switch (sort.getSelectedIndex())
            {
                case 1: comparator = Comparator.comparingLong(e -> e.price); break;
                case 2: comparator = Comparator.comparingLong(e -> quantity(e) * e.alch); break;
                case 3: comparator = Comparator.comparingLong(this::quantity); break;
                case 4: comparator = Comparator.comparing(e -> e.name.toLowerCase(Locale.ROOT)); break;
                default: comparator = Comparator.comparingLong(e -> quantity(e) * e.price);
            }
            if ((sort.getSelectedIndex() != 4 && descending) || (sort.getSelectedIndex() == 4 && !descending))
            { comparator = comparator.reversed(); }
            entries.sort(comparator.thenComparingInt(e -> e.id));
            int pages = Math.max(1, (entries.size() + 59) / 60);
            page = Math.max(0, Math.min(page, pages - 1));
            grid.removeAll();
            for (int i = page * 60; i < Math.min(entries.size(), (page + 1) * 60); ++i)
            { grid.add(itemCard(entries.get(i))); }
            long visibleTotal = entries.stream().mapToLong(e -> quantity(e) * e.price).sum();
            matches.setText(entries.size() + " matching items · " + compact(visibleTotal) + " GP in selected location");
            previous.setEnabled(page > 0); next.setEnabled(page + 1 < pages);
            pageLabel.setText("Page " + (page + 1) + " of " + pages);
            grid.revalidate(); grid.repaint();
        }

        private JPanel itemCard(Wealth.Entry entry)
        {
            JPanel card = new JPanel(new BorderLayout(0, 3));
            card.setBackground(CARD);
            card.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(40, 44, 63)),
                BorderFactory.createEmptyBorder(8, 5, 8, 5)));
            card.setPreferredSize(new Dimension(132, 112));
            String tooltip = "<html>" + escape(entry.name) + "<br>Quantity: " + exact(quantity(entry))
                + "<br>GE each: " + exact(entry.price) + " GP<br>GE stack: " + exact(quantity(entry) * entry.price)
                + " GP<br>HA stack: " + exact(quantity(entry) * entry.alch) + " GP<br>Bank: " + exact(entry.bank)
                + " · Inventory: " + exact(entry.inventory) + " · Equipment: " + exact(entry.equipment)
                + (entry.deployed == 0 ? "" : " · Deployed cannon: " + exact(entry.deployed)) + "</html>";
            JLabel quantity = label(exact(quantity(entry)), 11, new Color(255, 211, 94));
            JLabel image = new JLabel("", SwingConstants.CENTER);
            image.setPreferredSize(new Dimension(38, 34));
            if (itemManager != null)
            {
                AsyncBufferedImage sprite = itemManager.getImage(entry.id);
                if (sprite != null) { sprite.addTo(image); }
            }
            JPanel top = new JPanel(new BorderLayout()); top.setOpaque(false);
            top.add(quantity, BorderLayout.NORTH); top.add(image, BorderLayout.CENTER);
            card.add(top, BorderLayout.CENTER);
            JPanel bottom = new JPanel(new GridLayout(2, 1)); bottom.setOpaque(false);
            JLabel name = label(entry.name, 11, Color.WHITE); name.setHorizontalAlignment(SwingConstants.CENTER);
            JLabel value = label(entry.unpriced ? "No GE quote" : compact(quantity(entry) * entry.price) + " GP", 12, BLUE);
            value.setHorizontalAlignment(SwingConstants.CENTER);
            bottom.add(name); bottom.add(value);
            card.add(bottom, BorderLayout.SOUTH);
            card.setToolTipText(tooltip);
            image.setToolTipText(tooltip); name.setToolTipText(tooltip); value.setToolTipText(tooltip);
            return card;
        }

        private void refreshHistory()
        {
            long[] periods = {86_400_000L, 7 * 86_400_000L, 30 * 86_400_000L, 365 * 86_400_000L, Long.MAX_VALUE};
            long cutoff = periods[range.getSelectedIndex()] == Long.MAX_VALUE ? 0 : System.currentTimeMillis() - periods[range.getSelectedIndex()];
            List<Wealth.Point> points = state == null ? Collections.emptyList() : state.history.stream()
                .filter(p -> p.time >= cutoff).collect(Collectors.toList());
            if (points.isEmpty())
            {
                changes.setText("No snapshots in this period yet.");
                coverage.setText(snapshot != null && snapshot.bankTime > 0 ? "Use Record snapshot to add a point."
                    : "Carried values update now. Open your bank once to start net-worth history.");
            }
            else
            {
                Wealth.Point first = points.get(0), last = points.get(points.size() - 1);
                boolean attributed = points.stream().skip(1).allMatch(p -> p.attributed);
                changes.setText("<html>Net change " + signed(last.total - first.total) + " GP"
                    + (attributed ? "<br><font color='#44d394'>Market " + signed(last.market - first.market) + " GP</font>"
                        + " &nbsp; · &nbsp; <font color='#ffd35e'>Item changes " + signed(last.items - first.items) + " GP</font>"
                        : "<br>Market/item split unavailable across an unsynced device gap.") + "</html>");
                coverage.setText(points.size() == 1 ? "First snapshot saved. More points will appear as you play." :
                    TIME.format(Instant.ofEpochMilli(first.time)) + " – " + TIME.format(Instant.ofEpochMilli(last.time))
                        + " · " + points.size() + " recorded points (local time)");
            }
            graph.setData(points, metric.getSelectedIndex());
        }
    }

    static final class SessionHistoryModel extends AbstractTableModel
    {
        private final List<Wealth.Session> rows = new ArrayList<>();
        private final List<Boolean> live = new ArrayList<>();
        private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("MMM d, yyyy HH:mm").withZone(ZoneId.systemDefault());

        void setState(Wealth.State state)
        {
            rows.clear(); live.clear();
            if (state != null)
            {
                if (state.activeSession != null) { rows.add(state.activeSession); live.add(true); }
                for (int i = state.sessions.size() - 1; i >= 0; --i) { rows.add(state.sessions.get(i)); live.add(false); }
            }
            fireTableDataChanged();
        }

        Wealth.Session row(int row) { return rows.get(row); }
        public int getRowCount() { return rows.size(); }
        public int getColumnCount() { return 6; }
        public String getColumnName(int column)
        { return new String[]{"Session start", "Last update / end", "Session time", "Value change", "Change/hour", "Status"}[column]; }
        public Object getValueAt(int row, int column)
        {
            Wealth.Session session = rows.get(row);
            switch (column)
            {
                case 0: return DATE.format(Instant.ofEpochMilli(session.start));
                case 1: return DATE.format(Instant.ofEpochMilli(session.end));
                case 2: return duration(session.elapsedMillis());
                case 3: return signed(session.change) + " GP";
                case 4: return session.elapsedMillis() == 0 ? "--" : signed(session.changePerHour()) + " GP/h";
                default: return (live.get(row) ? "Live" : session.interrupted ? "Interrupted" : "Saved")
                    + (session.estimated ? " · Estimate" : "");
            }
        }

        private static String duration(long millis)
        {
            long seconds = millis / 1000;
            if (seconds < 60) { return seconds + " sec"; }
            long minutes = seconds / 60;
            if (minutes < 60) { return minutes + " min"; }
            return minutes / 60 + "h " + minutes % 60 + "m";
        }
    }

    static final class Graph extends JPanel
    {
        private List<Wealth.Point> points = Collections.emptyList();
        private int metric;
        private long origin;
        Graph()
        {
            setBackground(CARD);
            setPreferredSize(new Dimension(600, 300));
            setToolTipText("");
        }

        void setData(List<Wealth.Point> points, int metric)
        {
            this.points = points;
            this.metric = metric;
            origin = points.isEmpty() ? 0 : metric == 3 ? points.get(0).market : metric == 4 ? points.get(0).items : 0;
            repaint();
        }

        private long value(Wealth.Point p)
        {
            switch (metric)
            {
                case 1: return p.alch;
                case 2: return p.unique;
                case 3: return p.market - origin;
                case 4: return p.items - origin;
                default: return p.total;
            }
        }

        @Override
        protected void paintComponent(Graphics graphics)
        {
            super.paintComponent(graphics);
            Graphics2D g = (Graphics2D) graphics.create();
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int left = 70, right = getWidth() - 24, top = 28, bottom = getHeight() - 38;
            if (metric >= 3 && points.stream().skip(1).anyMatch(p -> !p.attributed))
            {
                g.setColor(MUTED);
                g.drawString("Market/item split unavailable across an unsynced device gap.", left, Math.max(50, getHeight() / 2));
                g.dispose(); return;
            }
            if (points.isEmpty())
            {
                g.setColor(MUTED); g.drawString("Your history starts with the first bank sync.", left, Math.max(50, getHeight() / 2));
                g.dispose(); return;
            }
            long min = points.stream().mapToLong(this::value).min().orElse(0);
            long max = points.stream().mapToLong(this::value).max().orElse(0);
            double padding = Math.max(1, (max - (double) min) * .15);
            double low = min - padding, high = max + padding;
            if (metric < 3) { low = Math.max(0, low); }
            if (high <= low) { high = low + 1; }
            for (int line = 0; line <= 4; ++line)
            {
                int y = top + (bottom - top) * line / 4;
                g.setColor(new Color(45, 50, 69)); g.drawLine(left, y, right, y);
                g.setColor(MUTED); g.drawString(compact((long) (high - (high - low) * line / 4)), 8, y + 4);
            }
            long firstTime = points.get(0).time, lastTime = points.get(points.size() - 1).time;
            Path2D path = new Path2D.Double();
            List<int[]> coordinates = new ArrayList<>();
            for (Wealth.Point point : points)
            {
                int x = firstTime == lastTime ? (left + right) / 2 : left + (int) ((right - left) * (point.time - (double) firstTime) / (lastTime - (double) firstTime));
                int y = bottom - (int) ((bottom - top) * (value(point) - low) / (high - low));
                if (coordinates.isEmpty()) { path.moveTo(x, y); } else { path.lineTo(x, y); }
                coordinates.add(new int[]{x, y});
            }
            Color color = metric == 3 ? GREEN : metric == 4 ? new Color(255, 211, 94) : BLUE;
            if (coordinates.size() > 1)
            {
                Path2D area = (Path2D) path.clone();
                area.lineTo(coordinates.get(coordinates.size() - 1)[0], bottom); area.lineTo(coordinates.get(0)[0], bottom); area.closePath();
                g.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), 32)); g.fill(area);
            }
            g.setStroke(new BasicStroke(2)); g.setColor(color); g.draw(path);
            if (coordinates.size() <= 100)
            { for (int[] p : coordinates) { g.fillOval(p[0] - 3, p[1] - 3, 6, 6); } }
            g.setColor(MUTED);
            String start = TIME.format(Instant.ofEpochMilli(firstTime)), end = TIME.format(Instant.ofEpochMilli(lastTime));
            g.drawString(start, left, bottom + 24);
            g.drawString(end, right - g.getFontMetrics().stringWidth(end), bottom + 24);
            g.dispose();
        }

        @Override
        public String getToolTipText(MouseEvent event)
        {
            if (points.isEmpty()) { return null; }
            if (metric >= 3 && points.stream().skip(1).anyMatch(p -> !p.attributed))
            { return "Net worth remains available; this gap cannot be split accurately into market and item changes."; }
            long first = points.get(0).time, last = points.get(points.size() - 1).time;
            double fraction = Math.max(0, Math.min(1, (event.getX() - 70.0) / Math.max(1, getWidth() - 94.0)));
            double time = first + fraction * (last - (double) first);
            Wealth.Point nearest = points.stream().min(Comparator.comparingDouble(p -> Math.abs(p.time - time))).get();
            return TIME.format(Instant.ofEpochMilli(nearest.time)) + " · " + exact(value(nearest)) + (metric == 2 ? " items" : " GP");
        }
    }

    private static JPanel vertical()
    {
        JPanel panel = new JPanel(); panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS)); panel.setOpaque(false); return panel;
    }

    private static JLabel label(String text, int size, Color color)
    {
        JLabel label = new JLabel(text)
        {
            @Override
            public Dimension getMaximumSize()
            {
                return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
            }
        };
        label.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, size)); label.setForeground(color);
        label.setAlignmentX(Component.LEFT_ALIGNMENT); return label;
    }

    private static JButton button(String text)
    {
        JButton button = new JButton(text); button.setAlignmentX(Component.LEFT_ALIGNMENT); return button;
    }

    static String compact(long value)
    {
        double abs = Math.abs((double) value);
        if (abs >= 1_000_000_000) { return String.format(Locale.ROOT, "%.2fB", value / 1_000_000_000.0); }
        if (abs >= 1_000_000) { return String.format(Locale.ROOT, "%.2fM", value / 1_000_000.0); }
        if (abs >= 1000) { return String.format(Locale.ROOT, "%.1fK", value / 1000.0); }
        return Long.toString(value);
    }

    private static String exact(long value) { return NumberFormat.getIntegerInstance(Locale.US).format(value); }
    static String signed(long value) { return (value > 0 ? "+" : "") + compact(value); }
    private static String escape(String text) { return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"); }
}

package com.atlas;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.Reader;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.util.Filepath;

/** Explicit JSON fields; never Java object serialization or account credentials. */
final class WealthStore
{
    private final Gson gson;
    private final Map<String, Long> written = new HashMap<>();

    WealthStore(Gson gson) { this.gson = gson; }

    synchronized Wealth.State load(Filepath directory, String key) throws IOException
    {
        directory.createDirectories();
        Filepath file = directory.joinSegment(key + ".json");
        if (!file.exists()) { return Wealth.State.empty(key); }
        try (Reader reader = file.openBufferedReader())
        {
            Wealth.State state = decode(key, gson.fromJson(reader, JsonObject.class));
            written.put(key, state.revision);
            return state;
        }
        catch (RuntimeException ex)
        {
            // Keep the original file for recovery. The caller must NOT overwrite it.
            throw new IOException("History could not be read; original file kept", ex);
        }
    }

    synchronized String deviceId(Filepath directory) throws IOException
    {
        directory.createDirectories();
        Filepath file = directory.joinSegment("sync-device-id.txt");
        if (file.exists())
        {
            try (Reader reader = file.openBufferedReader())
            {
                char[] chars = new char[64]; int length = reader.read(chars);
                String id = length < 0 ? "" : new String(chars, 0, length).trim();
                if (id.matches("[a-f0-9]{32}")) { return id; }
                throw new IOException("Invalid sync device ID");
            }
        }
        String id = java.util.UUID.randomUUID().toString().replace("-", "");
        file.write(id);
        return id;
    }

    synchronized void backupBeforeSync(Filepath directory, Wealth.State state) throws IOException
    {
        directory.createDirectories();
        Filepath backup = directory.joinSegment(state.profile + ".before-sync.json");
        if (!backup.exists()) { backup.write(gson.toJson(encode(state))); }
    }

    synchronized void save(Filepath directory, Wealth.State state) throws IOException
    {
        if (state.revision <= written.getOrDefault(state.profile, -1L)) { return; }
        directory.createDirectories();
        Filepath file = directory.joinSegment(state.profile + ".json");
        Filepath temp = directory.joinSegment(state.profile + ".pending.json");
        temp.write(gson.toJson(encode(state)));
        try { temp.moveTo(file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING); }
        catch (AtomicMoveNotSupportedException ex) { temp.moveTo(file, StandardCopyOption.REPLACE_EXISTING); }
        written.put(state.profile, state.revision);
    }

    static JsonObject encode(Wealth.State state)
    {
        JsonObject root = new JsonObject();
        root.addProperty("schema", 1);
        root.addProperty("revision", state.revision);
        JsonObject containers = new JsonObject();
        state.extraContainers.forEach((key, items) ->
        {
            JsonArray quantities = new JsonArray();
            items.forEach((id, quantity) ->
            {
                JsonObject item = new JsonObject();
                item.addProperty("id", id); item.addProperty("quantity", quantity); quantities.add(item);
            });
            containers.add(key, quantities);
        });
        root.add("extraContainers", containers);
        if (state.herbSack != null)
        {
            JsonArray herbs = new JsonArray();
            state.herbSack.forEach((id, quantity) ->
            {
                JsonObject herb = new JsonObject();
                herb.addProperty("id", id);
                herb.addProperty("quantity", quantity);
                herbs.add(herb);
            });
            root.add("herbSack", herbs);
        }
        if (state.bank != null)
        {
            JsonObject bank = new JsonObject();
            bank.addProperty("time", state.bank.time);
            JsonArray quantities = new JsonArray();
            state.bank.quantities.forEach((id, quantity) ->
            {
                JsonObject holding = new JsonObject();
                holding.addProperty("id", id);
                holding.addProperty("quantity", quantity);
                quantities.add(holding);
            });
            bank.add("quantities", quantities);
            root.add("bankCheckpoint", bank);
        }
        if (state.latest != null)
        {
            JsonObject snapshot = new JsonObject();
            snapshot.addProperty("time", state.latest.time);
            snapshot.addProperty("bankTime", state.latest.bankTime);
            JsonArray entries = new JsonArray();
            for (Wealth.Entry e : state.latest.items.values())
            {
                JsonObject item = new JsonObject();
                item.addProperty("id", e.id);
                item.addProperty("name", e.name);
                item.addProperty("bank", e.bank);
                item.addProperty("bankPouch", e.bankPouch);
                item.addProperty("bankSack", e.bankSack);
                item.addProperty("inventory", e.inventory);
                item.addProperty("equipment", e.equipment);
                item.addProperty("deployed", e.deployed);
                item.addProperty("price", e.price);
                item.addProperty("alch", e.alch);
                item.addProperty("members", e.members);
                item.addProperty("tradeable", e.tradeable);
                item.addProperty("unpriced", e.unpriced);
                entries.add(item);
            }
            snapshot.add("entries", entries);
            root.add("snapshot", snapshot);
        }
        JsonArray points = new JsonArray();
        for (Wealth.Point p : state.history)
        {
            JsonObject point = new JsonObject();
            point.addProperty("time", p.time);
            point.addProperty("total", p.total);
            point.addProperty("alch", p.alch);
            point.addProperty("unique", p.unique);
            point.addProperty("market", p.market);
            point.addProperty("items", p.items);
            point.addProperty("attributed", p.attributed);
            points.add(point);
        }
        root.add("history", points);
        JsonArray sessions = new JsonArray();
        for (Wealth.Session session : state.sessions) { sessions.add(encodeSession(session)); }
        root.add("sessions", sessions);
        if (state.activeSession != null) { root.add("activeSession", encodeSession(state.activeSession)); }
        return root;
    }

    private static JsonObject encodeSession(Wealth.Session session)
    {
        JsonObject object = new JsonObject();
        object.addProperty("start", session.start);
        object.addProperty("end", session.end);
        object.addProperty("change", session.change);
        object.addProperty("estimated", session.estimated);
        object.addProperty("interrupted", session.interrupted);
        return object;
    }

    private static Wealth.Session decodeSession(JsonObject object)
    {
        long start = nonnegative(object, "start"), end = nonnegative(object, "end");
        if (end < start) { throw new IllegalArgumentException("Invalid session dates"); }
        return new Wealth.Session(start, end, object.get("change").getAsLong(),
            object.get("estimated").getAsBoolean(), object.get("interrupted").getAsBoolean());
    }

    static Wealth.State decode(String key, JsonObject root)
    {
        if (root == null || root.get("schema").getAsInt() != 1) { throw new IllegalArgumentException("Unknown history format"); }
        Wealth.Snapshot snapshot = null;
        if (root.has("snapshot"))
        {
            JsonObject raw = root.getAsJsonObject("snapshot");
            Map<Integer, Wealth.Entry> entries = new LinkedHashMap<>();
            for (JsonElement value : raw.getAsJsonArray("entries"))
            {
                JsonObject e = value.getAsJsonObject();
                int id = e.get("id").getAsInt();
                Wealth.Entry entry = new Wealth.Entry(id, e.get("name").getAsString(),
                    nonnegative(e, "bank"), nonnegative(e, "inventory"), nonnegative(e, "equipment"),
                    nonnegative(e, "price"), nonnegative(e, "alch"), e.get("members").getAsBoolean(),
                    e.get("tradeable").getAsBoolean(), e.get("unpriced").getAsBoolean(),
                    e.has("bankPouch") ? nonnegative(e, "bankPouch") : 0,
                    e.has("bankSack") ? nonnegative(e, "bankSack") : 0,
                    e.has("deployed") ? nonnegative(e, "deployed") : 0);
                if (entry.bankPouch > entry.bank || entry.bankSack > entry.bank - entry.bankPouch)
                { throw new IllegalArgumentException("Invalid bank container quantity"); }
                if (entry.deployed > 1 || (entry.deployed > 0 && !CannonTracker.isPart(id)))
                { throw new IllegalArgumentException("Invalid deployed cannon piece"); }
                if (id < 0 || entry.quantity() == 0 || entries.put(id, entry) != null) { throw new IllegalArgumentException("Invalid holding"); }
            }
            snapshot = new Wealth.Snapshot(nonnegative(raw, "time"), nonnegative(raw, "bankTime"), entries);
        }
        List<Wealth.Point> history = new ArrayList<>();
        long lastTime = -1;
        for (JsonElement value : root.getAsJsonArray("history"))
        {
            JsonObject p = value.getAsJsonObject();
            long time = nonnegative(p, "time");
            if (time < lastTime) { throw new IllegalArgumentException("Unordered history"); }
            history.add(new Wealth.Point(time, nonnegative(p, "total"), nonnegative(p, "alch"),
                nonnegative(p, "unique"), p.get("market").getAsLong(), p.get("items").getAsLong(),
                !p.has("attributed") || p.get("attributed").getAsBoolean()));
            lastTime = time;
        }
        if ((snapshot == null) != history.isEmpty()) { throw new IllegalArgumentException("Missing history baseline"); }
        if (snapshot != null && (snapshot.time != lastTime || snapshot.total() != history.get(history.size() - 1).total))
        { throw new IllegalArgumentException("Inconsistent snapshot"); }
        // Older files have no checkpoint; recover just their bank quantities, never their carried gear.
        Wealth.Bank bank = Wealth.Bank.from(snapshot);
        if (root.has("bankCheckpoint"))
        {
            JsonObject rawBank = root.getAsJsonObject("bankCheckpoint");
            Map<Integer, Long> quantities = new LinkedHashMap<>();
            for (JsonElement value : rawBank.getAsJsonArray("quantities"))
            {
                JsonObject holding = value.getAsJsonObject();
                int id = holding.get("id").getAsInt();
                long quantity = nonnegative(holding, "quantity");
                if (id < 0 || quantity == 0 || quantities.put(id, quantity) != null)
                { throw new IllegalArgumentException("Invalid bank checkpoint"); }
            }
            long time = nonnegative(rawBank, "time");
            if (time == 0) { throw new IllegalArgumentException("Missing bank observation time"); }
            if (bank == null || time >= bank.time) { bank = new Wealth.Bank(time, quantities); }
        }
        List<Wealth.Session> sessions = new ArrayList<>();
        if (root.has("sessions"))
        {
            for (JsonElement value : root.getAsJsonArray("sessions")) { sessions.add(decodeSession(value.getAsJsonObject())); }
        }
        Wealth.Session active = root.has("activeSession") ? decodeSession(root.getAsJsonObject("activeSession")) : null;
        Map<Integer, Long> herbSack = null;
        if (root.has("herbSack"))
        {
            herbSack = new LinkedHashMap<>();
            for (JsonElement value : root.getAsJsonArray("herbSack"))
            {
                JsonObject herb = value.getAsJsonObject();
                int id = herb.get("id").getAsInt();
                long quantity = nonnegative(herb, "quantity");
                if (id < 0 || quantity == 0 || herbSack.put(id, quantity) != null)
                { throw new IllegalArgumentException("Invalid herb sack contents"); }
            }
        }
        Map<String, Map<Integer, Long>> extraContainers = new LinkedHashMap<>();
        if (root.has("extraContainers"))
        {
            root.getAsJsonObject("extraContainers").entrySet().forEach(container ->
            {
                Map<Integer, Long> items = new LinkedHashMap<>();
                for (JsonElement value : container.getValue().getAsJsonArray())
                {
                    JsonObject item = value.getAsJsonObject();
                    int id = item.get("id").getAsInt();
                    long quantity = nonnegative(item, "quantity");
                    if (id < 0 || quantity == 0 || items.put(id, quantity) != null)
                    { throw new IllegalArgumentException("Invalid stored container quantity"); }
                }
                extraContainers.put(container.getKey(), items);
            });
        }
        return new Wealth.State(key, snapshot, history, nonnegative(root, "revision"), bank, sessions, active, herbSack, extraContainers);
    }

    private static long nonnegative(JsonObject object, String field)
    {
        long value = object.get(field).getAsLong();
        if (value < 0) { throw new IllegalArgumentException("Negative " + field); }
        return value;
    }
}

package com.atlas;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;

/** Bounded experimental RuneLite-config payloads and deterministic, non-destructive history merge. */
final class WealthSync
{
    static final String GROUP = "atlas";
    static final String PREFIX = "historyV1_";
    // Prototype budgets, not a claim about RuneLite server quotas. Never trim local history to fit.
    static final int MAX_ENCODED = 32_000;
    static final int MAX_DECODED = 4_000_000;

    static String encode(Wealth.State state, Gson gson) throws IOException
    {
        // A running session belongs to its device and is shared only once it has been closed/recovered.
        Wealth.State completed = new Wealth.State(state.profile, state.latest, state.history, 0, state.bank,
            state.sessions, null, state.herbSack, state.extraContainers);
        JsonObject envelope = new JsonObject();
        envelope.addProperty("syncSchema", 1);
        envelope.addProperty("profile", state.profile);
        envelope.addProperty("compact", true);
        envelope.add("state", pack(WealthStore.encode(completed)));
        byte[] plain = gson.toJson(envelope).getBytes(StandardCharsets.UTF_8);
        if (plain.length > MAX_DECODED) { throw new IOException("History exceeds the test sync size budget"); }
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (GZIPOutputStream gzip = new GZIPOutputStream(bytes)) { gzip.write(plain); }
        String encoded = Base64.getEncoder().encodeToString(bytes.toByteArray());
        if (encoded.length() > MAX_ENCODED) { throw new IOException("History exceeds the test sync size budget"); }
        return encoded;
    }

    static Wealth.State decode(String encoded, String profile, Gson gson) throws IOException
    {
        if (encoded == null || encoded.length() > MAX_ENCODED) { throw new IOException("Invalid sync payload size"); }
        try
        {
            ByteArrayOutputStream plain = new ByteArrayOutputStream();
            try (GZIPInputStream gzip = new GZIPInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(encoded))))
            {
                byte[] buffer = new byte[4096]; int count;
                while ((count = gzip.read(buffer)) != -1)
                {
                    if (plain.size() + count > MAX_DECODED) { throw new IOException("Expanded sync payload is too large"); }
                    plain.write(buffer, 0, count);
                }
            }
            JsonObject root = gson.fromJson(new String(plain.toByteArray(), StandardCharsets.UTF_8), JsonObject.class);
            if (root == null || root.get("syncSchema").getAsInt() != 1) { throw new IOException("Unknown sync version"); }
            if (!profile.equals(root.get("profile").getAsString())) { throw new IOException("Sync character does not match"); }
            JsonObject data = root.getAsJsonObject("state");
            Wealth.State state = WealthStore.decode(profile, root.has("compact") && root.get("compact").getAsBoolean() ? unpack(data) : data);
            if (state.activeSession != null) { throw new IOException("Sync payload contains a running session"); }
            return state;
        }
        catch (RuntimeException ex) { throw new IOException("Invalid sync payload", ex); }
    }

    /** Numeric rows avoid repeating field names and item labels; live capture resolves item names. */
    private static JsonObject pack(JsonObject state)
    {
        if (state.has("snapshot"))
        {
            JsonObject snapshot = state.getAsJsonObject("snapshot");
            JsonArray rows = new JsonArray();
            for (JsonElement element : snapshot.getAsJsonArray("entries"))
            {
                JsonObject item = element.getAsJsonObject();
                JsonArray row = row(item, "id", "bank", "inventory", "equipment", "price", "alch", "bankPouch", "bankSack", "deployed");
                row.add((item.get("members").getAsBoolean() ? 1 : 0) | (item.get("tradeable").getAsBoolean() ? 2 : 0)
                    | (item.get("unpriced").getAsBoolean() ? 4 : 0));
                rows.add(row);
            }
            snapshot.remove("entries"); snapshot.add("rows", rows);
        }
        JsonArray points = new JsonArray();
        for (JsonElement element : state.getAsJsonArray("history"))
        { points.add(row(element.getAsJsonObject(), "time", "total", "alch", "unique", "market", "items", "attributed")); }
        state.remove("history"); state.add("points", points);
        JsonArray sessions = new JsonArray();
        for (JsonElement element : state.getAsJsonArray("sessions"))
        { sessions.add(row(element.getAsJsonObject(), "start", "end", "change", "estimated", "interrupted")); }
        state.add("sessions", sessions);
        if (state.has("bankCheckpoint"))
        {
            JsonObject bank = state.getAsJsonObject("bankCheckpoint");
            bank.add("quantities", packQuantities(bank.getAsJsonArray("quantities")));
        }
        if (state.has("herbSack")) { state.add("herbSack", packQuantities(state.getAsJsonArray("herbSack"))); }
        state.getAsJsonObject("extraContainers").entrySet().forEach(e ->
            e.setValue(packQuantities(e.getValue().getAsJsonArray())));
        return state;
    }

    private static JsonObject unpack(JsonObject state)
    {
        if (state.has("snapshot"))
        {
            JsonObject snapshot = state.getAsJsonObject("snapshot");
            JsonArray entries = new JsonArray();
            for (JsonElement element : snapshot.getAsJsonArray("rows"))
            {
                JsonArray row = element.getAsJsonArray();
                if (row.size() != 10) { throw new IllegalArgumentException("Invalid item row"); }
                JsonObject item = object(row, "id", "bank", "inventory", "equipment", "price", "alch", "bankPouch", "bankSack", "deployed");
                int flags = row.get(9).getAsInt();
                item.addProperty("members", (flags & 1) != 0); item.addProperty("tradeable", (flags & 2) != 0);
                item.addProperty("unpriced", (flags & 4) != 0);
                item.addProperty("name", "Item #" + item.get("id").getAsInt());
                entries.add(item);
            }
            snapshot.remove("rows"); snapshot.add("entries", entries);
        }
        JsonArray points = new JsonArray();
        for (JsonElement row : state.getAsJsonArray("points"))
        { points.add(object(row.getAsJsonArray(), "time", "total", "alch", "unique", "market", "items", "attributed")); }
        state.remove("points"); state.add("history", points);
        JsonArray sessions = new JsonArray();
        for (JsonElement row : state.getAsJsonArray("sessions"))
        { sessions.add(object(row.getAsJsonArray(), "start", "end", "change", "estimated", "interrupted")); }
        state.add("sessions", sessions);
        if (state.has("bankCheckpoint"))
        {
            JsonObject bank = state.getAsJsonObject("bankCheckpoint");
            bank.add("quantities", unpackQuantities(bank.getAsJsonArray("quantities")));
        }
        if (state.has("herbSack")) { state.add("herbSack", unpackQuantities(state.getAsJsonArray("herbSack"))); }
        state.getAsJsonObject("extraContainers").entrySet().forEach(e ->
            e.setValue(unpackQuantities(e.getValue().getAsJsonArray())));
        return state;
    }

    private static JsonArray row(JsonObject object, String... fields)
    {
        JsonArray row = new JsonArray();
        for (String field : fields) { row.add(object.get(field)); }
        return row;
    }

    private static JsonObject object(JsonArray row, String... fields)
    {
        if (row.size() < fields.length) { throw new IllegalArgumentException("Truncated sync row"); }
        JsonObject object = new JsonObject();
        for (int i = 0; i < fields.length; i++) { object.add(fields[i], row.get(i)); }
        return object;
    }

    private static JsonArray packQuantities(JsonArray quantities)
    {
        JsonArray rows = new JsonArray();
        for (JsonElement item : quantities) { rows.add(row(item.getAsJsonObject(), "id", "quantity")); }
        return rows;
    }

    private static JsonArray unpackQuantities(JsonArray rows)
    {
        JsonArray quantities = new JsonArray();
        for (JsonElement row : rows) { quantities.add(object(row.getAsJsonArray(), "id", "quantity")); }
        return quantities;
    }

    static Wealth.State merge(Wealth.State local, List<Wealth.State> remote, boolean importHoldings)
    {
        List<Wealth.State> sources = new ArrayList<>(); sources.add(local); sources.addAll(remote);
        Map<Long, Sample> samples = new TreeMap<>();
        Map<Long, Wealth.Session> sessions = new TreeMap<>();
        Wealth.Snapshot latest = local.latest;
        Wealth.State holdings = local;
        Wealth.State bankOwner = local;
        for (Wealth.State source : sources)
        {
            if (!local.profile.equals(source.profile)) { throw new IllegalArgumentException("Wrong sync character"); }
            Wealth.Point previous = null;
            for (Wealth.Point point : source.history)
            {
                Sample sample = new Sample(point, previous);
                samples.merge(point.time, sample, WealthSync::chooseSample);
                previous = point;
            }
            for (Wealth.Session session : source.sessions)
            {
                // Never import an older checkpoint over this device's still-running session.
                if (local.activeSession == null || session.start != local.activeSession.start)
                { sessions.merge(session.start, session, WealthSync::chooseSession); }
            }
            if (source.latest != null && (latest == null || compareSnapshots(source.latest, latest) > 0))
            { latest = source.latest; }
            if (holdingsTime(source) > holdingsTime(holdings)) { holdings = source; }
            if (source.bank != null && (bankOwner.bank == null || source.bank.time > bankOwner.bank.time
                || (source.bank.time == bankOwner.bank.time && holdingsTime(source) > holdingsTime(bankOwner))))
            { bankOwner = source; }
        }
        List<Wealth.Point> points = new ArrayList<>();
        Wealth.Point previous = null;
        long market = 0, items = 0;
        for (Sample sample : samples.values())
        {
            Wealth.Point p = sample.point;
            boolean known = previous == null || (sample.previousTime == previous.time && p.attributed);
            if (previous != null)
            {
                long marketDelta = known ? sample.marketDelta : 0;
                market += marketDelta;
                items += p.total - previous.total - marketDelta;
            }
            previous = new Wealth.Point(p.time, p.total, p.alch, p.unique, market, items, known);
            points.add(previous);
        }
        if (latest != null && !points.isEmpty())
        {
            // The final snapshot and the final graph endpoint must represent the same observation.
            Wealth.Point last = points.get(points.size() - 1);
            if (latest.time != last.time || latest.total() != last.total)
            { throw new IllegalArgumentException("Inconsistent merged history endpoint"); }
        }
        Wealth.State carry = importHoldings ? holdings : local;
        Wealth.Bank bank = importHoldings ? bankOwner.bank : local.bank;
        Map<String, Map<Integer, Long>> extra = new LinkedHashMap<>(carry.extraContainers);
        if (importHoldings && bank != null && carry.bank == null && holdingsTime(carry) > bank.time)
        {
            Map<Integer, Long> credits = extra.get(SoulBearerTracker.REMOTE_BANK_KEY);
            if (credits != null && !credits.isEmpty())
            {
                Map<Integer, Long> quantities = new LinkedHashMap<>(bank.quantities);
                credits.forEach((id, quantity) -> quantities.merge(id, quantity, Long::sum));
                bank = new Wealth.Bank(bank.time, quantities);
                extra.put(SoulBearerTracker.REMOTE_BANK_KEY, java.util.Collections.emptyMap());
            }
        }
        return new Wealth.State(local.profile, latest, points, local.revision + 1, bank,
            new ArrayList<>(sessions.values()), local.activeSession, carry.herbSack, extra);
    }

    private static long holdingsTime(Wealth.State state)
    {
        long time = state.latest == null ? 0 : state.latest.time;
        if (state.bank != null) { time = Math.max(time, state.bank.time); }
        if (state.activeSession != null) { time = Math.max(time, state.activeSession.end); }
        for (Wealth.Session session : state.sessions) { time = Math.max(time, session.end); }
        return time;
    }

    private static int compareSnapshots(Wealth.Snapshot a, Wealth.Snapshot b)
    {
        int time = Long.compare(a.time, b.time);
        if (time != 0) { return time; }
        int total = Long.compare(a.total(), b.total());
        if (total != 0) { return total; }
        int alch = Long.compare(a.alch(), b.alch());
        return alch != 0 ? alch : Integer.compare(a.items.size(), b.items.size());
    }

    private static Wealth.Session chooseSession(Wealth.Session a, Wealth.Session b)
    {
        Comparator<Wealth.Session> order = Comparator.comparingLong((Wealth.Session s) -> s.end)
            .thenComparing(s -> !s.interrupted).thenComparingLong(s -> s.change).thenComparing(s -> s.estimated);
        return order.compare(a, b) >= 0 ? a : b;
    }

    private static Sample chooseSample(Sample a, Sample b)
    {
        Comparator<Sample> order = Comparator.comparingLong((Sample s) -> s.point.total)
            .thenComparingLong(s -> s.point.alch).thenComparingLong(s -> s.point.unique)
            .thenComparingLong(s -> s.previousTime).thenComparing(s -> s.point.attributed)
            .thenComparingLong(s -> s.marketDelta);
        return order.compare(a, b) >= 0 ? a : b;
    }

    private static final class Sample
    {
        final Wealth.Point point;
        final long previousTime, marketDelta;
        Sample(Wealth.Point point, Wealth.Point previous)
        {
            this.point = point; previousTime = previous == null ? -1 : previous.time;
            marketDelta = previous == null ? 0 : point.market - previous.market;
        }
    }
}

