public class CannonTrackerTest
{
    private static final int[] NORMAL = {ItemID.TWPART1, ItemID.TWPART2, ItemID.TWPART3, ItemID.TWPART4};
    private static final int[] SKINNED = {ItemID.LEAGUE_3_MULTICANNON_BASE, ItemID.LEAGUE_3_MULTICANNON_STAND,
        ItemID.LEAGUE_3_MULTICANNON_BARRELS, ItemID.LEAGUE_3_MULTICANNON_FURNACE};
    private static final Item[] EMPTY = new Item[0];

    private Item[] inventory(int[] parts, int assembly, int balls)
    {
        List<Item> inventory = new ArrayList<>();
        for (int component = assembly; component < parts.length; component++) { inventory.add(new Item(parts[component], 1)); }
        if (balls > 0) { inventory.add(new Item(ItemID.MCANNONBALL, balls)); }
        return inventory.toArray(EMPTY);
    }

    private Wealth.Snapshot observe(CannonTracker cannon, HoldingsTracker holdings, int assembly, Item[] inventory, long time)
    {
        cannon.observe(assembly, false, inventory, id -> id);
        Map<Integer, long[]> counts = holdings.combine(inventory, EMPTY);
        cannon.deployed().forEach((id, quantity) -> counts.computeIfAbsent(id, ignored -> new long[3]));
        Map<Integer, Wealth.Entry> entries = new LinkedHashMap<>();
        counts.forEach((id, q) -> entries.put(id, new Wealth.Entry(id, "Item " + id, q[0], q[1], q[2],
            id == ItemID.MCANNONBALL ? 200 : id >= ItemID.LEAGUE_3_MULTICANNON_BASE ? 180_000 : 150_000,
            0, true, true, false, 0, 0, cannon.deployed().getOrDefault(id, 0L))));
        return new Wealth.Snapshot(time, holdings.getBankTime(), entries);
    }

    private HoldingsTracker holdings()
    {
        HoldingsTracker holdings = new HoldingsTracker(id -> id, id -> false);
        holdings.observeBank(EMPTY, 100);
        return holdings;
    }

    @Test
    public void regularAndSkinnedCannonsRemainOwnedThroughEveryAssemblyStageAndPickup()
    {
        for (int[] parts : new int[][]{NORMAL, SKINNED})
        {
            CannonTracker cannon = new CannonTracker(); HoldingsTracker holdings = holdings();
            Wealth.Snapshot start = observe(cannon, holdings, 0, inventory(parts, 0, 100), 110);
            SessionTracker session = new SessionTracker(100); session.observe(start, true);
            for (int stage = 1; stage <= 4; stage++)
            {
                Wealth.Snapshot next = observe(cannon, holdings, stage, inventory(parts, stage, 100), 110 + stage);
                session.observe(next, true);
                assertEquals(start.total(), next.total());
                assertEquals(0L, session.current().change);
                assertEquals(stage, cannon.deployed().size());
                assertTrue(cannon.deployed().containsKey(parts[stage - 1]));
                assertFalse(cannon.estimated());
            }
            Wealth.Snapshot pickedUp = observe(cannon, holdings, 0, inventory(parts, 0, 100), 120);
            session.observe(pickedUp, true);
            assertEquals(start.total(), pickedUp.total());
            assertEquals(0L, session.current().change);
            assertEquals(0L, pickedUp.deployed());
        }
    }

    @Test
    public void assemblyCompletingBetweenCapturesStillRecognizesEverySkinnedPiece()
    {
        CannonTracker cannon = new CannonTracker(); HoldingsTracker holdings = holdings();
        Wealth.Snapshot start = observe(cannon, holdings, 0, inventory(SKINNED, 0, 0), 110);
        Wealth.Snapshot placed = observe(cannon, holdings, 4, EMPTY, 120);
        assertEquals(start.total(), placed.total());
        assertEquals(720_000L, placed.deployed());
        for (int id : SKINNED) { assertTrue(cannon.deployed().containsKey(id)); }
    }

    @Test
    public void loadingBallsIsStillALossAndUnusedBallsReturnedOnPickupOffsetThatCost()
    {
        CannonTracker cannon = new CannonTracker(); HoldingsTracker holdings = holdings();
        SessionTracker session = new SessionTracker(100);
        session.observe(observe(cannon, holdings, 0, inventory(SKINNED, 0, 100), 110), true);
        session.observe(observe(cannon, holdings, 4, inventory(SKINNED, 4, 70), 120), true);
        assertEquals(-6000L, session.current().change); // 30 balls loaded at 200 GP each.
        // Firing is not counted again: loaded cannonballs have already left tracked inventory.
        session.observe(observe(cannon, holdings, 4, inventory(SKINNED, 4, 70), 130), true);
        assertEquals(-6000L, session.current().change);
        session.observe(observe(cannon, holdings, 0, inventory(SKINNED, 0, 80), 140), true);
        assertEquals(-4000L, session.current().change); // Ten unused balls returned; twenty spent.
    }

    @Test
    public void savedSkinnedCannonRestoresWithoutABankVisitAndPickupDoesNotDoubleCount()
    {
        CannonTracker cannon = new CannonTracker(); HoldingsTracker holdings = holdings();
        observe(cannon, holdings, 0, inventory(SKINNED, 0, 0), 110);
        Wealth.Snapshot placed = observe(cannon, holdings, 4, EMPTY, 120);
        Wealth.State saved = Wealth.State.empty("test").withExtraContainers(
            Collections.singletonMap(CannonTracker.STORAGE_KEY, cannon.deployed())).append(placed, Collections.emptyMap());
        Wealth.State loaded = WealthStore.decode("test", WealthStore.encode(saved));
        assertTrue(loaded.bank.quantities.isEmpty()); // Deployed parts must never become saved bank items.
        assertEquals(720_000L, loaded.latest.deployed());
        CannonTracker restored = new CannonTracker(); restored.restore(loaded.extraContainers.get(CannonTracker.STORAGE_KEY));
        Wealth.Snapshot resumed = observe(restored, holdings, 4, EMPTY, 130);
        assertEquals(placed.total(), resumed.total());
        SessionTracker session = new SessionTracker(125); session.observe(resumed, false);
        Wealth.Snapshot pickedUp = observe(restored, holdings, 0, inventory(SKINNED, 0, 0), 140);
        session.observe(pickedUp, false, restored.takeReconciliation());
        assertEquals(placed.total(), pickedUp.total());
        assertEquals(0L, session.current().change);
    }

    @Test
    public void unknownSkinOnFirstDeployedLoginIsAnEstimateAndDiscoveryIsNotProfit()
    {
        CannonTracker cannon = new CannonTracker(); HoldingsTracker holdings = holdings();
        Wealth.Snapshot unknown = observe(cannon, holdings, 4, EMPTY, 110);
        assertTrue(cannon.estimated());
        assertEquals(600_000L, unknown.deployed());
        SessionTracker session = new SessionTracker(100); session.observe(unknown, true);
        Wealth.Snapshot actual = observe(cannon, holdings, 0, inventory(SKINNED, 0, 0), 120);
        assertTrue(cannon.takeReconciliation());
        session.observe(actual, true, true);
        assertEquals(0L, session.current().change);
        assertEquals(720_000L, actual.total());
    }

    @Test
    public void decayedRecoverableCannonKeepsItsOwnedPieces()
    {
        CannonTracker cannon = new CannonTracker(); HoldingsTracker holdings = holdings();
        observe(cannon, holdings, 0, inventory(SKINNED, 0, 0), 110);
        observe(cannon, holdings, 4, EMPTY, 120);
        cannon.observe(0, true, EMPTY, id -> id);
        assertEquals(4, cannon.deployed().size());
        for (int id : SKINNED) { assertEquals(1L, (long) cannon.deployed().get(id)); }
    }

    @Test
    public void extraCopiesInBankAndInventoryAreNotMistakenForTheDeployedSet()
    {
        CannonTracker cannon = new CannonTracker(); HoldingsTracker holdings = holdings();
        holdings.observeBank(inventory(NORMAL, 0, 0), 100);
        Item[] carried = inventory(SKINNED, 0, 0);
        Wealth.Snapshot start = observe(cannon, holdings, 0, carried, 110);
        Wealth.Snapshot placed = observe(cannon, holdings, 4, EMPTY, 120);
        assertEquals(start.total(), placed.total());
        assertEquals(600_000L, placed.bank());
        assertEquals(720_000L, placed.deployed());
        assertEquals(1_320_000L, placed.total());
    }

    @Test
    public void noDeploymentMeansNoImaginedCannonAndNoCompensationForOrdinaryLosses()
    {
        CannonTracker cannon = new CannonTracker(); HoldingsTracker holdings = holdings();
        SessionTracker session = new SessionTracker(100);
        session.observe(observe(cannon, holdings, 0, inventory(NORMAL, 0, 0), 110), true);
        session.observe(observe(cannon, holdings, 0, EMPTY, 120), true);
        assertEquals(-600_000L, session.current().change); // Dropping/trading parts is still a loss.
        assertTrue(cannon.deployed().isEmpty());
        assertFalse(CannonTracker.isPart(ItemID.MCANNONBALL));
        assertFalse(CannonTracker.isPart(ItemID.GRANITE_CANNONBALL));
        assertFalse(CannonTracker.isPart(ItemID.LEAGUE_3_MULTICANNON_PACK));
    }

    @Test
    public void legacyHistoryWithoutDeployedFieldStillLoadsAndResetSeparatesCharacters()
    {
        CannonTracker cannon = new CannonTracker(); HoldingsTracker holdings = holdings();
        Wealth.Snapshot start = observe(cannon, holdings, 0, inventory(NORMAL, 0, 0), 110);
        Wealth.State state = Wealth.State.empty("test").append(start, Collections.emptyMap());
        JsonObject old = WealthStore.encode(state);
        old.getAsJsonObject("snapshot").getAsJsonArray("entries").forEach(e -> e.getAsJsonObject().remove("deployed"));
        assertEquals(start.total(), WealthStore.decode("test", old).latest.total());
        observe(cannon, holdings, 4, EMPTY, 120);
        cannon.reset();
        assertTrue(cannon.deployed().isEmpty());
        cannon.observe(0, false, EMPTY, id -> id);
        assertFalse(cannon.estimated());
    }
}

package com.atlas;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.InterfaceID;
import org.junit.Test;
import static org.junit.Assert.*;

public class ContainerUseTest
{
    private static final Item[] EMPTY = new Item[0];

    @Test
    public void selectedInventorySlotFallbackDoesNotMistakeASpellForAnInventoryItem()
    {
        Item[] inventory = {new Item(ItemID.SLAYER_HERB_SACK, 1)};
        assertEquals(ItemID.SLAYER_HERB_SACK,
            ContainerUse.inventoryItem(InterfaceID.Inventory.ITEMS, -1, 0, inventory));
        assertEquals(ItemID.UNIDENTIFIED_TORSTOL,
            ContainerUse.inventoryItem(InterfaceID.Inventory.ITEMS, ItemID.UNIDENTIFIED_TORSTOL, -1, inventory));
        assertEquals(-1, ContainerUse.inventoryItem(InterfaceID.Bankmain.DEPOSITINV, -1, 0, inventory));
        assertEquals(-1, ContainerUse.inventoryItem(InterfaceID.Inventory.ITEMS, -1, -1, inventory));
    }

    @Test
    public void torstolOnSackPreservesNetWorthAndSessionInsteadOfLosing3671Gp()
    {
        for (boolean reverse : new boolean[]{false, true})
        {
            int herb = ItemID.UNIDENTIFIED_TORSTOL;
            int sackId = ItemID.SLAYER_HERB_SACK_OPEN;
            int selected = reverse ? sackId : herb;
            int target = reverse ? herb : sackId;
            HerbSackTracker sack = new HerbSackTracker();
            sack.restore(Collections.emptyMap());
            Item[] before = {new Item(herb, 1), new Item(sackId, 1)};
            Item[] after = {new Item(-1, 0), before[1]};
            HoldingsTracker holdings = new HoldingsTracker(id -> id, id -> false);
            holdings.observeBank(EMPTY, 100);
            Wealth.Snapshot start = snapshot(holdings.combine(before, EMPTY), 110, herb, 3671);
            SessionTracker session = new SessionTracker(100);
            session.observe(start, true);
            assertEquals(sackId, ContainerUse.container(selected, target));
            sack.beginItemUse(ContainerUse.storedItem(selected, target), before, null, 10);
            assertFalse(sack.finishTransfer(before, null, 11));
            // Some storage actions also send the pickup-looking message; the transfer counts once.
            assertFalse(sack.chat("You put the Grimy torstol herb into your herb sack."));
            assertTrue(sack.finishTransfer(after, null, 12));
            assertEquals(1L, (long) sack.contents().get(herb));
            Map<Integer, long[]> counts = holdings.combine(after, EMPTY);
            sack.include(counts);
            Wealth.Snapshot end = snapshot(counts, 120, herb, 3671);
            session.observe(end, true);
            assertEquals(3671L, end.total());
            assertEquals(start.total(), end.total());
            assertEquals(0L, session.current().change);
            assertFalse(sack.finishTransfer(after, null, 13));
        }
    }

    @Test
    public void seedStacksAndEveryGemVariantTransferWithoutSessionLossInEitherDirection()
    {
        for (BagTracker.Kind kind : BagTracker.Kind.values())
        {
            for (boolean reverse : new boolean[]{false, true})
            {
                int id = kind.seeds() ? ItemID.RANARR_SEED : kind.semiPrecious ? ItemID.UNCUT_OPAL : ItemID.UNCUT_SAPPHIRE;
                int quantity = kind.seeds() ? 150 : 3;
                BagTracker bag = new BagTracker(kind, name -> id, item -> item == id);
                bag.restore(Collections.emptyMap());
                Item[] before = {new Item(id, quantity), new Item(kind.closed, 1)};
                Item[] after = {new Item(-1, 0), before[1]};
                int selected = reverse ? kind.closed : id;
                int target = reverse ? id : kind.closed;
                assertEquals(kind.closed, ContainerUse.container(selected, target));
                HoldingsTracker holdings = new HoldingsTracker(item -> item, item -> false);
                holdings.observeBank(EMPTY, 100);
                Wealth.Snapshot start = snapshot(holdings.combine(before, EMPTY), 110, id, 1000);
                SessionTracker session = new SessionTracker(100);
                session.observe(start, true);
                bag.beginItemUse(ContainerUse.storedItem(selected, target), before, null, 10);
                if (kind.seeds()) { assertFalse(bag.chat("Stored 150 x Ranarr seed in your seed box.", 10)); }
                else { assertFalse(bag.chat("You put a gem in your " + kind.name + ": Uncut "
                    + (kind.semiPrecious ? "opal" : "sapphire"), 10)); }
                assertTrue(kind.name, bag.finishTransfer(after, null, 12));
                assertEquals(quantity, (long) bag.contents().get(id));
                Map<Integer, long[]> counts = holdings.combine(after, EMPTY);
                bag.include(counts);
                Wealth.Snapshot end = snapshot(counts, 120, id, 1000);
                session.observe(end, true);
                assertEquals(kind.name, start.total(), end.total());
                assertEquals(kind.name, 0L, session.current().change);
            }
        }
    }

    @Test
    public void fullBagOrFailedUseNeverInventsStoredItems()
    {
        BagTracker bag = new BagTracker(BagTracker.Kind.GEM_POUCH, name -> -1, id -> false);
        bag.restore(Collections.singletonMap(ItemID.UNCUT_OPAL, 5L));
        Item[] inventory = {new Item(ItemID.GEM_POUCH, 1), new Item(ItemID.UNCUT_OPAL, 1)};
        bag.beginItemUse(ItemID.UNCUT_OPAL, inventory, null, 10);
        assertFalse(bag.finishTransfer(inventory, null, 12));
        assertFalse(bag.finishTransfer(EMPTY, null, 19)); // Expired action is not interpreted as a fill.
        assertEquals(5L, (long) bag.contents().get(ItemID.UNCUT_OPAL));
    }

    @Test
    public void usingOneHerbDoesNotAttributeUnrelatedDisappearingHerbsToTheSack()
    {
        HerbSackTracker sack = new HerbSackTracker();
        sack.restore(Collections.emptyMap());
        Item[] before = {new Item(ItemID.UNIDENTIFIED_TORSTOL, 1), new Item(ItemID.UNIDENTIFIED_RANARR, 1)};
        sack.beginItemUse(ItemID.UNIDENTIFIED_TORSTOL, before, null, 10);
        assertTrue(sack.finishTransfer(EMPTY, null, 12));
        assertEquals(1, sack.contents().size());
        assertEquals(1L, (long) sack.contents().get(ItemID.UNIDENTIFIED_TORSTOL));
    }

    @Test
    public void wrongGemAndInvalidSelectionsDoNotStartStorageTransfers()
    {
        assertEquals(-1, ContainerUse.container(-1, ItemID.GEM_BAG));
        assertEquals(-1, ContainerUse.container(ItemID.UNCUT_SAPPHIRE, ItemID.UNCUT_RUBY));
        assertEquals(-1, ContainerUse.container(ItemID.GEM_BAG, ItemID.SLAYER_HERB_SACK));
        BagTracker pouch = new BagTracker(BagTracker.Kind.GEM_POUCH, name -> -1, id -> false);
        pouch.restore(Collections.emptyMap());
        pouch.beginItemUse(ItemID.UNCUT_SAPPHIRE, new Item[]{new Item(ItemID.UNCUT_SAPPHIRE, 1)}, null, 10);
        assertFalse(pouch.finishTransfer(EMPTY, null, 12));
        assertTrue(pouch.contents().isEmpty());
    }

    @Test
    public void itemOnContainerAtBankUsesCombinedQuantitiesAndHandlesPartialFill()
    {
        HerbSackTracker sack = new HerbSackTracker();
        sack.restore(Collections.emptyMap());
        int herb = ItemID.UNIDENTIFIED_TORSTOL;
        Item[] bank = {new Item(herb, 10)};
        sack.beginItemUse(herb, new Item[]{new Item(herb, 3)}, bank, 10);
        assertTrue(sack.finishTransfer(new Item[]{new Item(herb, 1)}, bank, 12));
        assertEquals(2L, (long) sack.contents().get(herb));
        // A loose item moving to the bank is not a successful item-on-sack fill.
        sack.beginItemUse(herb, new Item[]{new Item(herb, 1)}, bank, 13);
        assertFalse(sack.finishTransfer(EMPTY, new Item[]{new Item(herb, 11)}, 15));
        assertEquals(2L, (long) sack.contents().get(herb));
    }

    private static Wealth.Snapshot snapshot(Map<Integer, long[]> quantities, long time, int valuedItem, long price)
    {
        Map<Integer, Wealth.Entry> entries = new LinkedHashMap<>();
        quantities.forEach((id, q) -> entries.put(id, new Wealth.Entry(id, "Item", q[0], q[1], q[2],
            id == valuedItem ? price : 0, 0, true, true, false)));
        return new Wealth.Snapshot(time, 100, entries);
    }
}

package com.atlas;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class HerbSackTrackerTest
{
    private static final int HERB = ItemID.UNIDENTIFIED_RANARR;
    private static final Item[] EMPTY = new Item[0];
    private static final Item SACK = new Item(ItemID.SLAYER_HERB_SACK_OPEN, 1);

    private HerbSackTracker checked(long quantity)
    {
        HerbSackTracker tracker = new HerbSackTracker();
        tracker.chat("You look in your herb sack and see:");
        if (quantity > 0) { tracker.chat(quantity + " x Grimy ranarr weed"); }
        tracker.finishCheck();
        tracker.takeReconciliation();
        return tracker;
    }

    private Wealth.Snapshot snapshot(HoldingsTracker holdings, HerbSackTracker sack, Item[] inventory, long time)
    {
        Map<Integer, long[]> quantities = holdings.combine(inventory, EMPTY);
        Map<Integer, Long> bankSack = sack.include(quantities);
        Map<Integer, Wealth.Entry> entries = new LinkedHashMap<>();
        quantities.forEach((id, q) -> entries.put(id, new Wealth.Entry(id, "Item " + id, q[0], q[1], q[2],
            id == HERB ? 7000 : 0, 1, true, true, false, 0, bankSack.getOrDefault(id, 0L))));
        return new Wealth.Snapshot(time, holdings.getBankTime(), entries);
    }

    @Test
    public void checkReplacesFullContentsTogetherWithoutTreatingDiscoveryAsLoot()
    {
        HerbSackTracker sack = checked(2);
        sack.chat("You look in your herb sack and see:");
        sack.chat("1 x Grimy guam leaf");
        sack.chat("5 x Grimy ranarr weed");
        assertEquals(2L, (long) sack.contents().get(HERB));
        assertTrue(sack.finishCheck());
        assertEquals(2, sack.contents().size());
        assertEquals(5L, (long) sack.contents().get(HERB));
        assertTrue(sack.takeReconciliation());
        assertFalse(sack.takeReconciliation());
        assertTrue(sack.confirmed());
    }

    @Test
    public void pickupImmediatelyAddsOneHerbAndSessionGain()
    {
        HerbSackTracker sack = checked(2);
        HoldingsTracker holdings = new HoldingsTracker(id -> id, id -> false);
        holdings.observeBank(EMPTY, 100);
        SessionTracker session = new SessionTracker(100);
        session.observe(snapshot(holdings, sack, new Item[]{SACK}, 110), true);
        assertTrue(sack.chat("You put the Grimy ranarr weed herb into your herb sack."));
        Wealth.Snapshot next = snapshot(holdings, sack, new Item[]{SACK}, 120);
        session.observe(next, true);
        assertEquals(21_000L, next.inventory());
        assertEquals(7000L, session.current().change);
    }

    @Test
    public void unknownStartingContentsTrackNewPickupsButNeedCheckToConfirm()
    {
        HerbSackTracker sack = new HerbSackTracker();
        assertNull(sack.contents());
        sack.chat("You put the Grimy ranarr weed herb into your herb sack.");
        assertEquals(1L, (long) sack.contents().get(HERB));
        assertFalse(sack.confirmed());
        sack.chat("You look in your herb sack and see:");
        sack.chat("10 x Grimy ranarr weed");
        sack.finishCheck();
        assertEquals(10L, (long) sack.contents().get(HERB));
        assertTrue(sack.takeReconciliation());
    }

    @Test
    public void checkMessagesOutsideBatchAndOtherPluginPriceOutputDoNotAddHerbs()
    {
        HerbSackTracker sack = checked(2);
        assertFalse(sack.chat("99 x Grimy ranarr weed"));
        assertFalse(sack.chat("Total value of herbs in sack: 14,000"));
        assertFalse(sack.chat("You put the Grimy mystery herb into your herb sack."));
        assertEquals(2L, (long) sack.contents().get(HERB));
    }

    @Test
    public void emptyCheckResetsOldContentsAndSilklinedVariantIsRecognized()
    {
        HerbSackTracker sack = checked(2);
        sack.chat("The herb sack is empty.");
        sack.finishCheck();
        assertTrue(sack.contents().isEmpty());
        sack.chat("You look in your silklined herb sack and see:");
        sack.chat("1 x Grimy huasca");
        sack.finishCheck();
        assertEquals(1L, (long) sack.contents().get(ItemID.UNIDENTIFIED_HUASCA));
        assertTrue(sack.chat("You put the Grimy huasca herb into your silklined herb sack."));
        assertEquals(2L, (long) sack.contents().get(ItemID.UNIDENTIFIED_HUASCA));
    }

    @Test
    public void fillCountsCompletedInventoryDifferenceAndNeverCountsClickAsSuccess()
    {
        HerbSackTracker sack = checked(2);
        Item[] before = {SACK, new Item(HERB, 5)};
        sack.beginTransfer("Fill", before, 10);
        assertFalse(sack.finishTransfer(before, 11));
        assertEquals(2L, (long) sack.contents().get(HERB));
        assertFalse(sack.chat("You put the Grimy ranarr weed herb into your herb sack."));
        assertTrue(sack.finishTransfer(new Item[]{SACK, new Item(HERB, 2)}, 12));
        assertEquals(5L, (long) sack.contents().get(HERB));
    }

    @Test
    public void fillingAndEmptyingInventoryAreNeutralTransfersForSessionAndTotal()
    {
        HerbSackTracker sack = checked(2);
        HoldingsTracker holdings = new HoldingsTracker(id -> id, id -> false);
        holdings.observeBank(EMPTY, 100);
        Item[] loose = {SACK, new Item(HERB, 5)};
        SessionTracker session = new SessionTracker(100);
        Wealth.Snapshot before = snapshot(holdings, sack, loose, 110);
        session.observe(before, true);
        sack.beginTransfer("Fill", loose, 10);
        sack.finishTransfer(new Item[]{SACK}, 12);
        Wealth.Snapshot filled = snapshot(holdings, sack, new Item[]{SACK}, 120);
        session.observe(filled, true);
        assertEquals(before.total(), filled.total());
        assertEquals(0L, session.current().change);
        sack.beginTransfer("Empty", new Item[]{SACK}, 13);
        Item[] emptied = {SACK, new Item(HERB, 7)};
        sack.finishTransfer(emptied, 15);
        Wealth.Snapshot after = snapshot(holdings, sack, emptied, 130);
        session.observe(after, true);
        assertEquals(before.total(), after.total());
        assertEquals(0L, session.current().change);
    }

    @Test
    public void partialEmptySubtractsOnlyHerbsActuallyMovedToInventory()
    {
        HerbSackTracker sack = checked(10);
        sack.beginTransfer("Empty", new Item[]{SACK, new Item(HERB, 2)}, 10);
        assertTrue(sack.finishTransfer(new Item[]{SACK, new Item(HERB, 5)}, 12));
        assertEquals(7L, (long) sack.contents().get(HERB));
        assertFalse(sack.finishTransfer(new Item[]{SACK, new Item(HERB, 5)}, 13));
    }

    @Test
    public void failedOrExpiredTransferDoesNotChangeContents()
    {
        HerbSackTracker sack = checked(10);
        sack.beginTransfer("Empty", new Item[]{SACK}, 10);
        assertFalse(sack.finishTransfer(new Item[]{SACK}, 12));
        assertFalse(sack.finishTransfer(new Item[]{SACK, new Item(HERB, 10)}, 19));
        assertEquals(10L, (long) sack.contents().get(HERB));
    }

    @Test
    public void emptyingIntoBankDoesNotCreateProfitOrDuplicateOnRestart()
    {
        HerbSackTracker sack = checked(10);
        HoldingsTracker holdings = new HoldingsTracker(id -> id, id -> false);
        holdings.observeBank(new Item[]{new Item(HERB, 5)}, 100);
        Wealth.Snapshot before = snapshot(holdings, sack, new Item[]{SACK}, 110);
        sack.beginTransfer("Empty to bank", new Item[]{new Item(HERB, 5)}, 10);
        assertTrue(sack.transferringToBank());
        Item[] bankAfter = {new Item(HERB, 15)};
        holdings.observeBank(bankAfter, 120);
        assertTrue(sack.finishTransfer(bankAfter, 12));
        Wealth.Snapshot after = snapshot(holdings, sack, new Item[]{SACK}, 120);
        assertEquals(before.total(), after.total());
        SessionTracker session = new SessionTracker(100);
        session.observe(before, true);
        session.observe(after, true);
        assertEquals(0L, session.current().change);
        Wealth.State state = Wealth.State.empty("test").withHerbSack(sack.contents()).append(after, Collections.emptyMap());
        Wealth.State loaded = WealthStore.decode("test", WealthStore.encode(state));
        assertTrue(loaded.herbSack.isEmpty());
        assertEquals(15L, (long) loaded.bank.quantities.get(HERB));
    }

    @Test
    public void pickupThenContextualEmptyOrDepositAtBankBooksLootOnlyOnce()
    {
        for (String option : new String[]{"Empty", "Empty to bank", "Deposit", "Deposit-All"})
        {
            HerbSackTracker sack = checked(0);
            HoldingsTracker holdings = new HoldingsTracker(id -> id, id -> false);
            holdings.observeBank(new Item[]{new Item(HERB, 5)}, 100);
            Item[] inventory = {SACK};
            SessionTracker session = new SessionTracker(100);
            session.observe(snapshot(holdings, sack, inventory, 110), true);
            sack.chat("You put the Grimy ranarr weed herb into your herb sack.");
            Wealth.Snapshot pickup = snapshot(holdings, sack, inventory, 120);
            session.observe(pickup, true);
            assertEquals(7000L, session.current().change);
            sack.beginTransfer(option, inventory, new Item[]{new Item(HERB, 5)}, 10);
            Item[] bank = {new Item(HERB, 6)};
            holdings.observeBank(bank, 130);
            assertTrue(option, sack.finishTransfer(inventory, bank, 12));
            Wealth.Snapshot deposited = snapshot(holdings, sack, inventory, 130);
            session.observe(deposited, true);
            assertEquals(option, pickup.total(), deposited.total());
            assertEquals(option, 7000L, session.current().change);
            assertTrue(sack.contents().isEmpty());
            assertFalse(sack.finishTransfer(inventory, bank, 13));
        }
    }

    @Test
    public void depositingLooseHerbsWhileCarryingSackDoesNotSubtractSackContents()
    {
        HerbSackTracker sack = checked(10);
        sack.beginTransfer("Deposit-All", new Item[]{SACK, new Item(HERB, 3)}, new Item[]{new Item(HERB, 5)}, 10);
        assertFalse(sack.finishTransfer(new Item[]{SACK}, new Item[]{new Item(HERB, 8)}, 12));
        assertEquals(10L, (long) sack.contents().get(HERB));
    }

    @Test
    public void filledSackInBankPersistsSeparateFromLooseBankHerbs()
    {
        HerbSackTracker sack = checked(10);
        HoldingsTracker holdings = new HoldingsTracker(id -> id, id -> false);
        holdings.observeBank(new Item[]{SACK, new Item(HERB, 5)}, 100);
        Wealth.Snapshot snapshot = snapshot(holdings, sack, EMPTY, 110);
        assertEquals(105_000L, snapshot.bank());
        assertEquals(10L, snapshot.items.get(HERB).bankSack);
        Wealth.State saved = Wealth.State.empty("test").withHerbSack(sack.contents()).append(snapshot, Collections.emptyMap())
            .withActiveSession(new Wealth.Session(100, 110, 0, false, false)).closeSession(false);
        Wealth.State loaded = WealthStore.decode("test", WealthStore.encode(saved));
        HerbSackTracker restored = new HerbSackTracker();
        restored.restore(loaded.herbSack);
        assertFalse(restored.confirmed()); // A new login may have missed changes in another client.
        HoldingsTracker restoredHoldings = new HoldingsTracker(id -> id, id -> false);
        restoredHoldings.restoreBank(loaded.bank);
        assertEquals(5L, (long) loaded.bank.quantities.get(HERB));
        assertEquals(snapshot.total(), snapshot(restoredHoldings, restored, EMPTY, 120).total());
        restoredHoldings.observeBank(new Item[]{new Item(HERB, 5)}, 130);
        assertEquals(snapshot.total(), snapshot(restoredHoldings, restored, new Item[]{SACK}, 130).total());
    }

    @Test
    public void firstCheckRebasesOnlyCorrectionAndPreservesPreviouslyMeasuredLoot()
    {
        HerbSackTracker sack = checked(2);
        HoldingsTracker holdings = new HoldingsTracker(id -> id, id -> false);
        holdings.observeBank(EMPTY, 100);
        SessionTracker session = new SessionTracker(100);
        session.observe(snapshot(holdings, sack, new Item[]{SACK}, 110), true);
        sack.chat("You put the Grimy ranarr weed herb into your herb sack.");
        session.observe(snapshot(holdings, sack, new Item[]{SACK}, 120), true);
        sack.chat("You look in your herb sack and see:");
        sack.chat("10 x Grimy ranarr weed");
        sack.finishCheck();
        session.observe(snapshot(holdings, sack, new Item[]{SACK}, 130), true, sack.takeReconciliation());
        assertEquals(7000L, session.current().change);
    }

    @Test
    public void cachedContentsWithoutOwnedSackAreExcludedAndAllVariantsSupported()
    {
        HerbSackTracker sack = checked(2);
        Map<Integer, long[]> holdings = new LinkedHashMap<>();
        assertTrue(sack.include(holdings).isEmpty());
        assertTrue(holdings.isEmpty());
        assertTrue(HerbSackTracker.isSack(ItemID.SLAYER_HERB_SACK));
        assertTrue(HerbSackTracker.isSack(ItemID.SLAYER_HERB_SACK_OPEN));
        assertTrue(HerbSackTracker.isSack(ItemID.SLAYER_HERB_SACK_SILK));
        assertTrue(HerbSackTracker.isSack(ItemID.SLAYER_HERB_SACK_SILK_OPEN));
        sack.invalidate();
        assertFalse(sack.confirmed());
    }
}

package com.atlas;

import java.util.Map;
import net.runelite.api.Item;
import org.junit.Test;
import static org.junit.Assert.*;

public class HoldingsTrackerTest
{
    private static final Item[] EMPTY = new Item[0];

    private HoldingsTracker tracker()
    {
        return new HoldingsTracker(id -> id, id -> false);
    }

    @Test
    public void equippingBowAfterClosingBankUpdatesLocationsWithoutLosingBankOrWealth()
    {
        HoldingsTracker tracker = tracker();
        // The bank is synced AFTER withdrawing the bow, then its live container becomes unavailable.
        tracker.observeBank(new Item[]{new Item(1, 20_000_000)}, 100);
        Map<Integer, long[]> carried = tracker.combine(new Item[]{new Item(2, 1)}, EMPTY);
        // No further bank observation. Equip the bow while walking away from the bank.
        Map<Integer, long[]> equipped = tracker.combine(EMPTY, new Item[]{new Item(2, 1)});
        assertNotNull(equipped);
        assertArrayEquals(new long[]{20_000_000, 0, 0}, equipped.get(1));
        assertArrayEquals(new long[]{0, 1, 0}, carried.get(2));
        assertArrayEquals(new long[]{0, 0, 1}, equipped.get(2));
        assertEquals(total(carried), total(equipped));
        assertEquals(124_000_000L, total(equipped));
        assertEquals(100L, tracker.getBankTime());
    }

    private long total(Map<Integer, long[]> counts)
    {
        return counts.entrySet().stream().mapToLong(e ->
            (e.getValue()[0] + e.getValue()[1] + e.getValue()[2]) * (e.getKey() == 1 ? 1 : 104_000_000L)).sum();
    }

    @Test
    public void swappingWeaponsOutsideBankIncludesTheWeaponReturnedToInventory()
    {
        HoldingsTracker tracker = tracker();
        tracker.observeBank(EMPTY, 100);
        Map<Integer, long[]> before = tracker.combine(new Item[]{new Item(2, 1)}, new Item[]{new Item(3, 1)});
        Map<Integer, long[]> after = tracker.combine(new Item[]{new Item(3, 1)}, new Item[]{new Item(2, 1)});
        assertArrayEquals(new long[]{0, 1, 0}, before.get(2));
        assertArrayEquals(new long[]{0, 0, 1}, after.get(2));
        assertArrayEquals(new long[]{0, 1, 0}, after.get(3));
        assertEquals(total(before), total(after));
    }

    @Test
    public void inventoryLootAndConsumptionUpdateAgainstUnchangedCachedBank()
    {
        HoldingsTracker tracker = tracker();
        tracker.observeBank(new Item[]{new Item(1, 100)}, 100);
        assertArrayEquals(new long[]{100, 50, 0}, tracker.combine(new Item[]{new Item(1, 50)}, EMPTY).get(1));
        assertArrayEquals(new long[]{100, 25, 0}, tracker.combine(new Item[]{new Item(1, 25)}, EMPTY).get(1));
        assertArrayEquals(new long[]{100, 0, 0}, tracker.combine(EMPTY, EMPTY).get(1));
    }

    @Test
    public void cachesCopyOfObservedBankAndAcceptsRealEmptyBankOnNextVisit()
    {
        HoldingsTracker tracker = tracker();
        Item[] mutable = {new Item(1, 50)};
        tracker.observeBank(mutable, 100);
        mutable[0] = new Item(1, 0);
        assertEquals(50L, tracker.combine(EMPTY, EMPTY).get(1)[0]);
        tracker.observeBank(null, 101);
        assertEquals(50L, tracker.combine(EMPTY, EMPTY).get(1)[0]);
        tracker.observeBank(EMPTY, 102);
        assertTrue(tracker.combine(EMPTY, EMPTY).isEmpty());
        assertEquals(102L, tracker.getBankTime());
    }

    @Test
    public void absentCarriedContainersKeepBankAndResetDoesNotReuseAnotherSessionsBank()
    {
        HoldingsTracker tracker = tracker();
        assertFalse(tracker.hasBank());
        assertTrue(tracker.combine(EMPTY, EMPTY).isEmpty());
        tracker.observeBank(new Item[]{new Item(1, 50)}, 100);
        assertArrayEquals(new long[]{50, 0, 0}, tracker.combine(null, EMPTY).get(1));
        assertArrayEquals(new long[]{50, 0, 0}, tracker.combine(null, null).get(1));
        assertArrayEquals(new long[]{50, 0, 0}, tracker.combine(EMPTY, null).get(1));
        tracker.reset();
        assertFalse(tracker.hasBank());
        assertTrue(tracker.combine(EMPTY, EMPTY).isEmpty());
        assertEquals(0L, tracker.getBankTime());
    }

    @Test
    public void unequippedLoginStartsSessionAndTracksLootBeforeFirstEquip()
    {
        HoldingsTracker tracker = tracker();
        tracker.restoreBank(new Wealth.Bank(90, java.util.Collections.singletonMap(1, 100L)));
        SessionTracker session = new SessionTracker(100);
        session.observe(snapshot(tracker.combine(new Item[]{new Item(1, 10), new Item(2, 1)}, null), 100), false);
        assertNotNull(session.current());
        assertEquals(0L, session.current().change);

        session.observe(snapshot(tracker.combine(new Item[]{new Item(1, 15), new Item(2, 1)}, null), 101), false);
        assertEquals(5L, session.current().change);

        session.observe(snapshot(tracker.combine(new Item[]{new Item(1, 15)},
            new Item[]{new Item(2, 1)}), 102), false);
        assertEquals(5L, session.current().change);
        session.observe(snapshot(tracker.combine(new Item[]{new Item(1, 15), new Item(2, 1)}, EMPTY), 103), false);
        assertEquals(5L, session.current().change);
    }

    @Test
    public void firstEverUnequippedLoginDoesNotRequireBankOrEquipment()
    {
        HoldingsTracker tracker = tracker();
        Map<Integer, long[]> current = tracker.combine(new Item[]{new Item(1, 500)}, null);
        assertFalse(tracker.hasBank());
        assertEquals(500L, total(current));
        assertTrue(tracker.combine(EMPTY, null).isEmpty());
        assertTrue(tracker.combine(null, null).isEmpty());
    }

    @Test
    public void nullEmptyAndPopulatedCarriedContainersWorkInEveryCombination()
    {
        Item[][] inventories = {null, EMPTY, {new Item(1, 5)}};
        Item[][] equipment = {null, EMPTY, {new Item(2, 1)}};
        for (boolean bankKnown : new boolean[]{false, true})
        {
            for (Item[] inventory : inventories)
            {
                for (Item[] worn : equipment)
                {
                    HoldingsTracker tracker = tracker();
                    if (bankKnown) { tracker.restoreBank(new Wealth.Bank(90, java.util.Collections.singletonMap(1, 100L))); }
                    Map<Integer, long[]> current = tracker.combine(inventory, worn);
                    long expected = (bankKnown ? 100 : 0) + (inventory != null && inventory.length > 0 ? 5 : 0)
                        + (worn != null && worn.length > 0 ? 104_000_000L : 0);
                    assertEquals(expected, total(current));
                    SessionTracker session = new SessionTracker(100);
                    session.observe(snapshot(current, 100), bankKnown);
                    assertNotNull(session.current());
                    assertEquals(0L, session.current().change);
                }
            }
        }
    }

    @Test
    public void equippedLoginWithAbsentInventoryStartsSessionBeforeFirstPickup()
    {
        HoldingsTracker tracker = tracker();
        tracker.restoreBank(new Wealth.Bank(90, java.util.Collections.singletonMap(1, 100L)));
        SessionTracker session = new SessionTracker(100);
        session.observe(snapshot(tracker.combine(null, new Item[]{new Item(2, 1)}), 100), false);
        assertNotNull(session.current());
        assertEquals(0L, session.current().change);
        session.observe(snapshot(tracker.combine(new Item[]{new Item(2, 1)}, EMPTY), 101), false);
        assertEquals(0L, session.current().change);
        session.observe(snapshot(tracker.combine(new Item[]{new Item(1, 5), new Item(2, 1)}, EMPTY), 102), false);
        assertEquals(5L, session.current().change);
    }

    @Test
    public void bothCarriedContainersAbsentStartSessionAndBankWithdrawalIsNeutral()
    {
        HoldingsTracker tracker = tracker();
        tracker.restoreBank(new Wealth.Bank(90, java.util.Collections.singletonMap(1, 100L)));
        SessionTracker session = new SessionTracker(100);
        session.observe(snapshot(tracker.combine(null, null), 100), false);
        assertNotNull(session.current());
        assertEquals(0L, session.current().change);
        tracker.observeBank(new Item[]{new Item(1, 75)}, 101);
        session.observe(snapshot(tracker.combine(new Item[]{new Item(1, 25)}, null), 101), true);
        assertEquals(0L, session.current().change);
        session.observe(snapshot(tracker.combine(new Item[]{new Item(1, 30)}, null), 102), true);
        assertEquals(5L, session.current().change);
        session.observe(snapshot(tracker.combine(null, null), 103), true);
        assertEquals(-25L, session.current().change);
    }

    @Test
    public void bothCarriedContainersAbsentAndBankUnknownTrackFirstLootFromZero()
    {
        HoldingsTracker tracker = tracker();
        SessionTracker session = new SessionTracker(100);
        session.observe(new Wealth.Snapshot(100, 0, snapshot(tracker.combine(null, null), 100).items), false);
        assertNotNull(session.current());
        assertEquals(0L, session.current().change);
        session.observe(new Wealth.Snapshot(101, 0, snapshot(tracker.combine(new Item[]{new Item(1, 5)}, null), 101).items), false);
        assertEquals(5L, session.current().change);
        assertFalse(tracker.hasBank());
    }

    private Wealth.Snapshot snapshot(Map<Integer, long[]> quantities, long time)
    {
        Map<Integer, Wealth.Entry> entries = new java.util.LinkedHashMap<>();
        quantities.forEach((id, q) -> entries.put(id, new Wealth.Entry(id, "Item " + id,
            q[0], q[1], q[2], id == 1 ? 1 : 104_000_000L, 1, false, true, false)));
        return new Wealth.Snapshot(time, 90, entries);
    }

    @Test
    public void notesPlaceholdersAndLargeMergedQuantitiesAreHandledInAllLocations()
    {
        HoldingsTracker tracker = new HoldingsTracker(id -> id == 2 ? 1 : id, id -> id == 3);
        tracker.observeBank(new Item[]{new Item(1, 2_000_000_000), new Item(3, 1)}, 100);
        Map<Integer, long[]> result = tracker.combine(new Item[]{new Item(2, 1_000_000_000), new Item(-1, 1)}, EMPTY);
        assertEquals(1, result.size());
        assertArrayEquals(new long[]{2_000_000_000L, 1_000_000_000L, 0}, result.get(1));
    }

    @Test
    public void loginRestoresOnlyBankAndImmediatelyUsesCurrentInventoryAndEquipment()
    {
        HoldingsTracker tracker = tracker();
        java.util.Map<Integer, Wealth.Entry> old = new java.util.LinkedHashMap<>();
        old.put(1, new Wealth.Entry(1, "Coins", 100, 25, 0, 1, 1, false, true, false));
        old.put(2, new Wealth.Entry(2, "Bow", 0, 1, 0, 104_000_000L, 1, true, true, false));
        Wealth.Snapshot previous = new Wealth.Snapshot(100, 90, old);
        tracker.restoreBank(Wealth.Bank.from(previous));
        Map<Integer, long[]> current = tracker.combine(new Item[]{new Item(1, 40)}, new Item[]{new Item(2, 1)});
        assertTrue(tracker.hasBank());
        assertArrayEquals(new long[]{100, 40, 0}, current.get(1));
        assertArrayEquals(new long[]{0, 0, 1}, current.get(2));
        assertEquals(104_000_140L, total(current));
        assertEquals(90L, tracker.getBankTime());
    }

    @Test
    public void firstEverLoginShowsCarriedHoldingsWhileBankRemainsUnknown()
    {
        HoldingsTracker tracker = tracker();
        tracker.restoreBank(null);
        Map<Integer, long[]> current = tracker.combine(new Item[]{new Item(1, 500)}, new Item[]{new Item(2, 1)});
        assertFalse(tracker.hasBank());
        assertEquals(0L, tracker.getBankTime());
        assertEquals(104_000_500L, total(current));
        assertArrayEquals(new long[]{0, 0, 1}, current.get(2));
    }

    @Test
    public void lateDiskLoadNeverReplacesBankAlreadyObservedThisSession()
    {
        HoldingsTracker tracker = tracker();
        tracker.observeBank(new Item[]{new Item(1, 100)}, 200);
        tracker.restoreBank(new Wealth.Bank(50, java.util.Collections.singletonMap(1, 500L)));
        assertEquals(100L, tracker.combine(EMPTY, EMPTY).get(1)[0]);
        assertEquals(200L, tracker.getBankTime());
    }
}

package com.atlas;

import com.google.gson.JsonObject;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;
import static org.junit.Assert.*;

public class RunePouchContentsTest
{
    private static final Item[] EMPTY = new Item[0];
    private static final int RUNE = ItemID.BLOODRUNE;

    private HoldingsTracker holdings()
    {
        HoldingsTracker tracker = new HoldingsTracker(id -> id, id -> false);
        tracker.observeBank(EMPTY, 100);
        return tracker;
    }

    private Wealth.Snapshot snapshot(HoldingsTracker tracker, long time, Item[] inventory, long pouchRunes)
    {
        Map<Integer, long[]> quantities = tracker.combine(inventory, EMPTY);
        Map<Integer, Long> bankPouch = RunePouchContents.include(quantities, Collections.singletonMap(RUNE, pouchRunes));
        Map<Integer, Wealth.Entry> entries = new LinkedHashMap<>();
        quantities.forEach((id, q) -> entries.put(id, new Wealth.Entry(id, "Item " + id, q[0], q[1], q[2],
            id == RUNE ? 149 : 0, 1, true, true, false, bankPouch.getOrDefault(id, 0L))));
        return new Wealth.Snapshot(time, tracker.getBankTime(), entries);
    }

    @Test
    public void movingOnePointFourNineMillionOfRunesIntoPouchIsNotALoss()
    {
        HoldingsTracker tracker = holdings();
        Item pouch = new Item(ItemID.BH_RUNE_POUCH, 1);
        Wealth.Snapshot loose = snapshot(tracker, 110, new Item[]{pouch, new Item(RUNE, 10_000)}, 0);
        Wealth.Snapshot inside = snapshot(tracker, 120, new Item[]{pouch}, 10_000);
        SessionTracker session = new SessionTracker(100);
        session.observe(loose, true);
        session.observe(inside, true);
        assertEquals(1_490_000L, inside.total());
        assertEquals(loose.total(), inside.total());
        assertEquals(0L, session.current().change);
        assertEquals(10_000L, inside.items.get(RUNE).inventory);
        session.observe(loose, true); // Emptying the pouch also preserves value.
        assertEquals(0L, session.current().change);
    }

    @Test
    public void consumingRunesWithoutChangingInventoryCountsAsASupplyLoss()
    {
        HoldingsTracker tracker = holdings();
        Item[] inventory = {new Item(ItemID.DIVINE_RUNE_POUCH, 1)};
        SessionTracker session = new SessionTracker(100);
        session.observe(snapshot(tracker, 110, inventory, 10_000), true);
        session.observe(snapshot(tracker, 120, inventory, 9990), true);
        assertEquals(-1490L, session.current().change);
    }

    @Test
    public void bankingPouchMovesItsContentsToBankWithoutChangingTotalOrSession()
    {
        HoldingsTracker tracker = holdings();
        Item pouch = new Item(ItemID.DIVINE_RUNE_POUCH_TROUVER, 1);
        Wealth.Snapshot carried = snapshot(tracker, 110, new Item[]{pouch}, 10_000);
        tracker.observeBank(new Item[]{pouch, new Item(RUNE, 500)}, 120);
        Wealth.Snapshot banked = snapshot(tracker, 120, EMPTY, 9500);
        SessionTracker session = new SessionTracker(100);
        session.observe(carried, true);
        session.observe(banked, true);
        assertEquals(carried.total(), banked.total());
        assertEquals(1_490_000L, banked.bank());
        assertEquals(0L, banked.inventory());
        assertEquals(0L, session.current().change);
        assertEquals(500L, (long) Wealth.Bank.from(banked).quantities.get(RUNE));
    }

    @Test
    public void reloadAndWithdrawBankedPouchNeverDuplicateItsRunes()
    {
        HoldingsTracker tracker = holdings();
        tracker.observeBank(new Item[]{new Item(ItemID.BH_RUNE_POUCH_TROUVER, 1), new Item(RUNE, 500)}, 120);
        Wealth.Snapshot banked = snapshot(tracker, 130, EMPTY, 9500);
        Wealth.State saved = Wealth.State.empty("test").append(banked, Collections.emptyMap());
        Wealth.State loaded = WealthStore.decode("test", WealthStore.encode(saved));
        assertEquals(9500L, loaded.latest.items.get(RUNE).bankPouch);
        HoldingsTracker restored = new HoldingsTracker(id -> id, id -> false);
        restored.restoreBank(loaded.bank);
        assertEquals(banked.total(), snapshot(restored, 140, EMPTY, 9500).total());
        restored.observeBank(new Item[]{new Item(RUNE, 500)}, 150);
        Wealth.Snapshot withdrawn = snapshot(restored, 150, new Item[]{new Item(ItemID.BH_RUNE_POUCH_TROUVER, 1)}, 9500);
        assertEquals(banked.total(), withdrawn.total());
        assertEquals(0L, withdrawn.items.get(RUNE).bankPouch);
    }

    @Test
    public void leftoverVarbitsDoNotCountRunesWithoutAnOwnedPouch()
    {
        assertEquals(0L, snapshot(holdings(), 120, EMPTY, 10_000).total());
    }

    @Test
    public void multiplePouchVariantsShareOneSetOfContentsWithCarriedPouchPreferred()
    {
        HoldingsTracker tracker = holdings();
        tracker.observeBank(new Item[]{new Item(ItemID.BH_RUNE_POUCH, 1)}, 100);
        Wealth.Snapshot snapshot = snapshot(tracker, 120, new Item[]{new Item(ItemID.DIVINE_RUNE_POUCH, 1)}, 10_000);
        assertEquals(1_490_000L, snapshot.total());
        assertEquals(1_490_000L, snapshot.inventory());
        assertEquals(0L, snapshot.bank());
    }

    @Test
    public void readsAllSixSlotsUsingRuneEnumAndMergesDuplicateTypes()
    {
        Map<Integer, Integer> varbits = new LinkedHashMap<>();
        varbits.put(VarbitID.RUNE_POUCH_TYPE_1, 7);
        varbits.put(VarbitID.RUNE_POUCH_QUANTITY_1, 400);
        varbits.put(VarbitID.RUNE_POUCH_TYPE_4, 7);
        varbits.put(VarbitID.RUNE_POUCH_QUANTITY_4, 600);
        varbits.put(VarbitID.RUNE_POUCH_TYPE_5, 8);
        varbits.put(VarbitID.RUNE_POUCH_QUANTITY_5, 100);
        varbits.put(VarbitID.RUNE_POUCH_TYPE_6, 9);
        varbits.put(VarbitID.RUNE_POUCH_QUANTITY_6, 200);
        Map<Integer, Long> runes = RunePouchContents.read(id -> varbits.getOrDefault(id, 0), type -> type + 1000);
        assertEquals(1000L, (long) runes.get(1007));
        assertEquals(100L, (long) runes.get(1008));
        assertEquals(200L, (long) runes.get(1009));
        assertEquals(3, runes.size());
        varbits.put(VarbitID.RUNE_POUCH_QUANTITY_1, 399);
        assertNotEquals(runes, RunePouchContents.read(id -> varbits.getOrDefault(id, 0), type -> type + 1000));
    }

    @Test
    public void ignoresEmptySlotsAndUnmappedRuneTypes()
    {
        assertTrue(RunePouchContents.read(id -> 0, type -> { fail("Empty slots must not look up runes"); return -1; }).isEmpty());
        assertTrue(RunePouchContents.read(id -> 1, type -> -1).isEmpty());
    }

    @Test
    public void legacySnapshotsWithoutPouchMetadataStillLoad()
    {
        HoldingsTracker tracker = holdings();
        tracker.observeBank(new Item[]{new Item(RUNE, 500)}, 100);
        Wealth.State state = Wealth.State.empty("test").append(snapshot(tracker, 120, EMPTY, 0), Collections.emptyMap());
        JsonObject json = WealthStore.encode(state);
        json.getAsJsonObject("snapshot").getAsJsonArray("entries").forEach(e -> e.getAsJsonObject().remove("bankPouch"));
        assertEquals(state.latest.total(), WealthStore.decode("test", json).latest.total());
    }
}

package com.atlas;

import com.google.gson.JsonObject;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

public class SessionTrackerTest
{
    @Test
    public void hourlyChangeUsesExactElapsedTimeForGainsLossesAndShortSessions()
    {
        long start = 1_000_000;
        Wealth.Session gain = new Wealth.Session(start, start + 29 * 60_000, 901_100, true, false);
        assertEquals(29 * 60_000, gain.elapsedMillis());
        assertEquals(1_864_345, gain.changePerHour());
        Wealth.Session loss = new Wealth.Session(start, start + 90 * 60_000, -4_100_000, false, false);
        assertEquals(-2_733_333, loss.changePerHour());
        assertEquals(60_000, new Wealth.Session(start, start + 30_000, 500, false, false).changePerHour());
        assertEquals(0, new Wealth.Session(start, start, 100, false, false).changePerHour());
        assertEquals(0, new Wealth.Session(start, start + 3_600_000, 0, false, false).changePerHour());
        // Scale without overflowing a long multiplication before division.
        assertEquals(10_000_000_000_000L,
            new Wealth.Session(start, start + 3_600_000, 10_000_000_000_000L, false, false).changePerHour());
    }

    private static Wealth.Entry item(int id, long bank, long inventory, long equipment, long price)
    {
        return new Wealth.Entry(id, "Item " + id, bank, inventory, equipment, price, 1, true, true, price == 0);
    }

    private static Wealth.Snapshot snapshot(long time, boolean bankKnown, Wealth.Entry... entries)
    {
        Map<Integer, Wealth.Entry> map = new LinkedHashMap<>();
        for (Wealth.Entry entry : entries) { map.put(entry.id, entry); }
        return new Wealth.Snapshot(time, bankKnown ? time : 0, map);
    }

    @Test
    public void twistedBowFallingFiftyMillionDoesNotHideSlayerSupplyLoss()
    {
        SessionTracker tracker = new SessionTracker(100);
        tracker.observe(snapshot(110, true, item(1, 1, 0, 0, 1_500_000_000), item(2, 0, 10_000, 0, 1000)), true);
        tracker.observe(snapshot(200, true, item(1, 1, 0, 0, 1_450_000_000), item(2, 0, 5900, 0, 1000)), true);
        assertEquals(-4_100_000L, tracker.current().change);
        assertEquals(100L, tracker.current().start);
        assertEquals(200L, tracker.current().end);
    }

    @Test
