        tracker.observe(snapshot(110, true, item(1, 1, 0, 0, 1_500_000_000)), true);
        tracker.observe(snapshot(200, true, item(1, 1, 0, 0, 1_450_000_000)), true);
        assertEquals(0L, tracker.current().change);
