        tracker.observe(snapshot(110, true, item(1, 1_000_000, 100, 0, 1)), false);
        tracker.observe(snapshot(120, true, item(1, 1_000_000, 150, 0, 1)), false);
        tracker.observe(snapshot(130, true, item(1, 500_150, 0, 0, 1)), true);
