        assertEquals(100L, model.row(2).start);
    }
}

package com.atlas;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class SoulBearerTrackerTest
{
    private static final int HEAD = ItemID.ARCEUUS_CORPSE_ABYSSAL;
    private static final int INITIAL = ItemID.ARCEUUS_CORPSE_ABYSSAL_INITIAL;
    private static final Item BEARER = new Item(ItemID.ARCEUUS_SOULBEARER, 1);
    private static final Item[] EMPTY = new Item[0];
    private static final Item[] CARRIED = {BEARER};

    private HoldingsTracker holdings()
    { return new HoldingsTracker(SoulBearerTracker::canonicalHead, id -> false); }

    private Wealth.Snapshot snapshot(HoldingsTracker bank, Item[] inventory, long time)
    {
        Map<Integer, Wealth.Entry> entries = new LinkedHashMap<>();
        bank.combine(inventory, EMPTY).forEach((id, q) -> entries.put(id,
            new Wealth.Entry(id, "Item", q[0], q[1], q[2],
                id == HEAD ? 3008 : id == ItemID.BLOODRUNE ? 300 : id == ItemID.SOULRUNE ? 443 : 0,
                0, true, true, id == BEARER.getId())));
        return new Wealth.Snapshot(time, bank.getBankTime(), entries);
    }

    private Map<Integer, Long> runeTransfer(long charges)
    {
        Map<Integer, Long> result = new LinkedHashMap<>();
        result.put(ItemID.BLOODRUNE, charges); result.put(ItemID.SOULRUNE, charges);
        return result;
    }

    @Test
    public void pickupThenSendPreservesHeadAndSubtractsOneChargeAtFixedPrices()
    {
        HoldingsTracker bank = holdings(); bank.observeBank(EMPTY, 100);
        SessionTracker session = new SessionTracker(100);
        session.observe(snapshot(bank, CARRIED, 100), true);
        Item[] head = {BEARER, new Item(INITIAL, 1)};
        session.observe(snapshot(bank, head, 110), true);
        assertEquals(3008, session.current().change);
        SoulBearerTracker bearer = new SoulBearerTracker();
        bearer.menu("Fill", BEARER.getId(), head, null, 10);
        assertEquals(0, bearer.finish(head, null, 11).spent());
        SoulBearerTracker.Result sent = bearer.finish(CARRIED, null, 12);
        assertEquals(1, sent.spent());
        bank.creditBank(sent.heads);
        session.spend(ItemID.BLOODRUNE, sent.spent(), 300);
        session.spend(ItemID.SOULRUNE, sent.spent(), 443);
        session.observe(snapshot(bank, CARRIED, 120), true);
        assertEquals(2265, session.current().change);
        assertEquals(3008, snapshot(bank, CARRIED, 120).bank());
        assertEquals(100, bank.getBankTime()); // Remote transfer is not a fresh whole-bank observation.
        assertEquals(0, bearer.finish(CARRIED, null, 13).spent());
        bank.observeBank(new Item[]{new Item(HEAD, 1)}, 130);
        session.observe(snapshot(bank, CARRIED, 130), true);
        assertEquals(2265, session.current().change);
        // A later price movement must not reprice the charge already booked this session.
        session.spend(ItemID.BLOODRUNE, 1, 1000); session.spend(ItemID.SOULRUNE, 1, 2000);
        assertEquals(1522, session.current().change);
    }

    @Test
    public void bulkSendCostsOneChargeForEachActuallyRemovedHead()
    {
        SoulBearerTracker bearer = new SoulBearerTracker();
        Item[] before = {BEARER, new Item(INITIAL, 2), new Item(ItemID.ARCEUUS_CORPSE_GOBLIN_INITIAL, 1)};
        bearer.menu("Fill", BEARER.getId(), before, null, 1);
        // Only enough charges for two heads: the remaining head must not be charged.
        SoulBearerTracker.Result result = bearer.finish(new Item[]{BEARER, new Item(INITIAL, 1)}, null, 2);
        assertEquals(2, result.spent());
        assertEquals(1L, (long) result.heads.get(HEAD));
        assertEquals(1L, (long) result.heads.get(ItemID.ARCEUUS_CORPSE_GOBLIN));
    }

    @Test
    public void itemUseWorksInEitherDirectionAndScopesTheSelectedHead()
    {
        for (boolean reverse : new boolean[]{false, true})
        {
            SoulBearerTracker bearer = new SoulBearerTracker();
            Item[] before = {BEARER, new Item(INITIAL, 1), new Item(ItemID.ARCEUUS_CORPSE_GOBLIN, 1)};
            bearer.use(reverse ? INITIAL : BEARER.getId(), reverse ? BEARER.getId() : INITIAL, before, null, 1);
            SoulBearerTracker.Result result = bearer.finish(CARRIED, null, 2);
            assertEquals(Collections.singletonMap(HEAD, 1L), result.heads);
        }
    }

    @Test
    public void failedCancelledExpiredAndOrdinaryBankDepositsBookNothing()
    {
        SoulBearerTracker bearer = new SoulBearerTracker();
        Item[] head = {BEARER, new Item(INITIAL, 1)};
        bearer.menu("Fill", BEARER.getId(), head, null, 1);
        assertEquals(0, bearer.finish(head, null, 2).spent()); // No charges/full bank/cancelled dialogue.
        bearer.menu("Drop", INITIAL, head, null, 3);
        assertEquals(0, bearer.finish(CARRIED, null, 4).spent());
        bearer.menu("Fill", BEARER.getId(), head, null, 5);
        assertEquals(0, bearer.finish(CARRIED, null, 106).spent());
        bearer.menu("Fill", BEARER.getId(), head, null, 110);
        assertEquals(0, bearer.finish(CARRIED, new Item[]{new Item(HEAD, 1)}, 111).spent());
        bearer.menu("Fill", BEARER.getId(), head, null, 120);
        assertEquals(0, bearer.finish(EMPTY, null, 121).spent()); // Lost bearer/death is not a send.
        bearer.menu("Fill", BEARER.getId(), head, null, 130);
        bearer.cancel(); // Logout/world hop.
        assertEquals(0, bearer.finish(CARRIED, null, 131).spent());
    }

    @Test
    public void initialAndBankableHeadFormsRemainTheSameHolding()
    {
        assertTrue(SoulBearerTracker.isHead(ItemID.ARCEUUS_CORPSE_HELLHOUND_INITIAL));
        assertTrue(SoulBearerTracker.isHead(ItemID.ARCEUUS_CORPSE_DRAGON));
        assertFalse(SoulBearerTracker.isHead(ItemID.BLOODRUNE));
        SoulBearerTracker bearer = new SoulBearerTracker();
        bearer.menu("Fill", BEARER.getId(), new Item[]{BEARER, new Item(INITIAL, 1)}, null, 1);
        // Conversion of an initial head in inventory alone is not a successful send.
        assertEquals(0, bearer.finish(new Item[]{BEARER, new Item(HEAD, 1)}, null, 2).spent());
    }

    @Test
    public void reanimationCancelsPendingSendAndDoesNotCreditTheConsumedHeadToBank()
    {
        SoulBearerTracker bearer = new SoulBearerTracker();
        Item[] head = {BEARER, new Item(INITIAL, 1)};
        bearer.menu("Fill", BEARER.getId(), head, null, 1);
        bearer.menu("Cast", -1, head, null, 2);
        assertEquals(0, bearer.finish(CARRIED, null, 3).spent());
    }

    @Test
    public void rechargingAndUnchargingAreTransfersRatherThanAdditionalSessionCosts()
    {
        HoldingsTracker bank = holdings(); bank.observeBank(EMPTY, 100);
        SoulBearerTracker bearer = new SoulBearerTracker();
        Item[] runes = {BEARER, new Item(ItemID.BLOODRUNE, 10), new Item(ItemID.SOULRUNE, 10)};
        SessionTracker session = new SessionTracker(100);
        session.observe(snapshot(bank, runes, 100), true);
        bearer.use(ItemID.BLOODRUNE, BEARER.getId(), runes, null, 1);
        SoulBearerTracker.Result loaded = bearer.finish(CARRIED, null, 5);
        assertEquals(10, loaded.chargeTransfer);
        session.observe(snapshot(bank, CARRIED, 110), true, false, runeTransfer(loaded.chargeTransfer));
        assertEquals(0, session.current().change);
        session.spend(ItemID.BLOODRUNE, 1, 300); session.spend(ItemID.SOULRUNE, 1, 443);
        session.observe(snapshot(bank, CARRIED, 120), true);
        assertEquals(-743, session.current().change);
        Item[] returned = {BEARER, new Item(ItemID.BLOODRUNE, 9), new Item(ItemID.SOULRUNE, 9)};
        bearer.menu("Uncharge", BEARER.getId(), CARRIED, null, 10);
        SoulBearerTracker.Result unloaded = bearer.finish(returned, null, 11);
        assertEquals(-9, unloaded.chargeTransfer);
        session.observe(snapshot(bank, returned, 130), true, false, runeTransfer(unloaded.chargeTransfer));
        assertEquals(-743, session.current().change);
    }

    @Test
    public void configuringBankChargesWaitsForBothRuneDeltasAndDoesNotCountWithdrawals()
    {
        SoulBearerTracker bearer = new SoulBearerTracker();
        Item[] bank = {BEARER, new Item(ItemID.BLOODRUNE, 10), new Item(ItemID.SOULRUNE, 10)};
        bearer.menu("Configure-Charges", BEARER.getId(), EMPTY, bank, 1);
        assertEquals(0, bearer.finish(new Item[]{new Item(ItemID.BLOODRUNE, 10)},
            new Item[]{BEARER, new Item(ItemID.SOULRUNE, 10)}, 2).chargeTransfer);
        assertEquals(0, bearer.finish(EMPTY,
            new Item[]{BEARER, new Item(ItemID.SOULRUNE, 10)}, 3).chargeTransfer);
        assertEquals(10, bearer.finish(EMPTY, new Item[]{BEARER}, 4).chargeTransfer);
        assertEquals(0, bearer.finish(EMPTY, new Item[]{BEARER}, 5).chargeTransfer);
    }

    @Test
    public void firstBankOrContainerReconciliationDoesNotTurnAChargeTransferIntoProfit()
    {
        HoldingsTracker bank = holdings();
        SessionTracker session = new SessionTracker(100);
        Item[] runes = {BEARER, new Item(ItemID.BLOODRUNE, 10), new Item(ItemID.SOULRUNE, 10)};
        session.observe(snapshot(bank, runes, 100), false);
        bank.observeBank(EMPTY, 110);
        session.spend(ItemID.BLOODRUNE, 1, 300); session.spend(ItemID.SOULRUNE, 1, 443);
        session.observe(snapshot(bank, CARRIED, 110), true, true, runeTransfer(10));
        assertEquals(-743, session.current().change);
    }

    @Test
    public void remoteBankCreditsSurviveRestartWithoutInventingAFullBankOrDuplicatingOnRefresh()
    {
        HoldingsTracker bank = holdings();
        bank.creditBank(Collections.singletonMap(HEAD, 1L));
        assertFalse(bank.hasBank()); assertNull(bank.bankSnapshot());
        assertEquals(3008, snapshot(bank, CARRIED, 100).total());
        Map<String, Map<Integer, Long>> extra = new LinkedHashMap<>();
        extra.put(SoulBearerTracker.REMOTE_BANK_KEY, bank.remoteBankSnapshot());
        Wealth.State state = Wealth.State.empty("fixture").withExtraContainers(extra);
        Wealth.State loaded = WealthStore.decode("fixture", WealthStore.encode(state));
        HoldingsTracker restarted = holdings();
        restarted.restoreRemoteBank(loaded.extraContainers.get(SoulBearerTracker.REMOTE_BANK_KEY));
        assertEquals(3008, snapshot(restarted, CARRIED, 110).total());
        restarted.observeBank(new Item[]{new Item(HEAD, 1)}, 120);
        assertTrue(restarted.hasBank()); assertTrue(restarted.remoteBankSnapshot().isEmpty());
        assertEquals(3008, snapshot(restarted, CARRIED, 120).total());
        restarted.restoreRemoteBank(Collections.singletonMap(HEAD, 1L));
        assertEquals(3008, snapshot(restarted, CARRIED, 130).total());
    }
}

package com.atlas;

import com.google.gson.Gson;
import com.google.inject.Guice;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Base64;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.zip.GZIPOutputStream;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class WealthSyncTest
{
    private final Gson gson = Guice.createInjector().getInstance(Gson.class);

    private Wealth.State state(long... rows)
    {
        List<Wealth.Point> points = new ArrayList<>();
        for (int i = 0; i < rows.length; i += 3)
        { points.add(new Wealth.Point(rows[i], rows[i + 1], 0, 1, rows[i + 2], rows[i + 1] - rows[1] - rows[i + 2])); }
        if (points.isEmpty()) { return Wealth.State.empty("fixture"); }
        Wealth.Point last = points.get(points.size() - 1);
        Map<Integer, Wealth.Entry> entries = Collections.singletonMap(ItemID.COINS,
            new Wealth.Entry(ItemID.COINS, "Coins", last.total, 0, 0, 1, 0, false, true, false));
        return new Wealth.State("fixture", new Wealth.Snapshot(last.time, last.time, entries), points, 1);
    }

    private String archive(Wealth.State state)
    { return gson.toJson(WealthStore.encode(state)); }

    @Test
    public void pcDeckPcRoundTripRetainsEverySessionAndGraphPointExactlyOnce() throws Exception
    {
        Wealth.State pc = state(100, 1000, 0, 200, 1100, 10)
            .withActiveSession(new Wealth.Session(100, 200, 90, false, false)).closeSession(false);
        Wealth.State deck = WealthSync.merge(Wealth.State.empty("fixture"),
            Collections.singletonList(WealthSync.decode(WealthSync.encode(pc, gson), "fixture", gson)), true);
        assertEquals(2, deck.history.size()); assertEquals(1, deck.sessions.size());
        assertEquals(1100, deck.bank.quantities.get(ItemID.COINS).longValue());
        deck = deck.append(new Wealth.Snapshot(300, 300,
            Collections.singletonMap(ItemID.COINS, new Wealth.Entry(ItemID.COINS, "Coins", 1200, 0, 0, 1, 0, false, true, false))),
            Collections.singletonMap(ItemID.COINS, 1L))
            .withActiveSession(new Wealth.Session(210, 300, 100, false, false)).closeSession(false);
        Wealth.State shared = WealthSync.decode(WealthSync.encode(deck, gson), "fixture", gson);
        Wealth.State returned = WealthSync.merge(pc, Arrays.asList(pc, shared, shared), true);
        assertEquals(3, returned.history.size()); assertEquals(2, returned.sessions.size());
        assertEquals(1200, returned.latest.total());
        assertEquals(10, returned.history.get(2).market);
        assertTrue(returned.history.get(2).attributed);
        Wealth.State again = WealthSync.merge(returned, Collections.singletonList(shared), true);
        assertEquals(returned.history.size(), again.history.size());
        assertEquals(returned.sessions.size(), again.sessions.size());
        assertEquals(returned.history.get(2).items, again.history.get(2).items);
        assertEquals(2, pc.history.size()); // The original local backup remains immutable.
        assertEquals(1, pc.sessions.size());
    }

    @Test
    public void offlineForksMergeInEitherOrderWithoutInventingMarketAttribution() throws Exception
    {
        Wealth.State pc = state(100, 1000, 0, 200, 1100, 10);
        Wealth.State deck = state(100, 1000, 0, 300, 1200, 20);
        Wealth.State merged = WealthSync.merge(pc, Collections.singletonList(deck), true);
        Wealth.State reverse = WealthSync.merge(deck, Collections.singletonList(pc), true);
        assertEquals(3, merged.history.size());
        assertTrue(merged.history.get(1).attributed);
        assertFalse(merged.history.get(2).attributed);
        assertEquals(10, merged.history.get(2).market);
        for (int i = 0; i < merged.history.size(); i++)
        {
            assertEquals(merged.history.get(i).time, reverse.history.get(i).time);
            assertEquals(merged.history.get(i).market, reverse.history.get(i).market);
            assertEquals(merged.history.get(i).attributed, reverse.history.get(i).attributed);
        }
        Wealth.State restored = WealthSync.decode(WealthSync.encode(merged, gson), "fixture", gson);
        assertFalse(restored.history.get(2).attributed);
        assertFalse(WealthSync.merge(restored, Arrays.asList(pc, deck), true).history.get(2).attributed);
    }

    @Test
    public void currentSessionStaysLocalWhileCompletedSessionsUseTheNewestFinalResult() throws Exception
    {
        Wealth.Session running = new Wealth.Session(400, 500, 50, false, false);
        Wealth.State local = state(100, 1000, 0).withActiveSession(running);
        Wealth.State stale = state(100, 1000, 0)
            .withActiveSession(new Wealth.Session(200, 250, 30, true, true)).closeSession(true);
        Wealth.State finalCopy = state(100, 1000, 0)
            .withActiveSession(new Wealth.Session(200, 300, 60, false, false)).closeSession(false);
        Wealth.State merged = WealthSync.merge(local, Arrays.asList(finalCopy, stale), true);
        assertSame(running, merged.activeSession);
        assertEquals(1, merged.sessions.size()); assertEquals(60, merged.sessions.get(0).change);
        assertFalse(merged.sessions.get(0).interrupted);
        Wealth.State exported = WealthSync.decode(WealthSync.encode(merged, gson), "fixture", gson);
        assertNull(exported.activeSession); assertEquals(1, exported.sessions.size());
        Wealth.State duplicate = local.withActiveSession(running).closeSession(false);
        assertEquals(0, WealthSync.merge(local, Collections.singletonList(duplicate), false).sessions.size());
    }

    @Test
    public void bankObservationTimeBeatsDeviceRevisionOrAnUnbankedLaterSession()
    {
        Wealth.State stale = state(100, 1000, 0)
            .withActiveSession(new Wealth.Session(300, 400, 10, false, false)).closeSession(false);
        Wealth.State fresh = state(200, 2000, 0);
        Wealth.State merged = WealthSync.merge(stale, Collections.singletonList(fresh), true);
        assertEquals(200, merged.bank.time);
        assertEquals(2000, merged.bank.quantities.get(ItemID.COINS).longValue());
        // Incoming history must not overwrite the bank currently being used by a running client.
        Wealth.State live = WealthSync.merge(stale, Collections.singletonList(fresh), false);
        assertSame(stale.bank, live.bank);
    }

    @Test
    public void unknownBankRemoteCreditsArePreservedWhenAFullOlderCheckpointArrives()
    {
        Wealth.State partial = Wealth.State.empty("fixture")
            .withExtraContainers(Collections.singletonMap(SoulBearerTracker.REMOTE_BANK_KEY,
                Collections.singletonMap(ItemID.ARCEUUS_CORPSE_ABYSSAL, 1L)))
            .withActiveSession(new Wealth.Session(200, 300, 0, true, false)).closeSession(false);
        Wealth.State merged = WealthSync.merge(partial, Collections.singletonList(state(100, 1000, 0)), true);
        assertEquals(1L, merged.bank.quantities.get(ItemID.ARCEUUS_CORPSE_ABYSSAL).longValue());
        assertTrue(merged.extraContainers.get(SoulBearerTracker.REMOTE_BANK_KEY).isEmpty());
    }

    @Test
    public void payloadCannotCrossCharactersOrAcceptCorruptOrNewerSchemaData() throws Exception
    {
        String valid = WealthSync.encode(state(100, 1000, 0), gson);
        expectDecodeFailure(valid, "another-character");
        expectDecodeFailure("not-base64", "fixture");
        ByteArrayOutputStream unknown = new ByteArrayOutputStream();
        try (GZIPOutputStream gzip = new GZIPOutputStream(unknown))
        { gzip.write("{\"syncSchema\":2}".getBytes(java.nio.charset.StandardCharsets.UTF_8)); }
        expectDecodeFailure(Base64.getEncoder().encodeToString(unknown.toByteArray()), "fixture");
        expectDecodeFailure(valid.substring(0, valid.length() - 8), "fixture");
        expectDecodeFailure(String.join("", Collections.nCopies(WealthSync.MAX_ENCODED + 1, "a")), "fixture");
        try
        {
            WealthSync.merge(state(100, 1000, 0), Collections.singletonList(Wealth.State.empty("other")), true);
            fail("Cross-character merge accepted");
        }
        catch (IllegalArgumentException expected) { }
    }

    @Test
    public void compactPayloadPreservesPouchBagCannonAndCachedContainerQuantities() throws Exception
    {
        Map<Integer, Wealth.Entry> entries = new LinkedHashMap<>();
        entries.put(ItemID.BLOODRUNE, new Wealth.Entry(ItemID.BLOODRUNE, "Blood rune", 20, 30, 0,
            300, 100, true, true, false, 5, 2, 0));
        entries.put(ItemID.TWPART1, new Wealth.Entry(ItemID.TWPART1, "Cannon base", 0, 0, 0,
            180_000, 100, true, true, false, 0, 0, 1));
        Map<String, Map<Integer, Long>> extra = new LinkedHashMap<>();
        extra.put(CannonTracker.STORAGE_KEY, Collections.singletonMap(ItemID.TWPART1, 1L));
        extra.put("SEED_BOX", Collections.singletonMap(ItemID.RANARR_SEED, 7L));
        Wealth.State original = Wealth.State.empty("fixture")
            .append(new Wealth.Snapshot(100, 100, entries), Collections.emptyMap())
            .withHerbSack(Collections.singletonMap(ItemID.UNIDENTIFIED_RANARR, 2L)).withExtraContainers(extra);
        Wealth.State restored = WealthSync.decode(WealthSync.encode(original, gson), "fixture", gson);
        Wealth.Entry rune = restored.latest.items.get(ItemID.BLOODRUNE);
        assertEquals(5, rune.bankPouch); assertEquals(2, rune.bankSack);
        assertEquals(13L, restored.bank.quantities.get(ItemID.BLOODRUNE).longValue());
        assertEquals(1, restored.latest.items.get(ItemID.TWPART1).deployed);
        assertEquals(original.latest.total(), restored.latest.total());
        assertEquals(original.extraContainers, restored.extraContainers);
        assertEquals(original.herbSack, restored.herbSack);
    }

    @Test
    public void decompressionIsBoundedEvenForASmallCompressedPayload() throws Exception
    {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (GZIPOutputStream gzip = new GZIPOutputStream(bytes)) { gzip.write(new byte[WealthSync.MAX_DECODED + 1]); }
        String bomb = Base64.getEncoder().encodeToString(bytes.toByteArray());
        assertTrue(bomb.length() < WealthSync.MAX_ENCODED);
        expectDecodeFailure(bomb, "fixture");
    }

    @Test
    public void exceedingTestBudgetRejectsExportWithoutTrimmingLocalData() throws Exception
    {
        Random random = new Random(42);
        List<Wealth.Point> points = new ArrayList<>();
        for (int i = 1; i < 5000; i++)
        { points.add(new Wealth.Point(i, random.nextInt(1_000_000_000), random.nextInt(1_000_000_000), 900, random.nextInt(1_000_000_000), random.nextInt(1_000_000_000))); }
        points.add(new Wealth.Point(5000, 1, 0, 1, 0, 0));
        Map<Integer, Wealth.Entry> entries = Collections.singletonMap(1,
            new Wealth.Entry(1, "Fixture", 1, 0, 0, 1, 0, true, true, false));
        Wealth.State large = new Wealth.State("fixture", new Wealth.Snapshot(5000, 5000, entries), points, 1);
        String before = archive(large);
        try { WealthSync.encode(large, gson); fail("Oversized export accepted"); }
        catch (IOException expected) { assertTrue(expected.getMessage().contains("size budget")); }
        assertEquals(before, archive(large));
    }

    @Test
    public void aRepresentativeBankAndDayOfHistoryFitsThePrototypeBudget() throws Exception
    {
        Map<Integer, Wealth.Entry> entries = new LinkedHashMap<>();
        for (int i = 1; i <= 900; i++)
        { entries.put(i, new Wealth.Entry(i, "Fixture item " + i, 10 + i, 0, 0, 100 + i, 50, true, true, false)); }
        List<Wealth.Point> points = new ArrayList<>();
        Wealth.Snapshot snapshot = new Wealth.Snapshot(288 * 300_000L, 288 * 300_000L, entries);
        for (int i = 1; i <= 288; i++)
        { points.add(new Wealth.Point(i * 300_000L, snapshot.total(), snapshot.alch(), 900, i * 7, -i * 7)); }
        Wealth.State fixture = new Wealth.State("fixture", snapshot, points, 1);
        String encoded = WealthSync.encode(fixture, gson);
        assertTrue(encoded.length() < WealthSync.MAX_ENCODED);
        Wealth.State decoded = WealthSync.decode(encoded, "fixture", gson);
        assertEquals(900, decoded.latest.items.size()); assertEquals(288, decoded.history.size());
        assertEquals(fixture.latest.total(), decoded.latest.total());
        System.out.println("Representative sync payload: " + encoded.length() + " characters (fixture only)");
    }

    private void expectDecodeFailure(String encoded, String profile) throws Exception
    {
        try { WealthSync.decode(encoded, profile, gson); fail("Invalid sync data accepted"); }
        catch (IOException expected) { }
    }
}

package com.atlas;

import com.google.gson.JsonObject;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

public class WealthTest
{
    private static Wealth.Entry item(int id, long bank, long inv, long equip, long price)
    {
        return new Wealth.Entry(id, "Item " + id, bank, inv, equip, price, price / 2, true, true, price == 0);
    }

    private static Wealth.Snapshot snapshot(long time, Wealth.Entry... entries)
    {
        Map<Integer, Wealth.Entry> map = new LinkedHashMap<>();
        for (Wealth.Entry entry : entries) { map.put(entry.id, entry); }
        return new Wealth.Snapshot(time, time, map);
    }

    @Test
    public void movingExpensiveGearBetweenBankInventoryAndEquipmentDoesNotChangeWealth()
    {
        Wealth.Snapshot bank = snapshot(1, item(1, 1, 0, 0, 300_000_000));
        Wealth.Snapshot inv = snapshot(2, item(1, 0, 1, 0, 300_000_000));
        Wealth.Snapshot worn = snapshot(3, item(1, 0, 0, 1, 300_000_000));
        Map<Integer, Long> quotes = Collections.singletonMap(1, 300_000_000L);
        Wealth.State state = Wealth.State.empty("test").append(bank, quotes).append(inv, quotes).append(worn, quotes);
        for (Wealth.Point point : state.history)
        {
            assertEquals(300_000_000L, point.total);
            assertEquals(0L, point.market);
            assertEquals(0L, point.items);
        }
    }

    @Test
    public void separatesPriceChangeFromAcquiringMoreItems()
    {
        Wealth.Snapshot first = snapshot(1, item(1, 10, 0, 0, 100));
        Wealth.Snapshot next = snapshot(2, item(1, 12, 0, 0, 120));
        Wealth.Point delta = Wealth.point(first, next, null, Collections.singletonMap(1, 120L));
        assertEquals(1440L, delta.total);
        assertEquals(200L, delta.market);
        assertEquals(240L, delta.items);
        assertEquals(next.total() - first.total(), delta.market + delta.items);
    }

    @Test
    public void saleUsesCurrentQuoteForItemNoLongerOwned()
    {
        Wealth.Snapshot first = snapshot(1, item(1, 1, 0, 0, 100));
        Wealth.Snapshot next = snapshot(2, item(2, 120, 0, 0, 1));
        Map<Integer, Long> quotes = new LinkedHashMap<>();
        quotes.put(1, 120L); quotes.put(2, 1L);
        Wealth.Point delta = Wealth.point(first, next, null, quotes);
        assertEquals(20L, delta.market);
        assertEquals(0L, delta.items);
    }

    @Test
    public void consumingOrLosingItemsIsNotMislabelledAsMarketLoss()
    {
        Wealth.Snapshot first = snapshot(1, item(1, 10, 0, 0, 100));
        Wealth.Snapshot next = snapshot(2, item(1, 7, 0, 0, 100));
        Wealth.Point delta = Wealth.point(first, next, null, Collections.singletonMap(1, 100L));
        assertEquals(0L, delta.market);
        assertEquals(-300L, delta.items);
    }

    @Test
    public void usesLongArithmeticForStacksAndNetWorth()
    {
        Wealth.Snapshot first = snapshot(1, item(1, 2_000_000_000L, 1_000_000_000L, 0, 1000));
        assertEquals(3_000_000_000_000L, first.total());
        Wealth.State state = Wealth.State.empty("test").append(first, Collections.singletonMap(1, 1000L));
        Wealth.State loaded = WealthStore.decode("test", WealthStore.encode(state));
        assertEquals(first.total(), loaded.latest.total());
        assertEquals(3_000_000_000L, loaded.latest.items.get(1).quantity());
    }

    @Test
    public void accountHistoryRoundTripRetainsAttributionAndLocationBreakdown()
    {
        Wealth.State state = Wealth.State.empty("account-a")
            .append(snapshot(1, item(1, 2, 1, 1, 100)), Collections.singletonMap(1, 100L))
            .append(snapshot(2, item(1, 1, 0, 3, 80)), Collections.singletonMap(1, 80L));
        Wealth.State loaded = WealthStore.decode("account-a", WealthStore.encode(state));
        assertEquals(state.revision, loaded.revision);
        assertEquals(2, loaded.history.size());
        assertEquals(80L, loaded.latest.bank());
        assertEquals(240L, loaded.latest.equipment());
        assertEquals(-80L, loaded.history.get(1).market);
        assertEquals(0L, loaded.history.get(1).items);
        assertNull(Wealth.State.empty("account-b").latest);
    }

    @Test(expected = IllegalArgumentException.class)
    public void rejectsUnknownHistorySchemaInsteadOfResettingAndOverwritingIt()
    {
        JsonObject object = new JsonObject(); object.addProperty("schema", 900);
        WealthStore.decode("test", object);
    }

    @Test
    public void missingPriceUsesPreviousQuoteForAttribution()
    {
        Wealth.Snapshot first = snapshot(1, item(1, 1, 0, 0, 500));
        Wealth.Snapshot next = snapshot(2, item(1, 1, 0, 0, 500));
        Wealth.Point delta = Wealth.point(first, next, null, Collections.emptyMap());
        assertEquals(0L, delta.market);
        assertEquals(0L, delta.items);
    }

    @Test
    public void newerBankCheckpointSurvivesRestartBeforeNextGraphSnapshot()
    {
        Wealth.State state = Wealth.State.empty("test").append(
            snapshot(100, item(1, 100, 0, 0, 1), item(2, 1, 0, 0, 104_000_000)),
            Collections.singletonMap(2, 104_000_000L));
        // Withdraw bow, then stop before the next graph snapshot. Only the bank checkpoint changes.
        state = state.withBank(new Wealth.Bank(200, Collections.singletonMap(1, 100L)));
        Wealth.State loaded = WealthStore.decode("test", WealthStore.encode(state));
        assertEquals(1, loaded.history.size());
        assertEquals(100L, loaded.latest.time);
        assertEquals(200L, loaded.bank.time);
        assertFalse(loaded.bank.quantities.containsKey(2));
        HoldingsTracker tracker = new HoldingsTracker(id -> id, id -> false);
        tracker.restoreBank(loaded.bank);
        Map<Integer, long[]> counts = tracker.combine(new net.runelite.api.Item[0],
            new net.runelite.api.Item[]{new net.runelite.api.Item(2, 1)});
        assertArrayEquals(new long[]{0, 0, 1}, counts.get(2));
    }

    @Test
    public void oldHistoryFilesCanRestoreBankWithoutImportingOldCarriedGear()
    {
        Wealth.State state = Wealth.State.empty("test").append(
            snapshot(100, item(1, 50, 20, 5, 1)), Collections.singletonMap(1, 1L));
        JsonObject legacy = WealthStore.encode(state);
        legacy.remove("bankCheckpoint");
        Wealth.State loaded = WealthStore.decode("test", legacy);
        assertEquals(Long.valueOf(50), loaded.bank.quantities.get(1));
        assertEquals(100L, loaded.bank.time);
    }

    @Test
    public void bankCheckpointCanBeSavedBeforeAnyHistoryExists()
    {
        Wealth.State state = Wealth.State.empty("test").withBank(
            new Wealth.Bank(100, Collections.singletonMap(1, 50L)));
        Wealth.State loaded = WealthStore.decode("test", WealthStore.encode(state));
        assertNull(loaded.latest);
        assertTrue(loaded.history.isEmpty());
        assertEquals(Long.valueOf(50), loaded.bank.quantities.get(1));
    }

    @Test(expected = IllegalArgumentException.class)
    public void unknownBankIsNeverRecordedAsZeroInNetWorthHistory()
    {
        Wealth.Snapshot partial = new Wealth.Snapshot(100, 0,
            Collections.singletonMap(1, item(1, 0, 500, 0, 1)));
        Wealth.State.empty("test").append(partial, Collections.singletonMap(1, 1L));
    }

    @Test
    public void finalOlderGraphSampleDoesNotOverwriteNewerBankCheckpoint()
    {
        Wealth.State state = Wealth.State.empty("test").withBank(
            new Wealth.Bank(200, Collections.singletonMap(1, 50L)));
        state = state.append(snapshot(150, item(1, 100, 0, 0, 1)), Collections.singletonMap(1, 1L));
        assertEquals(Long.valueOf(50), state.bank.quantities.get(1));
        assertEquals(200L, state.bank.time);
    }
}
